/**
 * Traços por nível das subclasses 2014 fora do SRD (XGE, TCE, SCAG, FToD, BGG, VRGR, EGW, MOoT…).
 * Só fatos: nome do traço e nível em que chega, com um resumo curto escrito por nós —
 * nenhum texto do livro. O motor (rules.js) espalha cada linha no nível certo da linha do tempo.
 *
 * Formato: classe → subclasse → [[nível, nomeEN, nomePT, resumoEN, resumoPT], …]
 */
import { CLASS_OPTIONS } from './class-options/index.js';

const F = {
  barbarian: {
    battlerager: [
      [3, 'Restriction: Dwarves Only', 'Restrição: Só Anões', "Only dwarves can follow the Path of the Battlerager. The battlerager fills a particular niche in dwarven society and culture. Your DM can lift this restriction to better suit the campaign. The restriction exists for the Forgotten Realms, and might not apply to your DM's setting or version of the Realms.", "Apenas anões podem seguir o Caminho do Furioso da Batalha. O furioso da batalha ocupa um nicho específico na sociedade e na cultura anã. Seu Mestre pode remover essa restrição para se adequar melhor à campanha. A restrição existe para os Forgotten Realms e pode não se aplicar ao cenário ou à versão dos Reinos do seu Mestre."],
      [3, 'Battlerager Armor', 'Armadura do Furioso', "When you choose this path at 3rd level, you gain the ability to use spiked armor as a weapon.\n\nWhile you are wearing spiked armor and are raging, you can use a bonus action to make one melee weapon attack with your armor spikes against a target within 5 feet of you. If the attack hits, the spikes deal 1d4 piercing damage. You use your Strength modifier for the attack and damage rolls.\n\nAdditionally, when you use the Attack action to grapple a creature, the target takes 3 piercing damage if your grapple check succeeds.", "Quando você escolhe este caminho no 3º nível, você ganha a capacidade de usar armadura com espinhos como uma arma.\n\nEnquanto estiver vestindo armadura com espinhos e em fúria, você pode usar uma ação bônus para desferir um ataque corpo a corpo com arma com os espinhos da sua armadura contra um alvo a até 1,5 metro de você. Se o ataque acertar, os espinhos causam 1d4 de dano perfurante. Você usa seu modificador de Força para as jogadas de ataque e dano.\n\nAlém disso, quando você usa a ação de Ataque para agarrar uma criatura, o alvo sofre 3 de dano perfurante se o seu teste para agarrar for bem-sucedido."],
      [6, 'Reckless Abandon', 'Abandono Imprudente', "Beginning at 6th level, when you use Reckless Attack while raging, you also gain temporary hit points equal to your Constitution modifier (minimum of 1). They vanish if any of them are left when your rage ends.", "A partir do 6º nível, quando você usa Ataque Descuidado enquanto está em fúria, você também ganha pontos de vida temporários iguais ao seu modificador de Constituição (mínimo de 1). Eles desaparecem se restar algum quando sua fúria terminar."],
      [10, 'Battlerager Charge', 'Investida do Furioso', "Beginning at 10th level, you can take the Dash action as a bonus action while you are raging.", "A partir do 10º nível, você pode realizar a ação Disparada como uma ação bônus enquanto estiver em fúria."],
      [14, 'Spiked Retribution', 'Retribuição Espinhosa', "Starting at 14th level, when a creature within 5 feet of you hits you with a melee attack, the attacker takes 3 piercing damage if you are raging, aren't incapacitated, and are wearing spiked armor.", "A partir do 14º nível, quando uma criatura a até 1,5 metro de você o atingir com um ataque corpo a corpo, o atacante sofre 3 de dano perfurante se você estiver em fúria, não estiver incapacitado e estiver vestindo armadura com espinhos."],
    ],
    ancestralguardian: [
      [3, 'Ancestral Protectors', 'Protetores Ancestrais', "Starting when you choose this path at 3rd level, spectral warriors appear when you enter your rage. While you’re raging, the first creature you hit with an attack on your turn becomes the target of the warriors, which hinder its attacks. Until the start of your next turn, that target has disadvantage on any attack roll that isn’t against you, and when the target hits a creature other than you with an attack, that creature has resistance to the damage dealt by the attack. The effect on the target ends early if your rage ends.", "A partir de quando você escolhe este caminho no 3º nível, guerreiros espectrais aparecem quando você entra em fúria. Enquanto estiver em fúria, a primeira criatura que você atingir com um ataque em seu turno torna-se o alvo dos guerreiros, que atrapalham os ataques dela. Até o início do seu próximo turno, aquele alvo tem desvantagem em qualquer jogada de ataque que não seja contra você e, quando o alvo atinge uma criatura que não seja você com um ataque, essa criatura tem resistência ao dano causado pelo ataque. O efeito no alvo termina mais cedo se a sua fúria terminar."],
      [6, 'Spirit Shield', 'Escudo Espiritual', "Beginning at 6th level, the guardian spirits that aid you can provide supernatural protection to those you defend. If you are raging and another creature you can see within 30 feet of you takes damage, you can use your reaction to reduce that damage by 2d6. When you reach certain levels in this class. you can reduce the damage by more: by 3d6 at 10th level and by 4d6 at 14th level.", "A partir do 6º nível, os espíritos guardiões que o auxiliam podem fornecer proteção sobrenatural àqueles que você defende. Se você estiver em fúria e outra criatura que possa ver a até 9 metros de você sofrer dano, você pode usar sua reação para reduzir esse dano em 2d6. Quando alcançar certos níveis nesta classe, poderá reduzir mais dano: em 3d6 no 10º nível e em 4d6 no 14º nível."],
      [10, 'Consult the Spirits', 'Consultar os Espíritos', "At 10th level, you gain the ability to consult with your ancestral spirits. When you do so, you cast the augury or clairvoyance spell, without using a spell slot or material components. Rather than creating a spherical sensor, this use of clairvoyance invisibly summons one of your ancestral spirits to the chosen location. Wisdom is your spellcasting ability for these spells. After you cast either spell in this way, you can’t use this feature again until you finish a short or long rest.", "No 10º nível, você ganha a habilidade de consultar seus espíritos ancestrais. Ao fazer isso, você conjura a magia augúrio ou clarividência, sem usar um espaço de magia ou componentes materiais. Em vez de criar um sensor esférico, esse uso de clarividência invoca invisivelmente um de seus espíritos ancestrais para o local escolhido. Sabedoria é a sua habilidade de conjuração para essas magias. Depois de conjurar qualquer uma das magias dessa forma, você não pode usar esta característica novamente até terminar um descanso curto ou longo."],
      [14, 'Vengeful Ancestors', 'Ancestrais Vingativos', "At 14th level, your ancestral spirits grow powerful enough to retaliate. When you use your Spirit Shield to reduce the damage of an attack, the attacker takes an amount of force damage equal to the damage that your Spirit Shield prevents.", "No 14º nível, seus espíritos ancestrais tornam-se poderosos o suficiente para retaliar. Quando você usa seu Escudo Espiritual para reduzir o dano de um ataque, o atacante sofre uma quantidade de dano de força igual ao dano que seu Escudo Espiritual previne."],
    ],
    stormherald: [
      [3, 'Storm Aura', 'Aura da Tempestade', "Starting at 3rd level, you emanate a stormy, magical aura while you rage. The aura extends 10 feet from you in every direction, but not through total cover.\n\nYour aura has an effect that activates when you enter your rage, and you can activate the effect again on each of your turns as a bonus action. Choose desert, sea, or tundra. Your aura’s effect depends on that chosen environment, as detailed below. You can change your environment choice whenever you gain a level in this class.\n\nIf your aura's effects require a saving throw, the DC equals 8 + your proficiency bonus + your Constitution modifier.\n\nDesert. When this effect is activated, all other creatures in your aura take 2 fire damage each. The damage increases when you reach certain levels in this class, increasing to 3 at 5th level, 4 at 10th level, 5 at 15th level, and 6 at 20th level.\n\nSea. When this effect is activated, you can choose one other creature you can see in your aura. The target must make a Dexterity saving throw. The target takes 1d6 lightning damage on a failed save, or half as much damage on a successful one. The damage increases when you reach certain levels in this class, increasing to 2d6 at 10th level, 3d6 at 15th level, and 4d6 at 20th level.\n\nTundra. When this effect is activated, each creature of your choice in your aura gains 2 temporary hit points, as icy spirits inure it to suffering. The temporary hit points increase when you reach certain levels in this class, increasing to 3 at 5th level, 4 at 10th level, 5 at 15th level, and 6 at 20th level.", "A partir do 3º nível, você emana uma aura tempestuosa e mágica enquanto estiver em fúria. A aura se estende por 3 metros a partir de você em todas as direções, mas não através de cobertura total.\n\nSua aura tem um efeito que se ativa quando você entra em fúria, e você pode ativar o efeito novamente em cada um dos seus turnos como uma ação bônus. Escolha deserto, mar ou tundra. O efeito da sua aura depende do ambiente escolhido, conforme detalhado abaixo. Você pode mudar sua escolha de ambiente sempre que ganhar um nível nesta classe.\n\nSe os efeitos da sua aura exigirem uma salvaguarda, a CD é igual a 8 + seu bônus de proficiência + seu modificador de Constituição.\ns ação. Escolha deserto, mar ou tundra. O efeito da sua aura depende do ambiente escolhido, conforme detalhado abaixo. Você pode mudar sua escolha de ambiente sempre que ganhar um nível nesta classe.\n\nSe os efeitos da sua aura exigirem uma salvaguarda, a CD é igual a 8 + seu bônus de proficiência + seu modificador de Constituição.\n\nDeserto. Quando este efeito for ativado, todas as outras criaturas em sua aura sofrem 2 de dano de fogo cada. O dano aumenta quando você alcança certos níveis nesta classe, aumentando para 3 no 5º nível, 4 no 10º nível, 5 no 15º nível e 6 no 20º nível.\n\nMar. Quando este efeito for ativado, você pode escolher uma outra criatura que possa ver em sua aura. O alvo deve fazer uma salvaguarda de Destreza. O alvo sofre 1d6 de dano elétrico se falhar na salvaguarda, ou metade desse dano se tiver sucesso. O dano aumenta quando você alcança certos níveis nesta classe, aumentando para 2d6 no 10º nível, 3d6 no 15º nível e 4d6 no 20º nível.\n\nTundra. Quando este efeito for ativado, cada criatura de sua escolha em sua aura ganha 2 pontos de vida temporários, conforme espíritos gélidos a acostumam ao sofrimento. Os pontos de vida temporários aumentam quando você alcança certos níveis nesta classe, aumentando para 3 no 5º nível, 4 no 10º nível, 5 no 15º nível e 6 no 20º nível."],
      [6, 'Storm Soul', 'Alma da Tempestade', "At 6th level, the storm grants you benefits even when your aura isn’t active. The benefits are based on the environment you chose for your Storm Aura.\n\nDesert. You gain resistance to fire damage, and you don’t suffer the effects of extreme heat, as described in the Dungeon Master’s Guide. Moreover, as an action, you can touch a flammable object that isn’t being worn or carried by anyone else and set it on fire.\n\nSea. You gain resistance to lightning damage, and you can breathe underwater. You also gain a swimming speed of 30 feet.\n\nTundra. You gain resistance to cold damage, and you don’t suffer the effects of extreme cold, as described in the Dungeon Master’s Guide. Moreover, as an action, you can touch water and turn a 5-foot cube Of it into ice, which melts after 1 minute. This action fails if a creature is in the cube.", "No 6º nível, a tempestade concede a você benefícios mesmo quando sua aura não estiver ativa. Os benefícios são baseados no ambiente que você escolheu para sua Aura de Tempestade.\n\nDeserto. Você ganha resistência a dano de fogo e não sofre os efeitos de calor extremo, conforme descrito no Guia do Mestre. Além disso, como uma ação, você pode tocar um objeto inflamável que não esteja sendo vestido ou carregado por ninguém e incendiá-lo.\n\nMar. Você ganha resistência a dano elétrico e pode respirar sob a água. Você também ganha um deslocamento de natação de 9 metros.\n\nTundra. Você ganha resistência a dano de frio e não sofre os efeitos de frio extremo, conforme descrito no Guia do Mestre. Além disso, como uma ação, você pode tocar na água e transformar um cubo de 1,5 metro dela em gelo, que derrete após 1 minuto. Esta ação falha se houver uma criatura dentro do cubo."],
      [10, 'Shielding Storm', 'Tempestade Protetora', "At 10th level, you learn to use your mastery of the storm to protect others. Each creature of your choice has the damage resistance you gained from the Storm Soul feature while the creature is in your Storm Aura.", "No 10º nível, você aprende a usar seu domínio sobre a tempestade para proteger outros. Cada criatura à sua escolha tem a resistência a dano que você obteve da característica Alma da Tempestade enquanto a criatura estiver na sua Aura de Tempestade."],
      [14, 'Raging Storm', 'Tempestade Furiosa', "At 14th level, the power of the storm you channel grows mightier, lashing out at your foes. The effect is based on the environment you chose for your Storm Aura.\n\nDesert. Immediately after a creature in your aura hits you with an attack, you can use your reaction to force that creature to make a Dexterity saving throw. On a failed save, the creature takes fire damage equal to half your barbarian level.\n\nSea. When you hit a creature in your aura with an attack, you can use your reaction to force that creature to make a Strength saving throw. On a failed save, the creature is knocked prone, as if struck by a wave.\n\nTundra. Whenever the effect of your Storm Aura is activated, you can choose one creature you can see in the aura. That creature must succeed on a Strength saving throw, or its speed is reduced to 0 until the start of your next turn, as magical frost covers it.", "No 14º nível, o poder da tempestade que você canaliza se torna ainda mais poderoso, açoitando seus inimigos. O efeito é baseado no ambiente que você escolheu para a sua Aura de Tempestade.\n\nDeserto. Imediatamente após uma criatura na sua aura acertar você com um ataque, você pode usar sua reação para forçar aquela criatura a fazer uma salvaguarda de Destreza. Se falhar na salvaguarda, a criatura sofre dano de fogo igual à metade do seu nível de bárbaro.\n\nMar. Quando você acertar uma criatura na sua aura com um ataque, você pode usar sua reação para forçar aquela criatura a fazer uma salvaguarda de Força. Se falhar na salvaguarda, a criatura é derrubada e fica caída, como se tivesse sido atingida por uma onda.\n\nTundra. Sempre que o efeito da sua Aura de Tempestade for ativado, você pode escolher uma criatura que possa ver na aura. Essa criatura deve ser bem-sucedida em uma salvaguarda de Força, ou seu deslocamento é reduzido a 0 até o início do seu próximo turno, enquanto uma geada mágica a cobre."],
    ],
    zealot: [
      [3, 'Divine Fury', 'Fúria Divina', "Starting when you choose this path at 3rd level, you can channel divine fury into your weapon strikes. While you’re raging, the first creature you hit on each of your turns with a weapon attack takes extra damage equal to 1d6 + half your barbarian level. The extra damage is necrotic or radiant; you choose the type of damage when you gain this feature.", "A partir do momento em que escolhe este caminho no 3º nível, você pode canalizar fúria divina nos seus golpes com arma. Enquanto estiver em fúria, a primeira criatura que você atingir em cada um dos seus turnos com um ataque com arma sofre dano extra igual a 1d6 + metade do seu nível de bárbaro. O dano extra é necrótico ou radiante; você escolhe o tipo de dano quando obtém esta característica."],
      [3, 'Warrior of the Gods', 'Guerreiro dos Deuses', "At 3rd level, your soul is marked for endless battle. If a spell, such as raise dead, has the sole effect of restoring you to life (but not undeath), the caster doesn’t need material components to cast the spell on you.", "No 3º nível, sua alma é marcada para o combate sem fim. Se uma magia, como reviver os mortos, tiver como único efeito trazê-lo de volta à vida (mas não como um morto-vivo), o conjurador não precisa de componentes materiais para conjurar a magia em você."],
      [6, 'Fanatical Focus', 'Foco Fanático', "Starting at 6th level, the divine power that fuels your rage can protect you. If you fail a saving throw while you’re raging, you can reroll it, and you must use the new roll. You can use this ability only once per rage.", "A partir do 6º nível, o poder divino que abastece sua fúria pode proteger você. Se você falhar em uma salvaguarda enquanto estiver em fúria, poderá rolá-la novamente e deverá usar a nova rolagem. Você pode usar esta habilidade apenas uma vez por fúria."],
      [10, 'Zealous Presence', 'Presença Zelosa', "At 10th level, you learn to channel divine power to inspire zealotry in others. As a bonus action, you unleash a battle cry infused with divine energy. Up to ten other creatures of your choice within 60 feet of you that can hear you gain advantage on attack rolls and saving throws until the start of your next turn. Once you use this feature, you can’t use it again until you finish a long rest.", "No 10º nível, você aprende a canalizar poder divino para inspirar fanatismo nos outros. Com uma ação bônus, você solta um brado de batalha impregnado de energia divina. Até dez outras criaturas à sua escolha a até 18 metros de você que possam ouvi-lo ganham vantagem em jogadas de ataque e salvaguardas até o início do seu próximo turno. Depois de usar esta característica, você não pode usá-la novamente até terminar um descanso longo."],
      [14, 'Rage Beyond Death', 'Fúria Além da Morte', "Beginning at 14th level, the divine power that fuels your rage allows you to shrug off fatal blows. While you’re raging, having 0 hit points doesn’t knock you unconscious. You still must make death saving throws, and you suffer the normal effects of taking damage while at 0 hit points. However, if you would die due to failing death saving throws, you don't die until your rage ends, and you die then only if you still have 0 hit points.", "A partir do 14º nível, o poder divino que abastece sua fúria permite que você ignore golpes fatais. Enquanto estiver em fúria, ter 0 pontos de vida não deixa você inconsciente. Você ainda precisa fazer salvaguardas contra a morte e sofre os efeitos normais de receber dano enquanto estiver com 0 pontos de vida. No entanto, se você fosse morrer por falhar em salvaguardas contra a morte, você não morre até que sua fúria termine, e só morrerá então se ainda tiver 0 pontos de vida."],
    ],
    beast: [
      [3, 'Form of the Beast', 'Forma da Fera', "3rd-level Path of the Beast feature\n\nWhen you enter your rage, you can transform, revealing the bestial power within you. Until the rage ends, you manifest a natural weapon. It counts as a simple melee weapon for you, and you add your Strength modifier to the attack and damage rolls when you attack with it, as normal.\n\nYou choose the weapon’s form each time you rage:\n\nBite. Your mouth transforms into a bestial muzzle or great mandibles (your choice). It deals 1d8 piercing damage on a hit. Once on each of your turns when you damage a creature with this bite, you regain a number of hit points equal to your proficiency bonus, provided you have less than half your hit points when you hit.\n\nClaws. Each of your hands transforms into a claw, which you can use as a weapon if it’s empty. It deals 1d6 slashing damage on a hit. Once on each of your turns when you attack with a claw using the Attack action, you can make one additional claw attack as part of the same action.\n\nTail. You grow a lashing, spiny tail, which deals 1d8 piercing damage on a hit and has the reach property. If a creature you can see within 10 feet of you hits you with an attack roll, you can use your reaction to swipe your tail and roll a d8, applying a bonus to your AC equal to the number rolled, potentially causing the attack to miss you.", "Característica de 3º nível do Caminho da Besta\n\nQuando você entra em fúria, pode se transformar, revelando o poder bestial dentro de você. Até a fúria terminar, você manifesta uma arma natural. Ela conta como uma arma corpo a corpo simples para você, e você adiciona seu modificador de Força às jogadas de ataque e dano quando ataca com ela, como de costume.\n\nVocê escolhe a forma da arma cada vez que entra em fúria:\ntrar em fúria, você pode se transformar, revelando o poder bestial dentro de você. Até a fúria terminar, você manifesta uma arma natural. Ela conta como uma arma corpo a corpo simples para você, e você adiciona seu modificador de Força às jogadas de ataque e dano quando ataca com ela, como de costume.\n\nVocê escolhe a forma da arma cada vez que entra em fúria:\n\nMordida. Sua boca se transforma em um focinho bestial ou em grandes mandíbulas (à sua escolha). Ela causa 1d8 de dano perfurante ao acertar. Uma vez em cada um de seus turnos, ao causar dano a uma criatura com esta mordida, você recupera um número de pontos de vida igual ao seu bônus de proficiência, desde que tenha menos da metade dos seus pontos de vida ao acertar.\n\nGarras. Cada uma de suas mãos se transforma em uma garra, que você pode usar como arma se ela estiver vazia. Ela causa 1d6 de dano cortante ao acertar. Uma vez em cada um de seus turnos, ao atacar com uma garra usando a ação de Ataque, você pode realizar um ataque adicional com garra como parte da mesma ação.\n\nCauda. Você desenvolve uma cauda chicoteante e espinhosa, que causa 1d8 de dano perfurante ao acertar e possui a propriedade alcance. Se uma criatura que você possa ver a até 3 metros de você atingir você com uma jogada de ataque, você pode usar sua reação para golpear com sua cauda e rolar um d8, aplicando um bônus à sua CA igual ao número rolado, potencialmente fazendo com que o ataque erre você."],
      [6, 'Bestial Soul', 'Alma Bestial', "6th-level Path of the Beast feature\n\nThe feral power within you increases, causing the natural weapons of your Form of the Beast to count as magical for the purpose of overcoming resistance and immunity to nonmagical attacks and damage.\n\nYou can also alter your form to help you adapt to your surroundings. When you finish a short or long rest, choose one of the following benefits, which lasts until you finish a short or long rest:\n\n• You gain a swimming speed equal to your walking speed, and you can breathe underwater.\n\n• You gain a climbing speed equal to your walking speed, and you can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check.\n\n• When you jump, you can make a Strength (Athletics) check and extend your jump by a number of feet equal to the check’s total. You can make this special check only once per turn.", "Característica de 6º nível do Caminho da Besta\n\nO poder feral dentro de você aumenta, fazendo com que as armas naturais da sua Forma da Besta contem como mágicas com o propósito de superar resistência e imunidade a ataques e dano não mágicos.\n\nVocê também pode alterar sua forma para ajudá-lo a se adaptar aos seus arredores. Ao terminar um descanso curto ou longo, escolha um dos seguintes benefícios, que dura até você terminar um descanso curto ou longo:\n\n• Você ganha um deslocamento de natação igual ao seu deslocamento de caminhada e pode respirar debaixo d'água.\n\n• Você ganha um deslocamento de escalada igual ao seu deslocamento de caminhada e pode escalar superfícies difíceis, inclusive de cabeça para baixo em tetos, sem precisar fazer um teste de atributo.\n\n• Quando você salta, pode fazer um teste de Força (Atletismo) e estender seu salto por uma distância em metros igual ao total do teste dividido por 3. Você pode fazer este teste especial apenas uma vez por turno."],
      [10, 'Infectious Fury', 'Fúria Contagiosa', "10th-level Path of the Beast feature\n\nWhen you hit a creature with your natural weapons while you are raging, the beast within you can curse your target with rabid fury. The target must succeed on a Wisdom saving throw (DC equal to 8 + your Constitution modifier + your proficiency bonus) or suffer one of the following effects (your choice):\n\n• The target must use its reaction to make a melee attack against another creature of your choice that you can see.\n\n• The target takes 2d12 psychic damage.\n\nYou can use this feature a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.", "Característica de 10º nível do Caminho da Besta\n\nQuando você atinge uma criatura com suas armas naturais enquanto estiver em fúria, a besta dentro de você pode amaldiçoar seu alvo com fúria raivosa. O alvo deve ser bem-sucedido em uma salvaguarda de Sabedoria (CD igual a 8 + seu modificador de Constituição + seu bônus de proficiência) ou sofrer um dos seguintes efeitos (à sua escolha):\n\n• O alvo deve usar a reação dele para realizar um ataque corpo a corpo contra outra criatura à sua escolha que você possa ver.\n\n• O alvo sofre 2d12 de dano psíquico.\n\nVocê pode usar esta característica um número de vezes igual ao seu bônus de proficiência e recupera todos os usos gastos ao terminar um descanso longo."],
      [14, 'Call the Hunt', 'Chamado da Caçada', "14th-level Path of the Beast feature\n\nThe beast within you grows so powerful that you can spread its ferocity to others and gain resilience from them joining your hunt. When you enter your rage, you can choose a number of other willing creatures you can see within 30 feet of you equal to your Constitution modifier (minimum of one creature).\n\nYou gain 5 temporary hit points for each creature that accepts this feature. Until the rage ends, the chosen creatures can use the following benefit once on each of their turns: when the creature hits a target with an attack roll and deals damage to it, the creature can roll a d6 and gain a bonus to the damage equal to the number rolled.\n\nYou can use this feature a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.", "Característica de 14º nível do Caminho da Besta\n\nA besta dentro de você se torna tão poderosa que você pode espalhar sua ferocidade para outros e obter resiliência ao se juntarem à sua caçada. Quando entra em sua fúria, você pode escolher um número de outras criaturas voluntárias que possa ver a até 9 metros de você igual ao seu modificador de Constituição (mínimo de uma criatura).\n\nVocê ganha 5 pontos de vida temporários para cada criatura que aceitar esta característica. Até a fúria terminar, as criaturas escolhidas podem usar o seguinte benefício uma vez em cada um de seus turnos: quando a criatura atingir um alvo com uma jogada de ataque e causar dano a ele, ela pode rolar um d6 e ganhar um bônus no dano igual ao número rolado.\n\nVocê pode usar esta característica um número de vezes igual ao seu bônus de proficiência e recupera todos os usos gastos ao terminar um descanso longo."],
    ],
    wildmagic: [
      [3, 'Magic Awareness', 'Percepção Mágica', "3rd-level Path of Wild Magic feature\n\nAs an action, you can open your awareness to the presence of concentrated magic. Until the end of your next turn, you know the location of any spell or magic item within 60 feet of you that isn’t behind total cover. When you sense a spell, you learn which school of magic it belongs to.\n\nYou can use this feature a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.", "Característica de 3º nível do Caminho da Magia Selvagem\n\nComo uma ação, você pode abrir sua percepção para a presença de magia concentrada. Até o final do seu próximo turno, você sabe a localização de qualquer magia ou item mágico a até 18 metros de você que não esteja atrás de cobertura total. Quando você pressente uma magia, você descobre a qual escola de magia ela pertence.\n\nVocê pode usar esta característica um número de vezes igual ao seu bônus de proficiência, e você recupera todos os usos gastos quando termina um descanso longo."],
      [3, 'Wild Surge', 'Surto Selvagem', "3rd-level Path of Wild Magic feature\n\nThe magical energy rolling inside you sometimes erupts from you. When you enter your rage, roll on the Wild Magic table to determine the magical effect produced.\n\nIf the effect requires a saving throw, the DC equals 8 + your proficiency bonus + your Constitution modifier.", "Característica de 3º nível do Caminho da Magia Selvagem\n\nA energia mágica que se agita dentro de você às vezes irrompe de você. Quando você entra em sua fúria, role na tabela Magia Selvagem para determinar o efeito mágico produzido.\n\nSe o efeito exigir uma salvaguarda, a CD é igual a 8 + seu bônus de proficiência + seu modificador de Constituição."],
      [6, 'Bolstering Magic', 'Magia Fortalecedora', "6th-level Path of Wild Magic feature\n\nYou can harness your wild magic to bolster yourself or a companion. As an action, you can touch one creature (which can be yourself) and confer one of the following benefits of your choice to that creature:\n\n• For 10 minutes, the creature can roll a d3 whenever making an attack roll or an ability check and add the number rolled to the d20 roll.\n\n• Roll a d3. The creature regains one expended spell slot, the level of which equals the number rolled or lower (the creature’s choice). Once a creature receives this benefit, that creature can’t receive it again until after a long rest.\n\nYou can take this action a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.", "Característica de 6º nível do Caminho da Magia Selvagem\n\nVocê pode canalizar sua magia selvagem para fortalecer a si mesmo ou a um companheiro. Como uma ação, você pode tocar uma criatura (que pode ser você mesmo) e conceder um dos seguintes benefícios à sua escolha para aquela criatura:\n\n• Por 10 minutos, a criatura pode rolar um d3 sempre que fizer uma jogada de ataque ou um teste de atributo e adicionar o número rolado à jogada do d20.\n\n• Role um d3. A criatura recupera um espaço de magia gasto, cujo círculo seja igual ou inferior ao número rolado (à escolha da criatura). Uma vez que uma criatura receba este benefício, ela não pode recebê-lo novamente até após um descanso longo.\n\nVocê pode realizar esta ação um número de vezes igual ao seu bônus de proficiência, e você recupera todos os usos gastos quando termina um descanso longo."],
      [10, 'Unstable Backlash', 'Reação Instável', "10th-level Path of Wild Magic feature\n\nWhen you are imperiled during your rage, the magic within you can lash out; immediately after you take damage or fail a saving throw while raging, you can use your reaction to roll on the Wild Magic table and immediately produce the effect rolled. This effect replaces your current Wild Magic effect.", "Característica de 10º nível do Caminho da Magia Selvagem\n\nQuando você estiver em perigo durante a sua fúria, a magia dentro de você pode se libertar abruptamente; imediatamente após sofrer dano ou falhar em uma salvaguarda enquanto estiver em fúria, você pode usar sua reação para rolar na tabela de Magia Selvagem e produzir imediatamente o efeito rolado. Esse efeito substitui o seu efeito atual de Magia Selvagem."],
      [14, 'Controlled Surge', 'Surto Controlado', "14th-level Path of Wild Magic feature\n\nWhenever you roll on the Wild Magic table, you can roll the die twice and choose which of the two effects to unleash. If you roll the same number on both dice, you can ignore the number and choose any effect on the table.", "Característica de 14º nível do Caminho da Magia Selvagem\n\nSempre que rolar na tabela de Magia Selvagem, você pode rolar o dado duas vezes e escolher qual dos dois efeitos deseja liberar. Se rolar o mesmo número em ambos os dados, você pode ignorar o número e escolher qualquer efeito na tabela."],
    ],
    giant: [
      [3, 'Giant\'s Power', 'Poder do Gigante', "When you choose this path at 3rd level, you learn to speak, read, and write Giant if you don't already know it, and you learn your choice of either the druidcraft or thaumaturgy cantrip. Wisdom is your spellcasting ability for this spell.", "Quando você escolhe este caminho no 3º nível, você aprende a falar, ler e escrever em Gigante, se já não o souber, e aprende o truque artifício druídico ou taumaturgia, à sua escolha. Sabedoria é a sua habilidade de conjuração para essa magia."],
      [3, 'Giant\'s Havoc', 'Devastação do Gigante', "3rd-level Path of the Giant feature\n\nYour rages pull strength from the primal might of giants, transforming you into a hulking force of destruction. While raging, you gain the following benefits:\n\nCrushing Throw. When you make a successful ranged attack with a thrown weapon using Strength, you can add your Rage Damage bonus to the attack's damage roll.\n\nGiant Stature. Your reach increases by 5 feet, and if you are smaller than Large, you become Large, along with anything you are wearing. If there isn't enough room for you to increase your size, your size doesn't change.", "Característica de 3º nível do Caminho do Gigante\n\nSuas fúrias extraem força do poder primordial dos gigantes, transformando você em uma força de destruição descomunal. Enquanto estiver em fúria, você ganha os seguintes benefícios:\n\nArremesso Esmagador. Quando você obtiver sucesso em um ataque à distância com uma arma de arremesso usando Força, você pode adicionar o seu bônus de Dano de Fúria à jogada de dano do ataque.\n\nEstatura de Gigante. Seu alcance aumenta em 1,5 metro e, se você for menor que Grande, você se torna Grande, juntamente com tudo o que estiver vestindo ou carregando. Se não houver espaço suficiente para você aumentar de tamanho, seu tamanho não muda."],
      [6, 'Elemental Cleaver', 'Cutelo Elemental', "6th-level Path of the Giant feature\n\nYour bond with the elemental might of giants grows, and you learn to infuse weapons with primordial energy.\n\nWhen you enter your rage, you can choose one weapon that you are holding and infuse it with one of the following damage types: acid, cold, fire, thunder, or lightning. While you wield the infused weapon during your rage, the weapon's damage type changes to the chosen type, it deals an extra 1d6 damage of the chosen type when it hits, and it gains the thrown property, with a normal range of 20 feet and a long range of 60 feet. If you throw the weapon, it reappears in your hand the instant after it hits or misses a target. The infused weapon's benefits are suppressed while a creature other than you wields it.\n\nWhile raging and holding the infused weapon, you can use a bonus action to change the infused weapon's current damage type to another one from the damage type options above.", "Característica de 6º nível do Caminho do Gigante\n\nSeu vínculo com o poder elemental dos gigantes cresce, e você aprende a imbuir armas com energia primordial.\n\nQuando você entra em sua fúria, você pode escolher uma arma que esteja segurando e imbui-la com um dos seguintes tipos de dano: ácido, frio, fogo, trovejante ou elétrico. Enquanto você empunhar a arma imbuída durante a sua fúria, o tipo de dano da arma muda para o tipo escolhido, ela causa 1d6 de dano adicional do tipo escolhido quando atinge, e ela ganha a propriedade de arremesso, com alcance normal de 6 metros e alcance longo de 18 metros. Se você arremessar a arma, ela reaparece na sua mão no instante após acertar ou errar um alvo. Os benefícios da arma imbuída são suprimidos enquanto uma criatura diferente de você a empunhar.\n\nEnquanto estiver em fúria e segurando a arma imbuída, você pode usar uma ação bônus para mudar o tipo de dano atual da arma imbuída para outro entre as opções de tipos de dano acima."],
      [10, 'Mighty Impel', 'Arremesso Poderoso', "10th-level Path of the Giant feature\n\nYour connection to giant strength allows you to hurl both allies and enemies on the battlefield. As a bonus action while raging, you can choose one Medium or smaller creature within your reach and move it to an unoccupied space you can see within 30 feet of yourself. An unwilling creature must succeed on a Strength saving throw (DC equals 8 + your proficiency bonus + your Strength modifier) to avoid the effect.\n\nIf, at the end of this movement, the thrown creature isn't on a surface or liquid that can support it, the creature falls, taking damage as normal and landing prone.", "Característica de 10º nível do Caminho do Gigante\n\nSua conexão com a força dos gigantes permite que você arremesse aliados e inimigos no campo de batalha. Como uma ação bônus enquanto estiver em fúria, você pode escolher uma criatura Média ou menor dentro do seu alcance e movê-la para um espaço desocupado que você possa ver a até 9 metros de você. Uma criatura relutante deve ser bem-sucedida em uma salvaguarda de Força (CD igual a 8 + seu bônus de proficiência + seu modificador de Força) para evitar o efeito.\n\nSe, ao final desse movimento, a criatura arremessada não estiver em uma superfície ou líquido capaz de sustentá-la, ela cai, sofrendo dano normalmente e caindo no chão."],
      [14, 'Demiurgic Colossus', 'Colosso Demiúrgico', "14th-level Path of the Giant feature\n\nThe primordial power of your rage intensifies. When you rage, your reach increases by 10 feet, your size can increase to Large or Huge (your choice), and you can use your Mighty Impel to move creatures that are Large or smaller.\n\nIn addition, the extra damage dealt by your Elemental Cleaver feature increases to 2d6.", "Característica de 14º nível do Caminho do Gigante\n\nO poder primordial da sua fúria se intensifica. Quando você entra em fúria, seu alcance aumenta em 3 metros, seu tamanho pode aumentar para Grande ou Enorme (à sua escolha) e você pode usar o seu Impulso Poderoso para mover criaturas que sejam Grandes ou menores.\n\nAlém disso, o dano adicional causado pela sua característica Cutelo Elemental aumenta para 2d6."],
    ],
  },
  bard: {
    swords: [
      [3, 'Bonus Proficiencies', 'Proficiências Adicionais', "When you join the College of Lore at 3rd level, you gain proficiency with three skills of your choice.", "Quando você se junta ao Colégio do Conhecimento no 3º nível, você ganha proficiência em três perícias à sua escolha."],
      [3, 'Fighting Style', 'Estilo de Luta', "At 3rd level, you adopt a style of fighting as your specialty. Choose one of the following options. You can’t take a Fighting Style option more than once, even if something in the game lets you choose again.\n\nDUELING\n\nWhen you are wielding a melee weapon in one hand and no other weapons, you gain a +2 bonus to damage rolls with that weapon.\n\nTWO-WEAPON FIGHTING\n\nWhen you engage in two-weapon fighting, you can add your ability modifier to the damage of the second attack.", "No 3º nível, você adota um estilo de luta como sua especialidade. Escolha uma das seguintes opções. Você não pode escolher uma opção de Estilo de Luta mais de uma vez, mesmo se algo no jogo permitir que você escolha novamente.\n\nDUELO\n\nQuando estiver empunhando uma arma corpo a corpo em uma mão e nenhuma outra arma, você ganha um bônus de +2 nas jogadas de dano com aquela arma.\n\nCOMBATE COM DUAS ARMAS\n\nQuando você se engajar em combate com duas armas, você pode adicionar seu modificador de atributo ao dano do segundo ataque."],
      [3, 'Blade Flourish', 'Floreio de Lâmina', "At 3rd level, you learn to perform impressive displays of martial prowess and speed.\n\nWhenever you take the Attack action on your turn, your walking speed increases by 10 feet until the end of the turn, and if a weapon attack that you make as part of this action hits a creature, you can use one of the following Blade Flourish options of your choice. You can use only one Blade Flourish option per turn.\n\nDefensive Flourish. You can expend one use of your Bardic Inspiration to cause the weapon to deal extra damage to the target you hit. The damage equals the number you roll on the Bardic Inspiration die. You also add the number rolled to your AC until the start of your next turn.\n\nSlashing Flourish. You can expend one use of your Bardic Inspiration to cause the weapon to deal extra damage to the target you hit and to any other creature of your choice that you can see within 5 feet of you. The damage equals the number you roll on the Bardic Inspiration die.\n\nMobile Flourish. You can expend one use of your Bardic Inspiration to cause the weapon to deal extra damage to the target you hit. The damage equals the number you roll on the Bardic Inspiration die. You can also push the target up to 5 feet away from you, plus a number of feet equal to the number you roll on that die. You can then immediately use your reaction to move up to your walking speed to an unoccupied space within 5 feet of the target.", "No 3º nível, você aprende a realizar demonstrações impressionantes de proeza marcial e velocidade.\n\nSempre que realizar a ação de Ataque em seu turno, seu deslocamento de caminhada aumenta em 3 metros até o final do turno e, se um ataque com arma que você fizer como parte dessa ação atingir uma criatura, você pode usar uma das seguintes opções de Floresio de Lâmina à sua escolha. Você pode usar apenas uma opção de Floresio de Lâmina por turno.\n\nFloresio Defensivo. Você pode gastar um uso da sua Inspiração de Bardo para fazer com que a arma cause dano adicional ao alvo atingido. O dano é igual ao número que você rolar no dado de Inspiração de Bardo. Você também adiciona o número rolado à sua CA até o início do seu próximo turno.\n\nFloresio Cortante. Você pode gastar um uso da sua Inspiração de Bardo para fazer com que a arma cause dano adicional ao alvo atingido e a qualquer outra criatura à sua escolha que você possa ver a até 1,5 metro de você. O dano é igual ao número que você rolar no dado de Inspiração de Bardo.\n\nFloresio Móvel. Você pode gastar um uso da sua Inspiração de Bardo para fazer com que a arma cause dano adicional ao alvo atingido. O dano é igual ao número que você rolar no dado de Inspiração de Bardo. Você também pode empurrar o alvo até 1,5 metro para longe de você, mais uma distância em metros igual a 1,5 vezes o número rolado naquele dado. Você pode então usar imediatamente sua reação para se mover até o seu deslocamento de caminhada para um espaço desocupado a até 1,5 metro do alvo."],
      [6, 'Extra Attack', 'Ataque Extra', "Starting at 6th level, you can attack twice, instead of once, whenever you take the Attack action on your turn.", "A partir do 6º nível, você pode atacar duas vezes, em vez de uma, sempre que realizar a ação de Ataque em seu turno."],
      [14, 'Master\'s Flourish', 'Floreio do Mestre', "Starting at 14th level, whenever you use a Blade Flourish option, you can roll a d6 and use it instead of expending a Bardic Inspiration die.", "A partir do 14º nível, sempre que você usar uma opção de Floresio de Lâmina, você pode rolar um d6 e usá-lo em vez de gastar um dado de Inspiração de Bardo."],
    ],
    whispers: [
      [3, 'Psychic Blades', 'Lâminas Psíquicas', "When you join the College of Whispers at 3rd level, you gain the ability to make your weapon attacks magically toxic to a creature’s mind.\n\nWhen you hit a creature with a weapon attack, you can expend one use of your Bardic Inspiration to deal an extra 2d6 psychic damage to that target. You can do so only once per round on your turn.\n\nThe psychic damage increases when you reach certain levels in this class, increasing to 3d6 at 5th level, 5d6 at 10th level, and 8d6 at 15th level.", "Quando você se junta ao Colégio dos Sussurros no 3º nível, você ganha a habilidade de tornar seus ataques com arma magicamente tóxicos para a mente de uma criatura.\n\nQuando você atinge uma criatura com um ataque com arma, você pode gastar um uso da sua Inspiração de Bardo para causar 2d6 de dano psíquico adicional àquele alvo. Você pode fazer isso apenas uma vez por rodada em seu turno.\n\nO dano psíquico aumenta quando você alcança certos níveis nesta classe, aumentando para 3d6 no 5º nível, 5d6 no 10º nível e 8d6 no 15º nível."],
      [3, 'Words of Terror', 'Palavras de Terror', "At 3rd level, you learn to infuse innocent-seeming words with an insidious magic that can inspire terror.\n\nIf you speak to a humanoid alone for at least 1 minute, you can attempt to seed paranoia in its mind. At the end of the conversation, the target must succeed on a Wisdom saving throw against your spell save DC or be frightened of you or another creature of your choice. The target is frightened in this way for 1 hour, until it is attacked or damaged, or until it witnesses its allies being attacked or damaged.\n\nIf the target succeeds on its saving throw, the target has no hint that you tried to frighten it.\n\nOnce you use this feature, you can't use it again until you finish a short or long rest.", "No 3º nível, você aprende a impregnar palavras aparentemente inocentes com uma magia insidiosa capaz de inspirar terror.\n\nSe conversar com um humanoide a sós por pelo menos 1 minuto, você pode tentar semear a paranoia na mente dele. Ao final da conversa, o alvo deve ser bem-sucedido em uma salvaguarda de Sabedoria contra a CD de resistência da sua magia ou ficará amedrontado por você ou por outra criatura à sua escolha. O alvo fica amedrontado dessa maneira por 1 hora, até ser atacado ou sofrer dano, ou até testemunhar seus aliados sendo atacados ou sofrendo dano.\n\nSe o alvo for bem-sucedido na salvaguarda, ele não terá pista alguma de que você tentou amedrontá-lo.\n\nDepois de usar esta característica, você não pode usá-la novamente até terminar um descanso curto ou longo."],
      [6, 'Mantle of Whispers', 'Manto dos Sussurros', "At 6th level, you gain the ability to adopt a humanoid’s persona. When a humanoid dies within 30 feet of you, you can magically capture its shadow using your reaction. You retain this shadow until you use it or you finish a long rest.\n\nYou can use the shadow as an action. When you do so, it vanishes, magically transforming into a disguise that appears on you. You now look like the dead person, but healthy and alive. This disguise lasts for 1 hour or until you end it as a bonus action.\n\nWhile you’re in the disguise, you gain access to all information that the humanoid would freely share with a casual acquaintance. Such information includes general details on its background and personal life, but doesn’t include secrets. The information is enough that you can pass yourself off as the person by drawing on its memories.\n\nAnother creature can see through this disguise by succeeding on a Wisdom (Insight) check contested by your Charisma (Deception) check. You gain a +5 bonus to your check.\n\nOnce you capture a shadow with this feature, you can’t capture another one with it until you finish a short or long rest.", "No 6º nível, você ganha a habilidade de adotar a persona de um humanoide. Quando um humanoide morre a até 9 metros de você, você pode capturar magicamente a sombra dele usando sua reação. Você retém essa sombra até usá-la ou terminar um descanso longo.\n\nVocê pode usar a sombra como uma ação. Ao fazer isso, ela desaparece, transformando-se magicamente em um disfarce que surge sobre você. Agora você se parece com a pessoa morta, mas saudável e viva. Esse disfarce dura por 1 hora ou até você encerrá-lo como uma ação bônus.\n\nEnquanto estiver no disfarce, você ganha acesso a todas as informações que o humanoide compartilharia livremente com um conhecido casual. Tais informações incluem detalhes gerais sobre seu histórico e vida pessoal, mas não incluem segredos. A informação é suficiente para que você se passe pela pessoa recorrendo às memórias dela.\n\nOutra criatura pode ver através desse disfarce sendo bem-sucedida em um teste de Sabedoria (Intuição) contestado pelo seu teste de Carisma (Enganação). Você ganha um bônus de +5 no seu teste.\nound e vida pessoal, mas não incluem segredos. A informação é suficiente para que você se passe pela pessoa recorrendo às memórias dela.\n\nOutra criatura pode ver através desse disfarce sendo bem-sucedida em um teste de Sabedoria (Intuição) contestado pelo seu teste de Carisma (Enganação). Você ganha um bônus de +5 no seu teste.\n\nUma vez que capturar uma sombra com esta característica, você não pode capturar outra com ela até terminar um descanso curto ou longo."],
      [14, 'Shadow Lore', 'Saber Sombrio', "At 14th level, you gain the ability to weave dark magic into your words and tap into a creature’s deepest fears.\n\nAs an action, you magically whisper a phrase that only one creature of your choice within 30 feet of you can hear. The target must make a Wisdom saving throw against your spell save DC. It automatically succeeds if it doesn’t share a language with you or if it can’t hear you. On a successful saving throw, your whisper sounds like unintelligible mumbling and has no effect.\n\nOn a failed saving throw, the target is charmed by you for the next 8 hours or until you or your allies attack it, damage it, or force it to make a saving throw. It interprets the whispers as a description of its most mortifying secret. You gain no knowledge of this secret, but the target is convinced you know it.\n\nThe charmed creature obeys your commands for fear that you will reveal its secret. It won’t risk its life for you or fight for you, unless it was already inclined to do so. It grants you favors and gifts it would offer to a close friend.\n\nWhen the effect ends, the creature has no understanding of why it held you in such fear.\n\nOnce you use this feature, you can’t use it again until you finish a long rest.", "No 14º nível, você ganha a habilidade de tecer magia sombria em suas palavras e explorar os medos mais profundos de uma criatura.\n\nComo uma ação, você sussurra magicamente uma frase que apenas uma criatura à sua escolha a até 9 metros de você pode ouvir. O alvo deve fazer uma salvaguarda de Sabedoria contra a CD de resistência das suas magias. Ele é automaticamente bem-sucedido se não compartilhar um idioma com você ou se não puder ouvir você. Em uma salvaguarda bem-sucedida, seu sussurro soa como um resmungo ininteligível e não tem efeito.\n\nSe falhar na salvaguarda, o alvo fica enfeitiçado por você pelas próximas 8 horas ou até que você ou seus aliados o ataquem, causem dano a ele ou o forcem a fazer uma salvaguarda. Ele interpreta os sussurros como uma descrição do seu segredo mais humilhante. Você não obtém conhecimento desse segredo, mas o alvo fica convencido de que você o conhece.\n\nA criatura enfeitiçada obedece aos seus comandos por medo de que você revele o segredo dela. Ela não arriscará a vida por você nem lutará por você, a menos que já estivesse inclinada a fazê-lo. Ela concede a você favores e presentes que ofereceria a um amigo próximo.\n\nQuando o efeito termina, a criatura não compreende por que tinha tanto medo de você.\n\nUma vez que usar esta característica, você não pode usá-la novamente até terminar um descanso longo."],
    ],
    creation: [
      [3, 'Mote of Potential', 'Fagulha de Potencial', "3rd-level College of Creation feature\n\nWhenever you give a creature a Bardic Inspiration die, you can utter a note from the Song of Creation to create a Tiny mote of potential, which orbits within 5 feet of that creature. The mote is intangible and invulnerable, and it lasts until the Bardic Inspiration die is lost. The mote looks like a musical note, a star, a flower, or another symbol of art or life that you choose.\n\nWhen the creature uses the Bardic Inspiration die, the mote provides an additional effect based on whether the die benefits an ability check, an attack roll, or a saving throw, as detailed below:\n\nAbility Check. When the creature rolls the Bardic Inspiration die to add it to an ability check, the creature can roll the Bardic Inspiration die again and choose which roll to use, as the mote pops and emits colorful, harmless sparks for a moment.\n\nAttack Roll. Immediately after the creature rolls the Bardic Inspiration die to add it to an attack roll against a target, the mote thunderously shatters. The target and each creature of your choice that you can see within 5 feet of it must succeed on a Constitution saving throw against your spell save DC or take thunder damage equal to the number rolled on the Bardic Inspiration die.\n\nSaving Throw. Immediately after the creature rolls the Bardic Inspiration die and adds it to a saving throw, the mote vanishes with the sound of soft music, causing the creature to gain temporary hit points equal to the number rolled on the Bardic Inspiration die plus your Charisma modifier (minimum of 1 temporary hit point).", "Característica de 3º nível do Colégio da Criação\n\nSempre que conceder um dado de Inspiração de Bardo a uma criatura, você pode entoar uma nota da Canção da Criação para criar um fragmento Minúsculo de potencial, que orbita a até 1,5 metro daquela criatura. O fragmento é intangível e invulnerável, e dura até que o dado de Inspiração de Bardo seja perdido. O fragmento se parece com uma nota musical, uma estrela, uma flor ou outro símbolo de arte ou vida à sua escolha.\n\nQuando a criatura usa o dado de Inspiração de Bardo, o fragmento fornece um efeito adicional com base em se o dado beneficia um teste de atributo, uma jogada de ataque ou uma salvaguarda, conforme detalhado abaixo:\npiração de Bardo seja perdido. O fragmento se parece com uma nota musical, uma estrela, uma flor ou outro símbolo de arte ou vida à sua escolha.\n\nQuando a criatura usa o dado de Inspiração de Bardo, o fragmento fornece um efeito adicional com base em se o dado beneficia um teste de atributo, uma jogada de ataque ou uma salvaguarda, conforme detalhado abaixo:\n\nTeste de Atributo. Quando a criatura rolar o dado de Inspiração de Bardo para adicioná-lo a um teste de atributo, ela pode rolar o dado de Inspiração de Bardo novamente e escolher qual rolagem usar, enquanto o fragmento estoura e emite faíscas coloridas e inofensivas por um instante.\n\nJogada de Ataque. Imediatamente após a criatura rolar o dado de Inspiração de Bardo para adicioná-lo a uma jogada de ataque contra um alvo, o fragmento se estilhaça estrondosamente. O alvo e cada criatura à sua escolha que você possa ver a até 1,5 metro dele devem ser bem-sucedidos em uma salvaguarda de Constituição contra a CD de resistência das suas magias ou sofrer dano trovejante igual ao número rolado no dado de Inspiração de Bardo.\n\nSalvaguarda. Imediatamente após a criatura rolar o dado de Inspiração de Bardo e adicioná-lo a uma salvaguarda, o fragmento desaparece com o som de uma música suave, fazendo com que a criatura ganhe pontos de vida temporários iguais ao número rolado no dado de Inspiração de Bardo mais o seu modificador de Carisma (mínimo de 1 ponto de vida temporário)."],
      [3, 'Performance of Creation', 'Atuação da Criação', "3rd-level College of Creation feature\n\nAs an action, you can channel the magic of the Song of Creation to create one nonmagical item of your choice in an unoccupied space within 10 feet of you. The item must appear on a surface or in a liquid that can support it. The gp value of the item can’t be more than 20 times your bard level, and the item must be Medium or smaller. The item glimmers softly, and a creature can faintly hear music when touching it. The created item disappears after a number of hours equal to your proficiency bonus. For examples of items you can create, see the equipment chapter of the Player’s Handbook.\n\nOnce you create an item with this feature, you can’t do so again until you finish a long rest, unless you expend a spell slot of 2nd level or higher to use this feature again. You can have only one item created by this feature at a time; if you use this action and already have an item from this feature, the first one immediately vanishes.\n\nThe size of the item you can create with this feature increases by one size category when you reach 6th level (Large) and 14th level (Huge).", "Característica de 3º nível do Colégio da Criação\n\nComo uma ação, você pode canalizar a magia da Canção da Criação para criar um item não mágico à sua escolha em um espaço desocupado a até 3 metros de você. O item deve surgir em uma superfície ou líquido capaz de sustentá-lo. O valor em po do item não pode ultrapassar 20 vezes o seu nível de bardo, e o item deve ser Médio ou menor. O item brilha suavemente, e uma criatura pode ouvir fracamente uma música ao tocá-lo. O item criado desaparece após um número de horas igual ao seu bônus de proficiência. Para exemplos de itens que você pode criar, consulte o capítulo de equipamentos do Livro do Jogador.\n\nUma vez que criar um item com esta característica, você não pode fazê-lo novamente até terminar um descanso longo, a menos que gaste um espaço de magia de 2º círculo ou superior para usar esta característica novamente. Você só pode ter um item criado por esta característica por vez; se usar esta ação e já tiver um item desta característica, o primeiro desaparece imediatamente.\n\nO tamanho do item que você pode criar com esta característica aumenta em uma categoria de tamanho quando você alcança o 6º nível (Grande) e o 14º nível (Enorme)."],
      [6, 'Animating Performance', 'Atuação Animadora', "6th-level College of Creation feature\n\nAs an action, you can animate one Large or smaller nonmagical item within 30 feet of you that isn’t being worn or carried. The animate item uses the Dancing Item stat block, which uses your proficiency bonus (PB). The item is friendly to you and your companions and obeys your commands. It lives for 1 hour, until it is reduced to 0 hit points, or until you die.\n\nIn combat, the item shares your initiative count, but it takes its turn immediately after yours. It can move and use its reaction on its own, but the only action it takes on its turns is the Dodge action, unless you take a bonus action on your turn to command it to take another action. That action can be one in its stat block or some other action. If you are incapacitated, the item can take any action of its choice, not just Dodge.\n\nWhen you use your Bardic Inspiration feature, you can command the item as part of the same bonus action you use for Bardic Inspiration.\n\nOnce you animate an item with this feature, you can’t do so again until you finish a long rest, unless you expend a spell slot of 3rd level or higher to use this feature again. You can have only one item animated by this feature at a time; if you use this action and already have a dancing item from this feature, the first one immediately becomes inanimate.", "Característica de 6º nível do Colégio da Criação\n\nComo uma ação, você pode animar um item não mágico Grande ou menor a até 9 metros de você que não esteja sendo vestido ou carregado. O item animado usa o bloco de estatísticas de Item Dançarino, que utiliza o seu bônus de proficiência (BP). O item é amigável a você e aos seus companheiros e obedece aos seus comandos. Ele vive por 1 hora, até ser reduzido a 0 pontos de vida, ou até você morrer.\n\nEm combate, o item compartilha a sua contagem de iniciativa, mas realiza o turno dele imediatamente após o seu. Ele pode se mover e usar a reação dele por conta própria, mas a única ação que realiza nos turnos dele é a ação de Desviar, a menos que você use uma ação bônus em seu turno para comandá-lo a realizar outra ação. Essa ação pode ser uma de seu bloco de estatísticas ou outra ação qualquer. Se você estiver incapacitado, o item pode realizar qualquer ação à escolha dele, não apenas Desviar.\n\nQuando você usa a sua característica Inspiração de Bardo, você pode comandar o item como parte da mesma ação bônus que você usa para a Inspiração de Bardo.\nara comandá-lo a realizar outra ação. Essa ação pode ser uma de seu bloco de estatísticas ou outra ação qualquer. Se você estiver incapacitado, o item pode realizar qualquer ação à escolha dele, não apenas Desviar.\n\nQuando você usa a sua característica Inspiração de Bardo, você pode comandar o item como parte da mesma ação bônus que você usa para a Inspiração de Bardo.\n\nUma vez que animar um item com esta característica, você não pode fazê-lo novamente até terminar um descanso longo, a menos que gaste um espaço de magia de 3º círculo ou superior para usar esta característica novamente. Você só pode ter um item animado por esta característica por vez; se usar esta ação e já tiver um item dançarino desta característica, o primeiro imediatamente se torna inanimado."],
      [14, 'Creative Crescendo', 'Crescendo Criativo', "14th-level College of Creation feature\n\nWhen you use your Performance of Creation feature, you can create more than one item at once. The number of items equals your Charisma modifier (minimum of two items). If you create an item that would exceed that number, you choose which of the previously created items disappears. Only one of these items can be of the maximum size you can create; the rest must be Small or Tiny.\n\nYou are no longer limited by gp value when creating items with Performance of Creation.", "Característica de 14º nível do Colégio da Criação\n\nQuando você usa sua característica Performance da Criação, você pode criar mais de um item de uma vez. O número de itens é igual ao seu modificador de Carisma (mínimo de dois itens). Se você criar um item que exceda esse número, você escolhe qual dos itens criados anteriormente desaparece. Apenas um desses itens pode ser do tamanho máximo que você pode criar; o restante deve ser Pequeno ou Minúsculo.\n\nVocê não é mais limitado pelo valor em po ao criar itens com a Performance da Criação."],
    ],
    eloquence: [
      [3, 'Silver Tongue', 'Língua de Prata', "3rd-level College of Eloquence feature\n\nYou are a master at saying the right thing at the right time. When you make a Charisma (Persuasion) or Charisma (Deception) check, you can treat a d20 roll of 9 or lower as a 10.", "Característica de 3º nível do Colégio da Eloquência\n\nVocê é um mestre em dizer a coisa certa no momento certo. Quando fizer um teste de Carisma (Persuasão) ou Carisma (Enganação), você pode tratar uma rolagem de d20 de 9 ou menor como um 10."],
      [3, 'Unsettling Words', 'Palavras Perturbadoras', "3rd-level College of Eloquence feature\n\nYou can spin words laced with magic that unsettle a creature and cause it to doubt itself. As a bonus action, you can expend one use of your Bardic Inspiration and choose one creature you can see within 60 feet of you. Roll the Bardic Inspiration die. The creature must subtract the number rolled from the next saving throw it makes before the start of your next turn.", "Característica de 3º nível do Colégio da Eloquência\n\nVocê pode tecer palavras carregadas de magia que perturbam uma criatura e a fazem duvidar de si mesma. Como uma ação bônus, você pode gastar um uso da sua Inspiração de Bardo e escolher uma criatura que você possa ver a até 18 metros de você. Role o dado de Inspiração de Bardo. A criatura deve subtrair o número rolado da próxima salvaguarda que fizer antes do início do seu próximo turno."],
      [6, 'Unfailing Inspiration', 'Inspiração Infalível', "6th-level College of Eloquence feature\n\nYour inspiring words are so persuasive that others feel driven to succeed. When a creature adds one of your Bardic Inspiration dice to its ability check, attack roll, or saving throw and the roll fails, the creature can keep the Bardic Inspiration die.", "Característica de 6º nível do Colégio da Eloquência\n\nSuas palavras inspiradoras são tão persuasivas que outros se sentem impelidos ao sucesso. Quando uma criatura adiciona um dos seus dados de Inspiração de Bardo ao teste de atributo, jogada de ataque ou salvaguarda dela e a rolagem falha, a criatura pode guardar o dado de Inspiração de Bardo."],
      [6, 'Universal Speech', 'Fala Universal', "6th-level College of Eloquence feature\n\nYou have gained the ability to make your speech intelligible to any creature. As an action, choose one or more creatures within 60 feet of you, up to a number equal to your Charisma modifier (minimum of one creature). The chosen creatures can magically understand you, regardless of the language you speak, for 1 hour.\n\nOnce you use this feature, you can't use it again until you finish a long rest, unless you expend a spell slot to use it again.", "Característica de 6º nível do Colégio da Eloquência\n\nVocê ganhou a habilidade de tornar a sua fala inteligível para qualquer criatura. Como uma ação, escolha uma ou mais criaturas a até 18 metros de você, até um número igual ao seu modificador de Carisma (mínimo de uma criatura). As criaturas escolhidas podem compreender você magicamente, independentemente do idioma que você fale, por 1 hora.\n\nUma vez que usar esta característica, você não pode usá-la novamente até terminar um descanso longo, a menos que gaste um espaço de magia para usá-la novamente."],
      [14, 'Infectious Inspiration', 'Inspiração Contagiosa', "14th-level College of Eloquence feature\n\nWhen you successfully inspire someone, the power of your eloquence can now spread to someone else. When a creature within 60 feet of you adds one of your Bardic Inspiration dice to its ability check, attack roll, or saving throw and the roll succeeds, you can use your reaction to encourage a different creature (other than yourself) that can hear you within 60 feet of you, giving it a Bardic Inspiration die without expending any of your Bardic Inspiration uses.\n\nYou can use this reaction a number of times equal to your Charisma modifier (minimum of once), and you regain all expended uses when you finish a long rest.", "Característica de 14º nível do Colégio da Eloquência\n\nQuando você inspira alguém com sucesso, o poder de sua eloquência agora pode se espalhar para outra pessoa. Quando uma criatura a até 18 metros de você adiciona um dos seus dados de Inspiração Bárdica ao seu teste de atributo, jogada de ataque ou salvaguarda e a jogada for bem-sucedida, você pode usar sua reação para encorajar uma criatura diferente (que não seja você) que possa ouvi-lo a até 18 metros de você, concedendo a ela um dado de Inspiração Bárdica sem gastar nenhum dos seus usos de Inspiração Bárdica.\n\nVocê pode usar esta reação um número de vezes igual ao seu modificador de Carisma (mínimo de uma vez) e recupera todos os usos gastos ao terminar um descanso longo."],
    ],
    spirits: [
      [3, 'Guiding Whispers', 'Sussurros Guias', "You can reach out to spirits to guide you and others. You learn the guidance cantrip, which doesn’t count against the number of bard cantrips you know. For you, it has a range of 60 feet when you cast it.", "Você pode estender a mão aos espíritos para guiar você e a outros. Você aprende o truque orientação, que não conta no número de truques de bardo que você conhece. Para você, ele tem um alcance de 18 metros quando você o conjura."],
      [3, 'Spiritual Focus', 'Foco Espiritual', "You employ tools that aid you in channeling spirits, be they historical figures or fictional archetypes. You can use the following objects as a spellcasting focus for your bard spells: a candle, crystal ball, skull, spirit board, or tarokka deck.\n\nStarting at 6th level, when you cast a bard spell that deals damage or restores hit points through the Spiritual Focus, roll a d6, and you gain a bonus to one damage or healing roll of the spell equal to the number rolled.", "Você emprega ferramentas que o ajudam a canalizar espíritos, sejam eles figuras históricas ou arquétipos fictícios. Você pode usar os seguintes objetos como foco de conjuração para suas magias de bardo: uma vela, bola de cristal, caveira, tabuleiro de espíritos ou baralho de tarokka.\n\nA partir do 6º nível, quando você conjurar uma magia de bardo que cause dano ou restaure pontos de vida através do Foco Espiritual, role um d6 e adicione um bônus a uma rolagem de dano ou cura da magia igual ao número rolado."],
      [3, 'Tales from Beyond', 'Contos do Além', "You reach out to spirits who tell their tales through you. While you are holding your Spiritual Focus, you can use a bonus action to expend one use of your Bardic Inspiration and roll on the Spirit Tales table using your Bardic Inspiration die to determine the tale the spirits direct you to tell. You retain the tale in mind until you bestow the tale’s effect or you finish a short or long rest.\n\nYou can use an action to choose one creature you can see within 30 feet of you (this can be you) to be the target of the tale’s effect. Once you do so, you can’t bestow the tale’s effect again until you roll it again.\n\nYou can retain only one of these tales in mind at a time, and rolling on the Spirit Tales table immediately ends the effect of the previous tale.\n\nIf the tale requires a saving throw, the DC equals your spell save DC.", "Você busca contato com espíritos que contam suas histórias através de você. Enquanto estiver segurando seu Foco Espiritual, você pode usar uma ação bônus para gastar um uso da sua Inspiração de Bardo e rolar na tabela Contos dos Espíritos usando seu dado de Inspiração de Bardo para determinar o conto que os espíritos o orientam a narrar. Você mantém o conto em mente até conceder o efeito dele ou até terminar um descanso curto ou longo.\n\nVocê pode usar uma ação para escolher uma criatura que possa ver a até 9 metros de você (que pode ser você) para ser o alvo do efeito do conto. Depois de fazer isso, você não pode conceder o efeito do conto novamente até rolá-lo de novo.\n\nVocê pode manter apenas um desses contos em mente por vez, e rolar na tabela Contos dos Espíritos encerra imediatamente o efeito do conto anterior.\n\nSe o conto exigir uma salvaguarda, a CD será igual à CD de resistência da sua magia."],
      [6, 'Spirit Session', 'Sessão Espiritual', "Spirits provide you with supernatural insights. You can conduct an hour-long ritual channeling spirits (which can be done during a short or long rest) using your Spiritual Focus. You can conduct the ritual with a number of willing creatures equal to your proficiency bonus (including yourself). At the end of the ritual, you temporarily learn one spell of your choice from any class.\n\nThe spell you choose must be of a level equal to the number of creatures that conducted the ritual or less, the spell must be of a level you can cast, and it must be in the school of divination or necromancy. The chosen spell counts as a bard spell for you but doesn’t count against the number of bard spells you know.\n\nOnce you perform the ritual, you can’t do so again until you start a long rest, and you know the chosen spell until you start a long rest.", "Os espíritos fornecem a você visões sobrenaturais. Você pode realizar um ritual de 1 hora canalizando espíritos (o que pode ser feito durante um descanso curto ou longo) usando seu Foco Espiritual. Você pode conduzir o ritual com um número de criaturas voluntárias igual ao seu bônus de proficiência (incluindo você mesmo). Ao final do ritual, você aprende temporariamente uma magia à sua escolha de qualquer classe.\n\nA magia escolhida deve ser de um círculo igual ou inferior ao número de criaturas que realizaram o ritual, deve ser de um círculo que você possa conjurar e deve pertencer à escola de adivinhação ou necromancia. A magia escolhida conta como uma magia de bardo para você, mas não conta no número de magias de bardo que você conhece.\n\nDepois de realizar o ritual, você não poderá realizá-lo novamente até iniciar um descanso longo, e saberá a magia escolhida até iniciar um descanso longo."],
      [14, 'Mystical Connection', 'Conexão Mística', "You now have the ability to nudge the spirits of Tales from Beyond toward certain tales. Whenever you roll on the Spirit Tales table, you can roll the die twice and choose which of the two effects to bestow. If you roll the same number on both dice, you can ignore the number and choose any effect on the table.", "Você agora tem a habilidade de conduzir os espíritos de Contos do Além em direção a certos contos. Sempre que você rolar na tabela de Contos Espirituais, você pode rolar o dado duas vezes e escolher qual dos dois efeitos conceder. Se rolar o mesmo número em ambos os dados, você pode ignorar o número e escolher qualquer efeito da tabela."],
    ],
  },
  cleric: {
    nature: [
      [1, 'Acolyte of Nature', 'Acólito da Natureza', "At 1st level, you learn one druid cantrip of your choice. This cantrip counts as a cleric cantrip for you, but it doesn’t count against the number of cleric cantrips you know. You also gain proficiency in one of the following skills of your choice: Animal Handling, Nature, or Survival.", "No 1º nível, você aprende um truque de druida à sua escolha. Esse truque conta como um truque de clérigo para você, mas não conta no número de truques de clérigo que você conhece. Você também ganha proficiência em uma das seguintes perícias à sua escolha: Adestrar Animais, Natureza ou Sobrevivência."],
      [1, 'Bonus Proficiency', 'Proficiência Adicional', "When you choose this domain at 1st level, you gain proficiency with heavy armor.", "Quando você escolhe este domínio no 1º nível, você ganha proficiência com armaduras pesadas."],
      [2, 'Channel Divinity: Charm Animals and Plants', 'Canalizar Divindade: Enfeitiçar Animais e Plantas', "Starting at 2nd level, you can use your Channel Divinity to charm animals and plants.\n\nAs an action, you present your holy symbol and invoke the name of your deity. Each beast or plant creature that can see you within 30 feet of you must make a Wisdom saving throw. If the creature fails its saving throw, it is charmed by you for 1 minute or until it takes damage. While it is charmed by you, it is friendly to you and other creatures you designate.", "A partir do 2º nível, você pode usar seu Canalizar Divindade para enfeitiçar animais e plantas.\n\nCom uma ação, você ergue seu símbolo sagrado e invoca o nome de sua divindade. Cada fera ou criatura vegetal a até 9 metros de você que puder vê-lo deve realizar uma salvaguarda de Sabedoria. Se a criatura falhar na salvaguarda, ela estará enfeitiçada por você por 1 minuto ou até sofrer dano. Enquanto estiver enfeitiçada por você, ela é amistosa com você e com as outras criaturas que você designar."],
      [6, 'Dampen Elements', 'Atenuar Elementos', "Starting at 6th level, when you or a creature within 30 feet of you takes acid, cold, fire, lightning, or thunder damage, you can use your reaction to grant resistance to the creature against that instance of the damage.", "A partir do 6º nível, quando você ou uma criatura a até 9 metros de você sofrer dano de ácido, frio, fogo, elétrico ou trovejante, você pode usar sua reação para conceder resistência à criatura contra essa instância de dano."],
      [8, 'Divine Strike', 'Golpe Divino', "At 8th level, you gain the ability to infuse your weapon strikes with divine energy. Once on each of your turns when you hit a creature with a weapon attack, you can cause the attack to deal an extra 1d8 radiant damage to the target. When you reach 14th level, the extra damage increases to 2d8.", "No 8º nível, você ganha a capacidade de impregnar seus golpes com arma com energia divina. Uma vez em cada um de seus turnos, ao acertar uma criatura com um ataque com arma, você pode fazer com que o ataque cause 1d8 de dano radiante extra ao alvo. Ao alcançar o 14º nível, o dano extra aumenta para 2d8."],
      [17, 'Master of Nature', 'Mestre da Natureza', "At 17th level, you gain the ability to command animals and plant creatures. While creatures are charmed by your Charm Animals and Plants feature, you can take a bonus action on your turn to verbally command what each of those creatures will do on its next turn.", "No 17º nível, você adquire a habilidade de comandar animais e criaturas vegetais. Enquanto criaturas estiverem enfeitiçadas pela sua característica Enfeitiçar Animais e Plantas, você pode usar uma ação bônus no seu turno para comandar verbalmente o que cada uma dessas criaturas fará no próximo turno dela."],
    ],
    death: [
      [1, 'Bonus Proficiency', 'Proficiência Adicional', "When you choose this domain at 1st level, you gain proficiency with heavy armor.", "Quando você escolhe este domínio no 1º nível, você ganha proficiência com armaduras pesadas."],
      [1, 'Reaper', 'Ceifador', "At 1st level, the cleric learns one necromancy cantrip of his or her choice from any spell list. When the cleric casts a necromancy cantrip that normally targets only one creature, the spell can instead target two creatures within range and within 5 feet of each other.", "No 1º nível, o clérigo aprende um truque de necromancia à sua escolha de qualquer lista de magias. Quando o clérigo conjura um truque de necromancia que normalmente tem como alvo apenas uma criatura, a magia pode, em vez disso, ter como alvo duas criaturas dentro do alcance e a até 1,5 metro uma da outra."],
      [2, 'Channel Divinity: Touch of Death', 'Canalizar Divindade: Toque da Morte', "Starting at 2nd level, the cleric can use Channel Divinity to destroy another creature's life force by touch. When the cleric hits a creature with a melee attack, the cleric can use Channel Divinity to deal extra necrotic damage to the target. The damage equals 5 + twice his or her cleric level.", "A partir do 2º nível, o clérigo pode usar o Canalizar Divindade para destruir a força vital de outra criatura através do toque. Quando o clérigo atinge uma criatura com um ataque corpo a corpo, ele pode usar o Canalizar Divindade para causar dano necrótico extra ao alvo. O dano é igual a 5 + o dobro do seu nível de clérigo."],
      [6, 'Inescapable Destruction', 'Destruição Inescapável', "Starting at 6th level, the cleric's ability to channel negative energy becomes more potent. Necrotic damage dealt by the character's cleric spells and Channel Divinity options ignores resistance to necrotic damage.", "A partir do 6º nível, a habilidade do clérigo de canalizar energia negativa torna-se mais potente. O dano necrótico causado pelas magias de clérigo do personagem e pelas opções de Canalizar Divindade ignora resistência a dano necrótico."],
      [8, 'Divine Strike', 'Golpe Divino', "At 8th level, you gain the ability to infuse your weapon strikes with divine energy. Once on each of your turns when you hit a creature with a weapon attack, you can cause the attack to deal an extra 1d8 radiant damage to the target. When you reach 14th level, the extra damage increases to 2d8.", "No 8º nível, você ganha a capacidade de impregnar seus golpes com arma com energia divina. Uma vez em cada um de seus turnos, ao acertar uma criatura com um ataque com arma, você pode fazer com que o ataque cause 1d8 de dano radiante extra ao alvo. Ao alcançar o 14º nível, o dano extra aumenta para 2d8."],
      [17, 'Improved Reaper', 'Ceifador Aprimorado', "Starting at 17th level, when the cleric casts a necromancy spell of 1st through 5th level that targets only one creature, the spell can instead target two creatures within range and within 5 feet of each other. If the spell consumes its material components, the cleric must provide them for each target.", "A partir do 17º nível, quando o clérigo conjurar uma magia de necromancia de 1º a 5º círculo que tenha como alvo apenas uma criatura, a magia pode, em vez disso, ter como alvo duas criaturas dentro do alcance e a até 1,5 metro uma da outra. Se a magia consumir seus componentes materiais, o clérigo deve fornecê-los para cada alvo."],
    ],
    arcana: [
      [1, 'Arcane Initiate', 'Iniciado Arcano', "When you choose this domain at 1st level, you gain proficiency in the Arcana skill, and you gain two cantrips of your choice from the wizard spell list. For you, these cantrips count as cleric cantrips.", "Quando você escolhe este domínio no 1º nível, você ganha proficiência na perícia Arcanismo e aprende dois truques de sua escolha da lista de magias de mago. Para você, esses truques contam como truques de clérigo."],
      [2, 'Channel Divinity: Arcane Abjuration', 'Canalizar Divindade: Abjuração Arcana', "Starting at 2nd level, you can use your Channel Divinity to abjure otherworldly creatures.\n\nAs an action, you present your holy symbol, and one celestial, elemental, fey, or fiend of your choice that is within 30 feet of you must make a Wisdom saving throw, provided that the creature can see or hear you. If the creature fails its saving throw, it is turned for 1 minute or until it takes any damage.\n\nA turned creature must spend its turns trying to move as far away from you as it can, and it can't willingly end its move in a space within 30 feet of you. It also can't take reactions. For its action, it can only use the Dash action or try to escape from an effect that prevents it from moving. If there's nowhere to move, the creature can use the Dodge action.\n\nAfter you reach 5th level, when a creature fails its saving throw against your Arcane Abjuration feature, the creature is banished for 1 minute (as in the banishment spell, no concentration required) if it isn't on its plane of origin and its challenge rating is at or below a certain threshold, as shown on the Arcane Banishment table.\n\nARCANE BANISHMENT\n\n| Cleric Level | Banishes Creatures of CR ... |\n\n| 5th | 1/2 or lower |\n\n| 8th | 1 or lower |\n\n| 11th | 2 or lower |\n\n| 14th | 3 or lower |\n\n| 17th | 4 or lower |", "A partir do 2º nível, você pode usar seu Canalizar Divindade para abjurar criaturas de outros mundos.\n\nCom uma ação, você apresenta seu símbolo sagrado, e um celestial, elemental, fada ou corruptor à sua escolha a até 9 metros de você deve fazer uma salvaguarda de Sabedoria, desde que a criatura possa vê-lo ou ouvi-lo. Se a criatura falhar na salvaguarda, ela é expulsa por 1 minuto ou até sofrer qualquer dano.\n\nUma criatura expulsa deve usar seus turnos tentando se mover o mais longe possível de você, e não pode terminar voluntariamente seu movimento em um espaço a até 9 metros de você. Ela também não pode realizar reações. Como ação, ela pode usar apenas a ação de Disparada ou tentar escapar de um efeito que a impeça de se mover. Se não houver para onde se mover, a criatura pode usar a ação de Desviar.\ne deve usar seus turnos tentando se mover o mais longe possível de você, e não pode terminar voluntariamente seu movimento em um espaço a até 9 metros de você. Ela também não pode realizar reações. Como ação, ela pode usar apenas a ação de Disparada ou tentar escapar de um efeito que a impeça de se mover. Se não houver para onde se mover, a criatura pode usar a ação de Desviar.\n\nDepois que você alcançar o 5º nível, quando uma criatura falhar na salvaguarda contra a sua característica Abjuração Arcana, a criatura é banida por 1 minuto (como na magia banimento, sem exigir concentração) se ela não estiver em seu plano de origem e seu nível de desafio for igual ou inferior a um determinado limiar, conforme mostrado na tabela Banimento Arcano.\n\nBANIMENTO ARCANO\n\nNível de Clérigo | Bane Criaturas de ND ...\n\n5º | 1/2 ou menor\n\n8º | 1 ou menor\n\n11º | 2 ou menor\n\n14º | 3 ou menor\n\n17º | 4 ou menor"],
      [6, 'Spell Breaker', 'Quebra-Magias', "Starting at 6th level, when you restore hit points to an ally with a spell of 1st level or higher, you can also end one spell of your choice on that creature. The level of the spell you end must be equal to or lower than the level of the spell slot you use to cast the healing spell.", "A partir do 6º nível, quando você recupera pontos de vida de um aliado com uma magia de 1º círculo ou superior, você também pode encerrar uma magia à sua escolha naquela criatura. O círculo da magia encerrada deve ser igual ou inferior ao círculo do espaço de magia que você usou para conjurar a magia de cura."],
      [8, 'Potent Spellcasting', 'Conjuração Potente', "Starting at 8th level, you add your Wisdom modifier to the damage you deal with any cleric cantrip.", "A partir do 8º nível, você adiciona seu modificador de Sabedoria ao dano que causa com qualquer truque de clérigo."],
      [17, 'Arcane Mastery', 'Maestria Arcana', "At 17th level, you choose four spells from the wizard spell list, one from each of the following levels: 6th, 7th, 8th, and 9th. You add them to your list of domain spells. Like your other domain spells, they are always prepared and count as cleric spells for you.", "No 17º nível, você escolhe quatro magias da lista de magias de mago, uma de cada um dos seguintes círculos: 6º, 7º, 8º e 9º. Você as adiciona à sua lista de magias de domínio. Assim como suas outras magias de domínio, elas estão sempre preparadas e contam como magias de clérigo para você."],
    ],
    forge: [
      [1, 'Bonus Proficiencies', 'Proficiências Adicionais', "When you choose this domain at 1st level, you gain proficiency with heavy armor and smith’s tools.", "Quando você escolhe este domínio no 1º nível, você ganha proficiência com armaduras pesadas e ferramentas de ferreiro."],
      [1, 'Blessing of the Forge', 'Bênção da Forja', "At 1st level, you gain the ability to imbue magic into a weapon or armor. At the end of a long rest, you can touch one nonmagical object that is a suit of armor or a simple or martial weapon. Until the end of your next long rest or until you die, the object becomes a magic item, granting a +1 bonus to AC if it’s armor or a +1 bonus to attack and damage rolls if it’s a weapon.\n\nOnce you use this feature, you can’t use it again until you finish a long rest.", "No 1º nível, você ganha a habilidade de imbuir magia em uma arma ou armadura. Ao final de um descanso longo, você pode tocar um objeto não mágico que seja um traje de armadura ou uma arma simples ou marcial. Até o final do seu próximo descanso longo ou até você morrer, o objeto se torna um item mágico, concedendo um bônus de +1 na CA se for uma armadura ou um bônus de +1 nas jogadas de ataque e dano se for uma arma.\n\nDepois de usar essa característica, você não pode usá-la novamente até terminar um descanso longo."],
      [2, 'Channel Divinity: Artisan\'s Blessing', 'Canalizar Divindade: Bênção do Artesão', "Starting at 2nd level, you can use your Channel Divinity to create simple items.\n\nYou conduct an hour-long ritual that crafts a nonmagical item that must include some metal: a simple or martial weapon, a suit of armor, ten pieces of ammunition, a set of tools, or another metal object (see chapter 5, “Equipment,” in the Player’s Handbook for examples of these items). The creation is completed at the end of the hour, coalescing in an unoccupied space of your choice on a surface within 5 feet of you.\n\nThe thing you create can be something that is worth no more than 100 gp. As part of this ritual, you must lay out metal, which can include coins, with a value equal to the creation. The metal irretrievably coalesces and transforms into the creation at the ritual’s end, magically forming even nonmetal parts of the creation.\n\nThe ritual can create a duplicate of a nonmagical item that contains metal, such as a key, if you possess the original during the ritual.", "A partir do 2º nível, você pode usar seu Canalizar Divindade para criar itens simples.\n\nVocê realiza um ritual de uma hora que cria um item não mágico que deve incluir algum metal: uma arma simples ou marcial, um traje de armadura, dez munições, um conjunto de ferramentas ou outro objeto de metal (consulte o capítulo 5, “Equipamento”, no Livro do Jogador para obter exemplos desses itens). A criação é concluída ao final de uma hora, coalescendo em um espaço desocupado à sua escolha em uma superfície a até 1,5 metro de você.\n\nO que você cria pode ser algo que não valha mais de 100 po. Como parte desse ritual, você deve dispor de metal, o que pode incluir moedas, com valor igual ao da criação. O metal coalescerá irrevogavelmente e se transformará na criação ao final do ritual, formando magicamente até mesmo as partes não metálicas da criação.\n\nO ritual pode criar uma cópia de um item não mágico que contenha metal, como uma chave, se você possuir o original durante o ritual."],
      [6, 'Soul of the Forge', 'Alma da Forja', "Starting at 6th level, your mastery of the forge grants you special abilities:\n\n• You gain resistance to fire damage.\n\n• While wearing heavy armor, you gain a +1 bonus to AC.", "A partir do 6º nível, sua maestria na forja concede a você habilidades especiais:\n\n• Você ganha resistência a dano de fogo.\n\n• Enquanto estiver usando armadura pesada, você ganha um bônus de +1 na CA."],
      [8, 'Divine Strike', 'Golpe Divino', "At 8th level, you gain the ability to infuse your weapon strikes with divine energy. Once on each of your turns when you hit a creature with a weapon attack, you can cause the attack to deal an extra 1d8 radiant damage to the target. When you reach 14th level, the extra damage increases to 2d8.", "No 8º nível, você ganha a capacidade de impregnar seus golpes com arma com energia divina. Uma vez em cada um de seus turnos, ao acertar uma criatura com um ataque com arma, você pode fazer com que o ataque cause 1d8 de dano radiante extra ao alvo. Ao alcançar o 14º nível, o dano extra aumenta para 2d8."],
      [17, 'Saint of Forge and Fire', 'Santo da Forja e do Fogo', "At 17th level, your blessed affinity with fire and metal becomes more powerful:\n\n• You gain immunity to fire damage.\n\n• While wearing heavy armor, you have resistance to bludgeoning, piercing, and slashing damage from non-magical attacks.", "No 17º nível, sua afinidade abençoada com o fogo e o metal se torna mais poderosa:\n\n• Você ganha imunidade a dano de fogo.\n\n• Enquanto estiver usando armadura pesada, você tem resistência a dano contundente, perfurante e cortante de ataques não mágicos."],
    ],
    grave: [
      [1, 'Circle of Mortality', 'Círculo da Mortalidade', "At 1st level, you gain the ability to manipulate the line between life and death. When you would normally roll one or more dice to restore hit points with a spell to a creature at 0 hit points, you instead use the highest number possible for each die.\n\nIn addition, you learn the spare the dying cantrip, which doesn’t count against the number of cleric cantrips you know. For you, it has a range of 30 feet, and you can cast it as a bonus action.", "No 1º nível, você adquire a habilidade de manipular a linha entre a vida e a morte. Quando normalmente rolaria um ou mais dados para recuperar pontos de vida com uma magia em uma criatura com 0 pontos de vida, em vez disso, você usa o maior número possível para cada dado.\n\nAlém disso, você aprende o truque poupar os moribundos, que não conta no número de truques de clérigo que você conhece. Para você, ele tem um alcance de 9 metros, e você pode conjurá-lo como uma ação bônus."],
      [1, 'Eyes of the Grave', 'Olhos do Túmulo', "At lst level, you gain the ability to occasionally sense the presence of the undead, whose existence is an insult to the natural cycle of life. As an action, you can open your awareness to magically detect undead. Until the end of your next turn, you know the location of any undead within 60 feet of you that isn’t behind total cover and that isn’t protected from divination magic. This sense doesn’t tell you anything about a creature's capabilities or identity.\n\nYou can use this feature a number of times equal to your Wisdom modifier (minimum of once). You regain all expended uses when you finish a long rest.", "No 1º nível, você ganha a habilidade de sentir ocasionalmente a presença de mortos-vivos, cuja existência é um insulto ao ciclo natural da vida. Com uma ação, você pode abrir sua percepção para detectar mortos-vivos magicamente. Até o final do seu próximo turno, você sabe a localização de qualquer morto-vivo a até 18 metros de você que não esteja atrás de cobertura total e que não esteja protegido contra magia de adivinhação. Esse sentido não revela nada sobre as capacidades ou identidade de uma criatura.\n\nVocê pode usar esta característica um número de vezes igual ao seu modificador de Sabedoria (mínimo de uma vez). Você recupera todos os usos gastos ao terminar um descanso longo."],
      [2, 'Channel Divinity: Path to the Grave', 'Canalizar Divindade: Caminho ao Túmulo', "Starting at 2nd level, you can use your Channel Divinity to mark another creature’s life force for termination.\n\nAs an action, you choose one creature you can see within 30 feet of you, cursing it until the end of your next turn. The next time you or an ally of yours hits the cursed creature with an attack, the creature has vulnerability to all of that attack's damage, and then the curse ends.", "A partir do 2º nível, você pode usar seu Canalizar Divindade para marcar a força vital de outra criatura para o extermínio.\n\nCom uma ação, você escolhe uma criatura que você possa ver a até 9 metros de você, amaldiçoando-a até o final do seu próximo turno. Na próxima vez que você ou um aliado seu atingir a criatura amaldiçoada com um ataque, a criatura terá vulnerabilidade a todo o dano desse ataque, e então a maldição se encerra."],
      [6, 'Sentinel at Death\'s Door', 'Sentinela na Porta da Morte', "At 6th level, you gain the ability to impede death’s progress. As a reaction when you or a creature you can see within 30 feet of you suffers a critical hit, you can turn that hit into a normal hit. Any effects triggered by a critical hit are canceled. You can use this feature a number of times equal to your Wisdom modifier (minimum of once). You regain all expended uses when you finish a long rest.", "No 6º nível, você adquire a habilidade de impedir o avanço da morte. Como uma reação quando você ou uma criatura que você possa ver a até 9 metros de você sofrer um acerto crítico, você pode transformar esse acerto em um acerto normal. Quaisquer efeitos ativados por um acerto crítico são cancelados. Você pode usar essa característica um número de vezes igual ao seu modificador de Sabedoria (mínimo de uma vez). Você recupera todos os usos gastos ao terminar um descanso longo."],
      [8, 'Potent Spellcasting', 'Conjuração Potente', "Starting at 8th level, you add your Wisdom modifier to the damage you deal with any cleric cantrip.", "A partir do 8º nível, você adiciona seu modificador de Sabedoria ao dano que causa com qualquer truque de clérigo."],
      [17, 'Keeper of Souls', 'Guardião das Almas', "Starting at 17th level. you can seize a trace of vitality from a parting soul and use it to heal the living. When an enemy you can see dies within 60 feet of you, you or one creature of your choice that is within 60 feet of you regains hit points equal to the enemy’s number of Hit Dice. You can use this feature only if you aren’t incapacitated. Once you use it, you can't do so again until the start of your next turn.", "A partir do 17º nível, você pode capturar um vestígio de vitalidade de uma alma que parte e usá-lo para curar os vivos. Quando um inimigo que você possa ver morrer a até 18 metros de você, você ou uma criatura à sua escolha a até 18 metros de você recupera uma quantidade de pontos de vida igual ao número de Dados de Vida do inimigo. Você só pode usar essa característica se não estiver incapacitado. Depois de usá-la, você não pode fazê-lo novamente até o início do seu próximo turno."],
    ],
    order: [
      [1, 'Bonus Proficiencies', 'Proficiências Adicionais', "When you choose this domain at 1st level, you gain proficiency with heavy armor. You also gain proficiency in the Intimidation or Persuasion skill (your choice).", "Quando você escolhe este domínio no 1º nível, você ganha proficiência com armaduras pesadas. Você também ganha proficiência na perícia Intimidação ou Persuasão (sua escolha)."],
      [1, 'Voice of Authority', 'Voz da Autoridade', "1st-level Order Domain feature\n\nYou can invoke the power of law to embolden an ally to attack. If you cast a spell with a spell slot of 1st level or higher and target an ally with the spell, that ally can use their reaction immediately after the spell to make one weapon attack against a creature of your choice that you can see.\n\nIf the spell targets more than one ally, you choose the ally who can make the attack.", "Característica de 1º nível do Domínio da Ordem\n\nVocê pode invocar o poder da lei para encorajar um aliado a atacar. Se você conjurar uma magia com um espaço de magia de 1º círculo ou superior e tiver um aliado como alvo da magia, esse aliado pode usar a reação dele imediatamente após a magia para fazer um ataque com arma contra uma criatura à sua escolha que você possa ver.\n\nSe a magia tiver como alvo mais de um aliado, você escolhe qual aliado pode fazer o ataque."],
      [2, 'Channel Divinity: Order\'s Demand', 'Canalizar Divindade: Exigência da Ordem', "2nd-level Order Domain feature\n\nYou can use your Channel Divinity to exert an intimidating presence over others.\n\nAs an action, you present your holy symbol, and each creature of your choice that can see or hear you within 30 feet of you must succeed on a Wisdom saving throw or be charmed by you until the end of your next turn or until the charmed creature takes any damage. You can also cause any of the charmed creatures to drop what they are holding when they fail the saving throw.", "Característica de 2º nível do Domínio da Ordem\n\nVocê pode usar seu Canalizar Divindade para exercer uma presença intimidadora sobre os outros.\n\nCom uma ação, você apresenta seu símbolo sagrado, e cada criatura à sua escolha a até 9 metros de você que puder vê-lo ou ouvi-lo deve ser bem-sucedida em uma salvaguarda de Sabedoria ou ficará enfeitiçada por você até o final do seu próximo turno ou até que a criatura enfeitiçada sofra qualquer dano. Você também pode fazer com que qualquer uma das criaturas enfeitiçadas solte o que estiver segurando quando falhar na salvaguarda."],
      [6, 'Embodiment of the Law', 'Encarnação da Lei', "6th-level Order Domain feature\n\nYou have become remarkably adept at channeling magical energy to compel others.\n\nIf you cast a spell of the enchantment school using a spell slot of 1st level or higher, you can change the spell’s casting time to 1 bonus action for this casting, provided the spell’s casting time is normally 1 action.\n\nYou can use this feature a number of times equal to your Wisdom modifier (minimum of once), and you regain all expended uses of it when you finish a long rest.", "Característica de 6º nível do Domínio da Ordem\n\nVocê se tornou extraordinariamente hábil em canalizar energia mágica para compelir outros.\n\nSe você conjurar uma magia da escola de encantamento usando um espaço de magia de 1º círculo ou superior, você pode alterar o tempo de conjuração da magia para 1 ação bônus para essa conjuração, desde que o tempo de conjuração original da magia seja normalmente 1 ação.\n\nVocê pode usar essa característica um número de vezes igual ao seu modificador de Sabedoria (mínimo de uma vez), e recupera todos os usos gastos dela ao terminar um descanso longo."],
      [8, 'Divine Strike', 'Golpe Divino', "At 8th level, you gain the ability to infuse your weapon strikes with divine energy. Once on each of your turns when you hit a creature with a weapon attack, you can cause the attack to deal an extra 1d8 radiant damage to the target. When you reach 14th level, the extra damage increases to 2d8.", "No 8º nível, você ganha a capacidade de impregnar seus golpes com arma com energia divina. Uma vez em cada um de seus turnos, ao acertar uma criatura com um ataque com arma, você pode fazer com que o ataque cause 1d8 de dano radiante extra ao alvo. Ao alcançar o 14º nível, o dano extra aumenta para 2d8."],
      [17, 'Order\'s Wrath', 'Ira da Ordem', "17th-level Order Domain feature\n\nEnemies you designate for destruction wilt under the combined efforts of you and your allies. If you deal your Divine Strike damage to a creature on your turn, you can curse that creature until the start of your next turn. The next time one of your allies hits the cursed creature with an attack, the target also takes 2d8 psychic damage, and the curse ends. You can curse a creature in this way only once per turn.", "Característica de 17º nível do Domínio da Ordem\n\nOs inimigos que você designa para a destruição sucumbem sob os esforços combinados de você e seus aliados. Se você causar o dano do seu Golpe Divino a uma criatura no seu turno, poderá amaldiçoar essa criatura até o início do seu próximo turno. Na próxima vez que um dos seus aliados acertar a criatura amaldiçoada com um ataque, o alvo também sofrerá 2d8 de dano psíquico, e a maldição terminará. Você pode amaldiçoar uma criatura dessa maneira apenas uma vez por turno."],
    ],
    peace: [
      [1, 'Implement of Peace', 'Instrumento da Paz', "1st-level Peace Domain feature\n\nYou gain proficiency in the Insight, Performance, or Persuasion skill (your choice).", "Característica de 1º nível do Domínio da Paz\n\nVocê ganha proficiência na perícia Intuição, Atuação ou Persuasão (sua escolha)."],
      [1, 'Emboldening Bond', 'Elo Encorajador', "1st-level Peace Domain feature\n\nYou can forge an empowering bond among people who are at peace with one another. As an action, you can choose a number of willing creatures within 30 feet of you (this can include yourself) equal to your proficiency bonus. You create a magical bond among them for 10 minutes or until you use this feature again. While any bonded creature is within 30 feet of another, the creature can roll a d4 and add the number rolled to an attack roll, an ability check, or a saving throw it makes. Each creature can add the d4 no more than once per turn.\n\nYou can use this feature a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.", "Característica de 1º nível do Domínio da Paz\n\nVocê pode forjar um elo fortalecedor entre pessoas que estão em paz umas com as outras. Com uma ação, você pode escolher um número de criaturas voluntárias a até 9 metros de você (o que pode incluir você mesmo) igual ao seu bônus de proficiência. Você cria um elo mágico entre elas por 10 minutos ou até usar essa característica novamente. Enquanto qualquer criatura vinculada estiver a até 9 metros de outra, a criatura pode rolar um d4 e adicionar o número rolado a uma jogada de ataque, teste de habilidade ou salvaguarda que realizar. Cada criatura pode adicionar o d4 no máximo uma vez por turno.\n\nVocê pode usar essa característica um número de vezes igual ao seu bônus de proficiência, e recupera todos os usos gastos ao terminar um descanso longo."],
      [2, 'Channel Divinity: Balm of Peace', 'Canalizar Divindade: Bálsamo da Paz', "2nd-level Peace Domain feature\n\nYou can use your Channel Divinity to make your very presence a soothing balm. As an action, you can move up to your speed, without provoking an opportunity attacks, and when you move within 5 feet of any other creature during this action, you can restore a number of hit points to that creature equal to 2d6 + your Wisdom modifier (minimum of 1 hit point). A creature can receive this healing only once whenever you take this action.", "Característica de 2º nível do Domínio da Paz\n\nVocê pode usar seu Canalizar Divindade para tornar sua própria presença um bálsamo reconfortante. Com uma ação, você pode se mover até o seu deslocamento, sem provocar ataques de oportunidade, e quando se mover a até 1,5 metro de qualquer outra criatura durante essa ação, você pode recuperar um número de pontos de vida daquela criatura igual a 2d6 + seu modificador de Sabedoria (mínimo de 1 ponto de vida). Uma criatura pode receber essa cura apenas uma vez sempre que você realizar essa ação."],
      [6, 'Protective Bond', 'Elo Protetor', "6th-level Peace Domain feature\n\nThe bond you forge between people helps them protect each other. When a creature affected by your Emboldening Bond feature is about to take damage, a second bonded creature within 30 feet of the first can use its reaction to teleport to an unoccupied space within 5 feet of the first creature. The second creature then takes all the damage instead.", "Característica de 6º nível do Domínio da Paz\n\nO elo que você forja entre as pessoas ajuda-as a protegerem umas às outras. Quando uma criatura afetada por sua característica Elo Encorajador estiver prestes a sofrer dano, uma segunda criatura vinculada a até 9 metros da primeira pode usar sua reação para se teletransportar para um espaço desocupado a até 1,5 metro da primeira criatura. A segunda criatura então sofre todo o dano em seu lugar."],
      [8, 'Potent Spellcasting', 'Conjuração Potente', "Starting at 8th level, you add your Wisdom modifier to the damage you deal with any cleric cantrip.", "A partir do 8º nível, você adiciona seu modificador de Sabedoria ao dano que causa com qualquer truque de clérigo."],
      [17, 'Expansive Bond', 'Elo Expansivo', "17th-level Peace Domain feature\n\nThe benefits of your Emboldening Bond and Protective Bond features now work when the creatures are within 60 feet of each other. Moreover, when a creature uses Protective Bond to take someone else’s damage, the creature has resistance to that damage.", "Característica de 17º nível do Domínio da Paz\n\nOs benefícios de suas características Elo Encorajador e Elo Protetor agora funcionam quando as criaturas estão a até 18 metros uma da outra. Além disso, quando uma criatura usa Elo Protetor para assumir o dano de outra pessoa, a criatura tem resistência àquele dano."],
    ],
    twilight: [
      [1, 'Bonus Proficiencies', 'Proficiências Adicionais', "1st-level Twilight Domain feature\n\nYou gain proficiency with martial weapons and heavy armor.", "Característica de 1º nível do Domínio do Crepúsculo\n\nVocê ganha proficiência com armas marciais e armaduras pesadas."],
      [1, 'Eyes of Night', 'Olhos da Noite', "1st-level Twilight Domain feature\n\nYou can see through the deepest gloom. You have darkvision out to a range of 300 feet. In that radius, you can see in dim light as if it were bright light and in darkness as if it were dim light.\n\nAs an action, you can magically share the darkvision of this feature with willing creatures you can see within 10 feet of you, up to a number of creatures equal to your Wisdom modifier (minimum of one creature). The shared darkvision lasts for 1 hour. Once you share it, you can’t do so again until you finish a long rest, unless you expend a spell slot of any level to share it again.", "Característica de 1º nível do Domínio do Crepúsculo\n\nVocê pode enxergar através da mais profunda penumbra. Você tem visão no escuro com alcance de 90 metros. Nesse raio, você pode ver na luz penumbrosa como se fosse luz plena e na escuridão como se fosse luz penumbrosa.\n\nCom uma ação, você pode compartilhar magicamente a visão no escuro desta característica com criaturas voluntárias que possa ver a até 3 metros de você, até um número de criaturas igual ao seu modificador de Sabedoria (mínimo de uma criatura). A visão no escuro compartilhada dura por 1 hora. Uma vez compartilhada, você não pode fazê-lo novamente até terminar um descanso longo, a menos que gaste um espaço de magia de qualquer círculo para compartilhá-la novamente."],
      [1, 'Vigilant Blessing', 'Bênção Vigilante', "1st-level Twilight Domain feature\n\nThe night has taught you to be vigilant. As an action, you give one creature you touch (including possibly yourself) advantage on the next initiative roll the creature makes. This benefit ends immediately after the roll or if you use this feature again.", "Característica de 1º nível do Domínio do Crepúsculo\n\nA noite ensinou você a ser vigilante. Com uma ação, você concede a uma criatura que você tocar (incluindo você mesmo, se desejar) vantagem na próxima jogada de iniciativa que a criatura fizer. Esse benefício termina imediatamente após a jogada ou se você usar essa característica novamente."],
      [2, 'Channel Divinity: Twilight Sanctuary', 'Canalizar Divindade: Santuário do Crepúsculo', "2nd-level Twilight Domain feature\n\nYou can use your Channel Divinity to refresh your allies with soothing twilight.\n\nAs an action, you present your holy symbol, and a sphere of twilight emanates from you. The sphere is centered on you, has a 30-foot radius, and is filled with dim light. The sphere moves with you, and it lasts for 1 minute or until you are incapacitated or die. Whenever a creature (including you) ends its turn in the sphere, you can grant that creature one of these benefits:\n\n• You grant it temporary hit points equal to 1d6 plus your cleric level.\n\n• You end one effect on it causing it to be charmed or frightened.", "Característica de 2º nível do Domínio do Crepúsculo\n\nVocê pode usar seu Canalizar Divindade para revigorar seus aliados com um crepúsculo reconfortante.\n\nCom uma ação, você apresenta seu símbolo sagrado, e uma esfera de crepúsculo emana de você. A esfera é centrada em você, tem um raio de 9 metros e é preenchida com penumbra. A esfera se move com você e dura por 1 minuto ou até você ficar incapacitado ou morrer. Sempre que uma criatura (incluindo você) terminar o turno dela na esfera, você pode conceder a essa criatura um dos seguintes benefícios:\n\n• Você concede a ela pontos de vida temporários iguais a 1d6 mais seu nível de clérigo.\n\n• Você encerra um efeito nela que esteja causando a condição enfeitiçado ou amedrontado."],
      [6, 'Steps of Night', 'Passos da Noite', "6th-level Twilight Domain feature\n\nYou can draw on the mystical power of night to rise into the air. As a bonus action when you are in dim light or darkness, you can magically give yourself a flying speed equal to your walking speed for 1 minute. You can use this bonus action a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.", "Característica de 6º nível do Domínio do Crepúsculo\n\nVocê pode recorrer ao poder místico da noite para ascender ao ar. Como uma ação bônus quando você estiver na penumbra ou na escuridão, você pode magicamente conceder a si mesmo um deslocamento de voo igual ao seu deslocamento de caminhada por 1 minuto. Você pode usar essa ação bônus um número de vezes igual ao seu bônus de proficiência, e recupera todos os usos gastos ao terminar um descanso longo."],
      [8, 'Divine Strike', 'Golpe Divino', "At 8th level, you gain the ability to infuse your weapon strikes with divine energy. Once on each of your turns when you hit a creature with a weapon attack, you can cause the attack to deal an extra 1d8 radiant damage to the target. When you reach 14th level, the extra damage increases to 2d8.", "No 8º nível, você ganha a capacidade de impregnar seus golpes com arma com energia divina. Uma vez em cada um de seus turnos, ao acertar uma criatura com um ataque com arma, você pode fazer com que o ataque cause 1d8 de dano radiante extra ao alvo. Ao alcançar o 14º nível, o dano extra aumenta para 2d8."],
      [17, 'Twilight Shroud', 'Mortalha do Crepúsculo', "17th-level Twilight Domain feature\n\nThe twilight that you summon offers a protective embrace: you and your allies have half cover while in the sphere created by your Twilight Sanctuary.", "Característica de 17º nível do Domínio do Crepúsculo\n\nO crepúsculo que você invoca oferece um abraço protetor: você e seus aliados têm meia cobertura enquanto estiverem na esfera criada pelo seu Santuário do Crepúsculo."],
    ],
  },
  druid: {
    shepherd: [
      [2, 'Speech of the Woods', 'Fala da Floresta', "At 2nd level, you gain the ability to converse with beasts and many fey.\n\nYou learn to speak, read, and write Sylvan. In addition, beasts can understand your speech, and you gain the ability to decipher their noises and motions. Most beasts lack the intelligence to convey or understand sophisticated concepts, but a friendly beast could relay what it has seen or heard in the recent past. This ability doesn’t grant you friendship with beasts, though you can combine this ability with gifts to curry favor with them as you would with any nonplayer character.", "No 2º nível, você adquire a habilidade de conversar com feras e muitas fadas.\n\nVocê aprende a falar, ler e escrever Silvestre. Além disso, as feras podem entender sua fala, e você adquire a habilidade de decifrar seus ruídos e movimentos. A maioria das feras carece de inteligência para transmitir ou compreender conceitos sofisticados, mas uma fera amistosa pode relatar o que viu ou ouviu em um passado recente. Essa habilidade não lhe concede amizade com as feras, embora você possa combinar essa habilidade com presentes para obter favores delas, assim como faria com qualquer personagem do mestre."],
      [2, 'Spirit Totem', 'Totem Espiritual', "Starting at 2nd level, you can call forth nature spirits to influence the world around you. As a bonus action, you can magically summon an incorporeal spirit to a point you can see within 60 feet of you. The spirit creates an aura in a 30-foot radius around that point. It counts as neither a creature nor an object, though it has the spectral appearance of the creature it represents.\n\nAs a bonus action, you can move the spirit up to 60 feet to a point you can see.\n\nThe spirit persists for 1 minute or until you’re incapacitated. Once you use this feature, you can’t use it again until you finish a short or long rest.\n\nThe effect of the spirit’s aura depends on the type of spirit you summon from the options below.\n\nBear Spirit. The bear spirit grants you and your allies its might and endurance. Each creature of your choice in the aura when the spirit appears gains temporary hit points equal to 5 + your druid level. In addition, you and your allies gain advantage on Strength checks and Strength saving throws while in the aura.\n\nHawk Spirit.The hawk spirit is a consummate hunter, aiding you and your allies with its keen sight. When a creature makes an attack roll against a target in the spirit’s aura, you can use your reaction to grant advantage to that attack roll. In addition, you and your allies have advantage on Wisdom (Perception) checks while in the aura.\n\nUnicorn Spirit.The unicorn spirit lends its protection to those nearby. You and your allies gain advantage on all ability checks made to detect creatures in the spirit’s aura. In addition, if you cast a spell using a spell slot that restores hit points to any creature inside or outside the aura, each creature of your choice in the aura also regains hit points equal to your druid level.", "A partir do 2º nível, você pode convocar espíritos da natureza para influenciar o mundo ao seu redor. Como uma ação bônus, você pode invocar magicamente um espírito incorpóreo para um ponto que você possa ver a até 18 metros de você. O espírito cria uma aura em um raio de 9 metros ao redor daquele ponto. Ele não conta como criatura nem como objeto, embora tenha a aparência espectral da criatura que representa.\n\nComo uma ação bônus, você pode mover o espírito até 18 metros para um ponto que você possa ver.\n\nO espírito permanece por 1 minuto ou até você ficar incapacitado. Depois de usar essa característica, você não pode usá-la novamente até terminar um descanso curto ou longo.\n\nO efeito da aura do espírito depende do tipo de espírito que você invocar entre as opções abaixo.\n\nEspírito do Urso. O espírito do urso concede a você e aos seus aliados seu vigor e resistência. Cada criatura à sua escolha na aura quando o espírito aparece ganha pontos de vida temporários iguais a 5 + seu nível de druida. Além disso, você e seus aliados ganham vantagem em testes de Força e salvaguardas de Força enquanto estiverem na aura.\n\nEspírito do Falcão. O espírito do falcão é um caçador consumado, ajudando você e seus aliados com sua visão aguçada. Quando uma criatura fizer uma jogada de ataque contra um alvo na aura do espírito, você pode usar sua reação para conceder vantagem àquela jogada de ataque. Além disso, você e seus aliados têm vantagem em testes de Sabedoria (Percepção) enquanto estiverem na aura.\n\nEspírito do Unicórnio. O espírito do unicórnio concede sua proteção àqueles que estão por perto. Você e seus aliados ganham vantagem em todos os testes de habilidade feitos para detectar criaturas na aura do espírito. Além disso, se você conjurar uma magia usando um espaço de magia que recupere pontos de vida de qualquer criatura dentro ou fora da aura, cada criatura à sua escolha na aura também recupera pontos de vida iguais ao seu nível de druida."],
      [6, 'Mighty Summoner', 'Invocador Poderoso', "Starting at 6th level, beasts and fey that you conjure are more resilient than normal. Any beast or fey summoned or created by a spell that you cast gains the following benefits:\n\n• The creature appears with more hit points than normal: 2 extra hit points per Hit Die it has.\n\n• The damage from its natural weapons is considered magical for the purpose of overcoming immunity and resistance to nonmagical attacks and damage.", "A partir do 6º nível, as feras e fadas que você conjura são mais resistentes que o normal. Qualquer fera ou fada invocada ou criada por uma magia que você conjurar ganha os seguintes benefícios:\n\n• A criatura surge com mais pontos de vida que o normal: 2 pontos de vida adicionais por Dado de Vida que ela possuir.\n\n• O dano de suas armas naturais é considerado mágico com o propósito de superar imunidade e resistência a ataques e danos não mágicos."],
      [10, 'Guardian Spirit', 'Espírito Guardião', "Beginning at 10th level, your Spirit Totem safeguards the beasts and fey that you call forth with your magic. When a beast or fey that you summoned or created with a spell ends its turn in your Spirit Totem aura, that creature regains a number of hit points equal to half your druid level.", "A partir do 10º nível, seu Totem Espiritual protege as feras e fadas que você evoca com sua magia. Quando uma fera ou fada que você invocou ou criou com uma magia terminar o turno dela na aura do seu Totem Espiritual, essa criatura recupera uma quantidade de pontos de vida igual à metade do seu nível de druida."],
      [14, 'Faithful Summons', 'Invocações Fiéis', "Starting at 14th level, the nature spirits you commune with protect you when you are the most defenseless. If you are reduced to 0 hit points or are incapacitated against your will, you can immediately gain the benefits of conjure animals as if it were cast using a 9th-level spell slot. It summons four beasts of your choice that are challenge rating 2 or lower. The conjured beasts appear within 20 feet of you. If they receive no commands from you, they protect you from harm and attack your foes. The spell lasts for 1 hour, requiring no concentration, or until you dismiss it (no action required).\n\nOnce you use this feature, you can’t use it again until you finish a long rest.", "A partir do 14º nível, os espíritos da natureza com os quais você comunga protegem você quando estiver mais indefeso. Se você for reduzido a 0 pontos de vida ou ficar incapacitado contra a sua vontade, você pode imediatamente obter os benefícios de conjurar animais como se tivesse sido conjurada usando um espaço de magia de 9º círculo. Ela invoca quatro feras de sua escolha que possuam nível de desafio 2 ou menor. As feras conjuradas aparecem a até 6 metros de você. Se elas não receberem comandos seus, protegerão você de perigos e atacarão seus inimigos. A magia dura por 1 hora, não exigindo concentração, ou até você dispensá-la (nenhuma ação necessária).\n\nDepois de usar essa característica, você não pode usá-la novamente até terminar um descanso longo."],
    ],
  },
  fighter: {
    banneret: [
      [3, 'Rallying Cry', 'Grito de Reunião', "When you choose this archetype at 3rd level, you learn how to inspire your allies to fight on past their injuries.\n\nWhen you use your Second Wind feature, you can choose up to three creatures within 60 feet of you that are allied with you. Each one regains hit points equal to your fighter level, provided that the creature can see or hear you.", "Quando você escolhe este arquétipo no 3º nível, você aprende a inspirar seus aliados a lutar além de seus ferimentos.\n\nQuando você usa sua característica Retomar o Fôlego, pode escolher até três criaturas a até 18 metros de você que sejam suas aliadas. Cada uma recupera pontos de vida iguais ao seu nível de guerreiro, desde que a criatura possa ver ou ouvir você."],
      [7, 'Royal Envoy', 'Emissário Real', "A Purple Dragon knight serves as an envoy of the Cormyrean crown. Knights of high standing are expected to conduct themselves with grace.\n\nAt 7th level, you gain proficiency in the Persuasion skill. If you are already proficient in it, you gain proficiency in one of the following skills of your choice: Animal Handling, Insight, Intimidation, or Performance.\n\nYour proficiency bonus is doubled for any ability check you make that uses Persuasion. You receive this benefit regardless of the skill proficiency you gain from this feature.", "Um cavaleiro do Dragão Púrpura serve como um enviado da coroa de Cormyr. Espera-se que cavaleiros de alta posição se portem com graça.\n\nNo 7º nível, você ganha proficiência na perícia Persuasão. Se você já for proficiente nela, ganha proficiência em uma das seguintes perícias à sua escolha: Adestrar Animais, Intuição, Intimidação ou Atuação.\n\nSeu bônus de proficiência é dobrado para qualquer teste de atributo que você fizer que use Persuasão. Você recebe este benefício independentemente da proficiência em perícia que ganhar desta característica."],
      [10, 'Inspiring Surge', 'Surto Inspirador', "Starting at 10th level, when you use your Action Surge feature, you can choose one creature within 60 feet of you that is allied with you. That creature can make one melee or ranged weapon attack with its reaction, provided that it can see or hear you.\n\nStarting at 18th level, you can choose two allies within 60 feet of you, rather than one.", "A partir do 10º nível, quando você usa sua característica Surto de Ação, você pode escolher uma criatura a até 18 metros de você que seja sua aliada. Aquela criatura pode fazer um ataque com arma corpo a corpo ou à distância com a reação dela, desde que possa vê-lo ou ouvi-lo.\n\nA partir do 18º nível, você pode escolher dois aliados a até 18 metros de você, em vez de um."],
      [15, 'Bulwark', 'Baluarte', "Beginning at 15th level, you can extend the benefit of your Indomitable feature to an ally. When you decide to use Indomitable to reroll an Intelligence, a Wisdom, or a Charisma saving throw and you aren't incapacitated, you can choose one ally within 60 feet of you that also failed its saving throw against the same effect. If that creature can see or hear you, it can reroll its saving throw and must use the new roll.", "A partir do 15º nível, você pode estender o benefício da sua característica Indomável a um aliado. Quando você decidir usar Indomável para rolar novamente uma salvaguarda de Inteligência, Sabedoria ou Carisma e não estiver incapacitado, pode escolher um aliado a até 18 metros de você que também tenha falhado na salvaguarda dele contra o mesmo efeito. Se aquela criatura puder vê-lo ou ouvi-lo, ela pode rolar novamente a salvaguarda dela e deve usar a nova rolagem."],
      [18, 'Inspiring Surge (two allies)', 'Surto Inspirador (dois aliados)', "Starting at 10th level, when you use your Action Surge feature, you can choose one creature within 60 feet of you that is allied with you. That creature can make one melee or ranged weapon attack with its reaction, provided that it can see or hear you.\n\nStarting at 18th level, you can choose two allies within 60 feet of you, rather than one.", "A partir do 10º nível, quando você usa sua característica Surto de Ação, você pode escolher uma criatura a até 18 metros de você que seja sua aliada. Aquela criatura pode fazer um ataque com arma corpo a corpo ou à distância com a reação dela, desde que possa vê-lo ou ouvi-lo.\n\nA partir do 18º nível, você pode escolher dois aliados a até 18 metros de você, em vez de um."],
    ],
    arcanearcher: [
      [3, 'Arcane Archer Lore', 'Saber do Arqueiro Arcano', "At 3rd level, you learn magical theory or some of the secrets of nature—typical for practitioners of this elven martial tradition. You choose to gain proficiency in either the Arcana or the Nature skill, and you choose to learn either the prestidigitation or the druidcraft cantrip.", "No 3º nível, você aprende teoria mágica ou alguns dos segredos da natureza — típico para praticantes desta tradição marcial élfica. Você escolhe ganhar proficiência na perícia Arcanismo ou Natureza, e escolhe aprender o truque prestidigitação ou o truque artesanato druídico."],
      [3, 'Arcane Shot', 'Disparo Arcano', "At 3rd level, you learn to unleash special magical effects with some of your shots. When you gain this feature, you learn two Arcane Shot options of your choice.\n\nOnce per turn when you fire an arrow from a shortbow or longbow as part of the Attack action, you can apply one of your Arcane Shot options to that arrow. You decide to use the option when the arrow hits a creature, unless the option doesn’t involve an attack roll. You have two uses of this ability, and you regain all expended uses of it when you finish a short or long rest.\n\nYou gain an additional Arcane Shot option of your choice when you reach certain levels in this class: 7th, 10th, 15th, and 18th level. Each option also improves when you become an 18th—level fighter.", "No 3º nível, você aprende a liberar efeitos mágicos especiais com alguns de seus disparos. Ao obter esta característica, você aprende duas opções de Tiro Arcano à sua escolha.\nment>\n\nNo 3º nível, você aprende a liberar efeitos mágicos especiais com alguns de seus disparos. Ao obter esta característica, você aprende duas opções de Tiro Arcano à sua escolha.\n\nUma vez por turno, ao disparar uma flecha com um arco curto ou arco longo como parte da ação de Ataque, você pode aplicar uma de suas opções de Tiro Arcano a essa flecha. Você decide usar a opção quando a flecha atinge uma criatura, a menos que a opção não envolva uma jogada de ataque. Você tem dois usos desta habilidade e recupera todos os usos gastos ao terminar um descanso curto ou longo.\n\nVocê ganha uma opção adicional de Tiro Arcano à sua escolha ao atingir determinados níveis nesta classe: 7º, 10º, 15º e 18º nível. Cada opção também melhora quando você se torna um guerreiro de 18º nível."],
      [7, 'Magic Arrow', 'Flecha Mágica', "At 7th level, you gain the ability to infuse arrows with magic. Whenever you fire a nonmagical arrow from a shortbow or longbow, you can make it magical for the purpose of overcoming resistance and immunity to nonmagical attacks and damage. The magic fades from the arrow immediately after it hits or misses its target.", "No 7º nível, você ganha a habilidade de infundir flechas com magia. Sempre que disparar uma flecha não mágica de um arco curto ou arco longo, você pode torná-la mágica com o propósito de superar resistência e imunidade a ataques e danos não mágicos. A magia desaparece da flecha imediatamente após ela atingir ou errar o alvo."],
      [7, 'Curving Shot', 'Disparo Curvo', "At 7th level, you learn how to direct an errant arrow toward a new target. When you make an attack roll with a magic arrow and miss, you can use a bonus action to reroll the attack roll against a different target within 60 feet of the original target.", "No 7º nível, você aprende como direcionar uma flecha desviada em direção a um novo alvo. Quando você fizer uma jogada de ataque com uma flecha mágica e errar, você pode usar uma ação bônus para rolar novamente a jogada de ataque contra um alvo diferente a até 18 metros do alvo original."],
      [10, 'Additional Arcane Shot Option', 'Opção Adicional de Disparo Arcano', "At 3rd level, you learn to unleash special magical effects with some of your shots. When you gain this feature, you learn two Arcane Shot options of your choice.\nment>\n\nAt 3rd level, you learn to unleash special magical effects with some of your shots. When you gain this feature, you learn two Arcane Shot options of your choice.\n\nOnce per turn when you fire an arrow from a shortbow or longbow as part of the Attack action, you can apply one of your Arcane Shot options to that arrow. You decide to use the option when the arrow hits a creature, unless the option doesn’t involve an attack roll. You have two uses of this ability, and you regain all expended uses of it when you finish a short or long rest.\n\nYou gain an additional Arcane Shot option of your choice when you reach certain levels in this class: 7th, 10th, 15th, and 18th level. Each option also improves when you become an 18th—level fighter.", "No 3º nível, você aprende a liberar efeitos mágicos especiais com alguns de seus disparos. Ao obter esta característica, você aprende duas opções de Tiro Arcano à sua escolha.\nment>\n\nNo 3º nível, você aprende a liberar efeitos mágicos especiais com alguns de seus disparos. Ao obter esta característica, você aprende duas opções de Tiro Arcano à sua escolha.\n\nUma vez por turno, ao disparar uma flecha com um arco curto ou arco longo como parte da ação de Ataque, você pode aplicar uma de suas opções de Tiro Arcano a essa flecha. Você decide usar a opção quando a flecha atinge uma criatura, a menos que a opção não envolva uma jogada de ataque. Você tem dois usos desta habilidade e recupera todos os usos gastos ao terminar um descanso curto ou longo.\n\nVocê ganha uma opção adicional de Tiro Arcano à sua escolha ao atingir determinados níveis nesta classe: 7º, 10º, 15º e 18º nível. Cada opção também melhora quando você se torna um guerreiro de 18º nível."],
      [15, 'Ever-Ready Shot', 'Disparo Sempre Pronto', "Starting at 15th level, your magical archery is available whenever battle starts. If you roll initiative and have no uses of Arcane Shot remaining, you regain one use of it.", "A partir do 15º nível, sua arquearia mágica está disponível sempre que uma batalha começar. Se você rolar iniciativa e não tiver nenhum uso restante de Tiro Arcano, você recupera um uso dele."],
      [18, 'Improved Shots', 'Disparos Aprimorados', "Starting at 15th level, your magical archery is available whenever battle starts. If you roll initiative and have no uses of Arcane Shot remaining, you regain one use of it.", "A partir do 15º nível, sua arquearia mágica está disponível sempre que uma batalha começar. Se você rolar iniciativa e não tiver nenhum uso restante de Tiro Arcano, você recupera um uso dele."],
    ],
    cavalier: [
      [3, 'Bonus Proficiency', 'Proficiência Adicional', "When you choose this archetype at 3rd level, you gain proficiency in one of the following skills of your choice: Animal Handling, History, Insight, Performance, or Persuasion. Alternatively, you learn one language of your choice.", "Quando você escolhe este arquétipo no 3º nível, ganha proficiência em uma das seguintes perícias à sua escolha: Adestrar Animais, História, Intuição, Atuação ou Persuasão. Alternativamente, você aprende um idioma à sua escolha."],
      [3, 'Born to the Saddle', 'Nascido para a Sela', "Starting at 3rd level, your mastery as a rider becomes apparent. You have advantage on saving throws made to avoid falling off your mount. If you fall off your mount and descend no more than 10 feet, you can land on your feet if you’re not incapacitated.\n\nFinally, mounting or dismounting a creature costs you only 5 feet of movement, rather than half your speed.", "A partir do 3º nível, sua maestria como cavaleiro se torna evidente. Você tem vantagem em salvaguardas feitas para evitar cair da sua montaria. Se você cair da sua montaria e descer não mais do que 3 metros, você pode aterrissar em pé se não estiver incapacitado.\n\nPor fim, montar ou desmontar de uma criatura custa apenas 1,5 metro de movimento para você, em vez de metade do seu deslocamento."],
      [3, 'Unwavering Mark', 'Marca Inabalável', "Starting at 3rd level, you can menace your foes, foiling their attacks and punishing them for harming others. When you hit a creature with a melee weapon attack, you can mark the creature until the end of your next turn. This effect ends early if you are incapacitated or you die, or if someone else marks the creature.\n\nWhile it is within 5 feet of you, a creature marked by you has disadvantage on any attack roll that doesn’t target you.\n\nIn addition, if a creature marked by you deals damage to anyone other than you, you can make a special melee weapon attack against the marked creature as a bonus action on your next turn. You have advantage on the attack roll, and if it hits, the attacks weapon deals extra damage to the target equal to half your fighter level. Regardless of the number of creatures you mark, you can make this special attack a number of times equal to your Strength modifier (minimum of once), and you regain all expended uses of it when you finish a long rest.", "A partir do 3º nível, você pode ameaçar seus inimigos, frustrando os ataques deles e punindo-os por ferir outros. Quando atinge uma criatura com um ataque corpo a corpo com arma, você pode marcar a criatura até o final do seu próximo turno. Esse efeito termina prematuramente se você ficar incapacitado ou morrer, ou se outra pessoa marcar a criatura.\n\nEnquanto estiver a até 1,5 metro de você, uma criatura marcada por você tem desvantagem em qualquer jogada de ataque que não tenha você como alvo.\n\nAlém disso, se uma criatura marcada por você causar dano a qualquer pessoa que não seja você, você pode realizar um ataque corpo a corpo com arma especial contra a criatura marcada com uma ação bônus no seu próximo turno. Você tem vantagem na jogada de ataque e, se acertar, a arma do ataque causa dano extra ao alvo igual à metade do seu nível de guerreiro. Independentemente do número de criaturas que você marcar, você pode realizar este ataque especial um número de vezes igual ao seu modificador de Força (mínimo de uma vez) e recupera todos os usos gastos dele ao terminar um descanso longo."],
      [7, 'Warding Maneuver', 'Manobra de Proteção', "At 7th level, you learn to fend off strikes directed at you, your mount, or other creatures nearby. If you or a creature you can see within 5 feet of you is hit by an attack, you can roll 1d8 as a reaction if you’re wielding a melee weapon or a shield. Roll the die, and add the number rolled to the target’s AC against that attack. If the attack still hits, the target has resistance against the attack’s damage.\n\nYou can use this feature a number of times equal to your Constitution modifier (minimum of once), and you regain all expended uses of it when you finish a long rest.", "No 7º nível, você aprende a repelir golpes direcionados a você, à sua montaria ou a outras criaturas próximas. Se você ou uma criatura que possa ver a até 1,5 metro de você for atingido por um ataque, você poderá rolar 1d8 como uma reação se estiver empunhando uma arma corpo a corpo ou um escudo. Role o dado e adicione o número rolado à CA do alvo contra aquele ataque. Se o ataque ainda assim acertar, o alvo terá resistência contra o dano do ataque.\n\nVocê pode usar esta característica um número de vezes igual ao seu modificador de Constituição (mínimo de uma vez) e recupera todos os usos gastos ao terminar um descanso longo."],
      [10, 'Hold the Line', 'Segurar a Linha', "At 10th level, you become a master of locking down your enemies. Creatures provoke an opportunity attack from you when they move 5 feet or more while within your reach, and if you hit a creature with an opportunity attack, the target’s speed is reduced to 0 until the end of the current turn.", "No 10º nível, você se torna um mestre em conter seus inimigos. As criaturas provocam um ataque de oportunidade seu quando se movem 1,5 metro ou mais enquanto estiverem dentro do seu alcance, e se você atingir uma criatura com um ataque de oportunidade, o deslocamento do alvo é reduzido a 0 até o final do turno atual."],
      [15, 'Ferocious Charger', 'Investida Feroz', "Starting at 15th level, you can run down your foes, whether you’re mounted or not. If you move at least 10 feet in a straight line right before attacking a creature and you hit it with the attack, that target must succeed on a Strength saving throw (DC 8 + your proficiency bonus + your Strength modifier) or be knocked prone. You can use this feature only once on each of your turns.", "A partir do 15º nível, você pode atropelar seus inimigos, esteja você montado ou não. Se você se mover pelo menos 3 metros em linha reta logo antes de atacar uma criatura e atingi-la com o ataque, esse alvo deve ser bem-sucedido em uma salvaguarda de Força (CD 8 + seu bônus de proficiência + seu modificador de Força) ou ficará caído. Você pode usar esta característica apenas uma vez em cada um dos seus turnos."],
      [18, 'Vigilant Defender', 'Defensor Vigilante', "Starting at 18th level, you respond to danger with extraordinary vigilance. In combat, you get a special reaction that you can take once on every creature’s turn, except your turn. You can use this special reaction only to make an opportunity attack, and you can’t use it on the same turn that you take your normal reaction.", "A partir do 18º nível, você responde ao perigo com vigilância extraordinária. Em combate, você ganha uma reação especial que pode realizar uma vez no turno de cada criatura, exceto no seu turno. Você pode usar esta reação especial apenas para fazer um ataque de oportunidade, e não pode usá-la no mesmo turno em que usar sua reação normal."],
    ],
    samurai: [
      [3, 'Bonus Proficiency', 'Proficiência Adicional', "When you choose this archetype at 3rd level, you gain proficiency in one of the following skills of your choice: Animal Handling, History, Insight, Performance, or Persuasion. Alternatively, you learn one language of your choice.", "Quando você escolhe este arquétipo no 3º nível, ganha proficiência em uma das seguintes perícias à sua escolha: Adestrar Animais, História, Intuição, Atuação ou Persuasão. Alternativamente, você aprende um idioma à sua escolha."],
      [3, 'Fighting Spirit', 'Espírito de Luta', "Starting at 3rd level, your intensity in battle can shield you and help you strike true. As a bonus action on your turn, you can give yourself advantage on weapon attack rolls until the end of the current turn. When you do so, you also gain 5 temporary hit points. The number of temporary hit points increases when you reach certain levels in this class, increasing to 10 at 10th level and 15 at 15th level.\n\nYou can use this feature three times, and you regain all expended uses of it when you finish a long rest.", "A partir do 3º nível, sua intensidade em batalha pode protegê-lo e ajudá-lo a golpear com precisão. Como uma ação bônus em seu turno, você pode conceder a si mesmo vantagem em jogadas de ataque com armas até o final do turno atual. Ao fazer isso, você também ganha 5 pontos de vida temporários. A quantidade de pontos de vida temporários aumenta quando você atinge certos níveis nesta classe, aumentando para 10 no 10º nível e 15 no 15º nível.\n\nVocê pode usar esta característica três vezes, e recupera todos os usos gastos dela ao terminar um descanso longo."],
      [7, 'Elegant Courtier', 'Cortesão Elegante', "Starting at 7th level, your discipline and attention to detail allow you to excel in social situations. Whenever you make a Charisma (Persuasion) check, you gain a bonus to the check equal to your Wisdom modifier.\n\nYour self-control also causes you to gain proficiency in Wisdom saving throws. If you already have this proficiency, you instead gain proficiency in Intelligence or Charisma saving throws (your choice).", "A partir do 7º nível, sua disciplina e atenção aos detalhes permitem que você se destaque em situações sociais. Sempre que fizer um teste de Carisma (Persuasão), você ganha um bônus no teste igual ao seu modificador de Sabedoria.\n\nSeu autocontrole também faz com que você ganhe proficiência em salvaguardas de Sabedoria. Se você já tiver essa proficiência, em vez disso ganha proficiência em salvaguardas de Inteligência ou Carisma (sua escolha)."],
      [10, 'Tireless Spirit', 'Espírito Incansável', "Starting at 10th level, when you roll initiative and have no uses of Fighting Spirit remaining, you regain one use.", "A partir do 10º nível, quando você rolar iniciativa e não tiver nenhum uso restante de Espírito de Luta, você recupera um uso."],
      [15, 'Rapid Strike', 'Golpe Rápido', "Starting at 15th level, you learn to trade accuracy for swift strikes. If you take the Attack action on your turn and have advantage on an attack roll against one of the targets, you can forgo the advantage for that roll to make an additional weapon attack against that target, as part of the same action. You can do so no more than once per turn.", "A partir do 15º nível, você aprende a trocar precisão por ataques rápidos. Se você realizar a ação de Ataque em seu turno e tiver vantagem em uma jogada de ataque contra um dos alvos, você pode abrir mão da vantagem para essa jogada para fazer um ataque adicional com arma contra esse alvo, como parte da mesma ação. Você não pode fazer isso mais de uma vez por turno."],
      [18, 'Strength Before Death', 'Força Antes da Morte', "Starting at 18th level, your fighting spirit can delay the grasp of death. If you take damage that reduces you to 0 hit points and doesn’t kill you outright, you can use your reaction to delay falling unconscious, and you can immediately take an extra turn, interrupting the current turn. While you have 0 hit points during that extra turn, taking damage causes death saving throw failures as normal, and three death saving throw failures can still kill you. When the extra turn ends, you fall unconscious if you still have 0 hit points.\n\nOnce you use this feature, you can’t use it again until you finish a long rest.", "A partir do 18º nível, seu espírito de luta pode adiar o abraço da morte. Se você sofrer dano que o reduza a 0 pontos de vida e não o mate instantaneamente, você pode usar sua reação para adiar cair inconsciente, e pode realizar imediatamente um turno extra, interrompendo o turno atual. Enquanto tiver 0 pontos de vida durante esse turno extra, sofrer dano causa falhas em salvaguardas contra a morte normalmente, e três falhas em salvaguardas contra a morte ainda podem matá-lo. Quando o turno extra terminar, você cai inconsciente se ainda tiver 0 pontos de vida.\n\nAssim que usar esta característica, você não pode usá-la novamente até terminar um descanso longo."],
    ],
    echoknight: [
      [3, 'Manifest Echo', 'Manifestar Eco', "3rd-level Echo Knight feature\n\nYou can use a bonus action to magically manifest an echo of yourself in an unoccupied space you can see within 15 feet of you. This echo is a magical, translucent, gray image of you that lasts until it is destroyed, until you dismiss it as a bonus action, until you manifest another echo, or until you’re incapacitated.\n\nYour echo has AC 14 + your proficiency bonus, 1 hit point, and immunity to all conditions. If it has to make a saving throw, it uses your saving throw bonus for the roll. It is the same size as you, and it occupies its space. On your turn, you can mentally command the echo to move up to 30 feet in any direction (no action required). If your echo is ever more than 30 feet away from you at the end of your turn, it is destroyed.\n\nYou can use the echo in the following ways:\n\n• As a bonus action, you can teleport, magically swapping places with your echo at a cost of 15 feet of your movement, regardless of the distance between the two of you.\n\n• When you take the attack action on your turn, any attack you make with that action can originate from your space or the echo’s space. You make this choice for each attack.\n\n• When a creature that you can see within 5 feet of your echo moves at least 5 feet away from it, you can use your reaction to make an opportunity attack against that creature as if you were in the echo’s space.", "Característica de 3º nível do Cavaleiro do Eco\n\nVocê pode usar uma ação bônus para manifestar magicamente um eco de si mesmo em um espaço desocupado que possa ver a até 4,5 metros de você. Este eco é uma imagem mágica, translúcida e cinzenta de você que dura até ser destruído, até você dispensá-lo com uma ação bônus, até você manifestar outro eco ou até ficar incapacitado.\n\nSeu eco tem CA 14 + seu bônus de proficiência, 1 ponto de vida e imunidade a todas as condições. Se ele precisar fazer uma salvaguarda, ele usa o seu bônus de salvaguarda para a rolagem. Ele tem o mesmo tamanho que você e ocupa o espaço dele. No seu turno, você pode ordenar mentalmente que o eco se mova até 9 metros em qualquer direção (nenhuma ação necessária). Se o seu eco estiver a mais de 9 metros de você ao final do seu turno, ele é destruído.\n\nVocê pode usar o eco das seguintes maneiras:\n\n• Com uma ação bônus, você pode se teletransportar, trocando magicamente de lugar com seu eco a um custo de 4,5 metros do seu deslocamento, independentemente da distância entre vocês dois.\n\n• Quando você realiza a ação de Ataque no seu turno, qualquer ataque feito com essa ação pode se originar do seu espaço ou do espaço do eco. Você faz essa escolha para cada ataque.\nção bônus, você pode se teletransportar, trocando magicamente de lugar com seu eco a um custo de 4,5 metros do seu deslocamento, independentemente da distância entre vocês dois.\n\n• Quando você realiza a ação de Ataque no seu turno, qualquer ataque feito com essa ação pode se originar do seu espaço ou do espaço do eco. Você faz essa escolha para cada ataque.\n\n• Quando uma criatura que você possa ver a até 1,5 metro do seu eco se afastar pelo menos 1,5 metro dele, você pode usar sua reação para fazer um ataque de oportunidade contra essa criatura como se estivesse no espaço do eco."],
      [3, 'Unleash Incarnation', 'Liberar Encarnação', "3rd-level Echo Knight feature\n\nYou can heighten your echo’s fury. Whenever you take the Attack action, you can make one additional melee attack from the echo’s position.\n\nYou can use this feature a number of times equal to your Constitution modifier (a minimum of once). You regain all expended uses when you finish a long rest.", "Característica de 3º nível do Cavaleiro do Eco\n\nVocê pode intensificar a fúria do seu eco. Sempre que realizar a ação de Ataque, você pode fazer um ataque corpo a corpo adicional a partir da posição do eco.\n\nVocê pode usar esta característica um número de vezes igual ao seu modificador de Constituição (mínimo de uma vez). Você recupera todos os usos gastos ao terminar um descanso longo."],
      [7, 'Echo Avatar', 'Avatar do Eco', "7th-level Echo Knight feature\n\nYou can temporary transfer your consciousness to your echo. As an action, you can see through your echo’s eyes and hear trough its ears. During this time, you are deafened and blinded. You can sustain this effect for up to 10 minutes, and you can end it at any time (requires no action). While your echo is being used in this way, it can be up to 1,000 feet away from you without being destroyed.", "Característica de 7º nível do Cavaleiro do Eco\n\nVocê pode transferir temporariamente sua consciência para o seu eco. Como uma ação, você pode ver através dos olhos do seu eco e ouvir através dos ouvidos dele. Durante esse período, você fica surdo e cego. Você pode manter esse efeito por até 10 minutos, e pode encerrá-lo a qualquer momento (nenhuma ação necessária). Enquanto o seu eco estiver sendo usado dessa forma, ele pode estar a até 300 metros de distância de você sem ser destruído."],
      [10, 'Shadow Martyr', 'Mártir das Sombras', "10th-level Echo Knight feature\n\nYou can make your echo throw itself in front of an attack directed at another creature that you can see. Before the attack roll is made, you can use your reaction to teleport the echo to an unoccupied space withing 5 feet of the targeted creature. The attack roll that triggered the reaction is instead made against your echo.\n\nOnce you use this feature, you can’t use it again until you finish a short or long rest.", "Característica de 10º nível do Cavaleiro do Eco\n\nVocê pode fazer com que seu eco se lance na frente de um ataque direcionado a outra criatura que você possa ver. Antes de a jogada de ataque ser feita, você pode usar sua reação para teletransportar o eco para um espaço desocupado a até 1,5 metro da criatura visada. A jogada de ataque que desencadeou a reação é feita contra o seu eco em vez disso.\n\nAssim que usar esta característica, você não pode usá-la novamente até terminar um descanso curto ou longo."],
      [15, 'Reclaim Potential', 'Recuperar Potencial', "15th-level Echo Knight feature\n\nYou’ve learned to absorb the fleeting magic of your echo. When an echo of yours is destroyed by taking damage, you can gain a number of temporary hit points equal to 2d6 + your Constitution modifier, provided you don’t already have temporary hit points.\n\nYou can use this feature a number of times equal to your Constitution modifier (a minimum of once). You regain all expended uses when you finish a long rest.", "Característica de 15º nível do Cavaleiro do Eco\n\nVocê aprendeu a absorver a magia fugaz do seu eco. Quando um eco seu for destruído ao sofrer dano, você pode ganhar uma quantidade de pontos de vida temporários igual a 2d6 + seu modificador de Constituição, desde que já não tenha pontos de vida temporários.\n\nVocê pode usar esta característica um número de vezes igual ao seu modificador de Constituição (mínimo de uma vez). Você recupera todos os usos gastos ao terminar um descanso longo."],
      [18, 'Legion of One', 'Legião de Um', "18th-level Echo Knight feature\n\nYou can use a bonus action to create two echoes with your Manifest Echo feature, and these echoes can coexist. If you try to create a third echo, the previous two echoes are destroyed. Anything you can do from one echo’s position can be done from the other’s instead.\n\nIn addition, when you roll initiative and have no uses of your Unleash Incarnation feature left, you regain one use of that feature.", "Característica de 18º nível do Cavaleiro do Eco\n\nVocê pode usar uma ação bônus para criar dois ecos com sua característica Manifestar Eco, e esses ecos podem coexistir. Se tentar criar um terceiro eco, os dois ecos anteriores são destruídos. Qualquer coisa que você possa fazer a partir da posição de um eco pode ser feita a partir da do outro.\n\nAlém disso, quando rolar iniciativa e não tiver mais usos restantes da sua característica Liberar Encarnação, você recupera um uso dessa característica."],
    ],
    psiwarrior: [
      [3, 'Psionic Power', 'Poder Psiônico', "3rd-level Psi Warrior feature\n\nYou harbor a wellspring of psionic energy within yourself. This energy is represented by your Psionic Energy dice, which are each a d6. You have a number of these dice equal to twice your proficiency bonus, and they fuel various psionic powers you have, which are detailed below.\n\nSome of your powers expend the Psionic Energy die they use, as specified in a power’s description, and you can’t use a power if it requires you to use a die when your dice are all expended. You regain all your expended Psionic Energy dice when you finish a long rest. In addition, as a bonus action, you can regain one expended Psionic Energy die, but you can’t do so again until you finish a short or long rest.\n\nWhen you reach certain levels in this class, the size of your Psionic Energy dice increases: at 5th level (d8), 11th level (d10), and 17th level (d12).\n\nThe powers below use your Psionic Energy dice.\n\nProtective Field. When you or another creature you can see within 30 feet of you takes damage, you can use your reaction to expend one Psionic Energy die, roll the die, and reduce the damage taken by the number rolled plus your Intelligence modifier (minimum reduction of 1), as you create a momentary shield of telekinetic force.\n\nPsionic Strike. You can propel your weapons with psionic force. Once on each of your turns, immediately after you hit a target within 30 feet of you with an attack and deal damage to it with a weapon, you can expend one Psionic Energy die, rolling it and dealing force damage to the target equal to the number rolled plus your Intelligence modifier.\n\nTelekinetic Movement. You can move an object or a creature with your mind. As an action, you target one loose object that is Large or smaller or one willing creature, other than yourself. If you can see the target and it is within 30 feet of you, you can move it up to 30 feet to an unoccupied space you can see. Alternatively, if it is a Tiny object, you can move it to or from your hand. Either way, you can move the target horizontally, vertically, or both. Once you take this action, you can’t do so again until you finish a short or long rest, unless you expend a Psionic Energy die to take it again.", "Característica de 3º nível do Guerreiro Psíquico\n\nVocê abriga uma fonte de energia psiônica dentro de si. Essa energia é representada por seus Dados de Energia Psiônica, que são dados d6. Você possui uma quantidade desses dados igual ao dobro do seu bônus de proficiência, e eles abastecem vários poderes psiônicos que você possui, os quais estão detalhados abaixo.\n\nAlguns dos seus poderes gastam o Dado de Energia Psiônica que utilizam, conforme especificado na descrição de um poder, e você não pode usar um poder se ele exigir o uso de um dado quando todos os seus dados estiverem gastos. Você recupera todos os seus Dados de Energia Psiônica gastos ao terminar um descanso longo. Além disso, com uma ação bônus, você pode recuperar um Dado de Energia Psiônica gasto, mas não poderá fazer isso novamente até terminar um descanso curto ou longo.\ncificado na descrição de um poder, e você não pode usar um poder se ele exigir o uso de um dado quando todos os seus dados estiverem gastos. Você recupera todos os seus Dados de Energia Psiônica gastos ao terminar um descanso longo. Além disso, com uma ação bônus, você pode recuperar um Dado de Energia Psiônica gasto, mas não poderá fazer isso novamente até terminar um descanso curto ou longo.\n\nAo atingir determinados níveis nesta classe, o tamanho dos seus Dados de Energia Psiônica aumenta: no 5º nível (d8), 11º nível (d10) e 17º nível (d12).\n\nOs poderes abaixo usam seus Dados de Energia Psiônica.\n\nCampo Protetor. Quando você ou outra criatura que possa ver a até 9 metros de você sofrer dano, pode usar sua reação para gastar um Dado de Energia Psiônica, rolar o dado e reduzir o dano sofrido pelo número rolado mais o seu modificador de Inteligência (redução mínima de 1), criando um escudo momentâneo de força telecinética.\n\nGolpe Psiônico. Você pode impulsionar suas armas com força psiônica. Uma vez em cada um de seus turnos, imediatamente após acertar um alvo a até 9 metros de você com um ataque e causar dano a ele com uma arma, você pode gastar um Dado de Energia Psiônica, rolando-o e causando dano de energia ao alvo igual ao número rolado mais o seu modificador de Inteligência.\n\nMovimento Telecinético. Você pode mover um objeto ou uma criatura com a sua mente. Com uma ação, você escolhe como alvo um objeto solto que seja Grande ou menor ou uma criatura voluntária além de você. Se puder ver o alvo e ele estiver a até 9 metros de você, poderá movê-lo até 9 metros para um espaço desocupado que possa ver. Como alternativa, se for um objeto Miúdo, poderá movê-lo para a sua mão ou a partir dela. De qualquer maneira, você pode mover o alvo horizontalmente, verticalmente ou em ambas as direções. Depois de realizar esta ação, você não poderá fazê-lo novamente até terminar um descanso curto ou longo, a menos que gaste um Dado de Energia Psiônica para realizá-la de novo."],
      [7, 'Telekinetic Adept', 'Adepto Telecinético', "7th-level Psi Warrior feature\n\nYou have mastered new ways to use your telekinetic abilities, detailed below.\n\nPsi-Powered Leap. As a bonus action, you can propel your body with your mind. You gain a flying speed equal to twice your walking speed until the end of the current turn. Once you take this bonus action, you can’t do so again until you finish a short or long rest, unless you expend a Psionic Energy die to take it again.\n\nTelekinetic Thrust. When you deal damage to a target with your Psionic Strike, you can force the target to make a Strength saving throw against a DC equal to 8 + your proficiency bonus + your Intelligence modifier. If the save fails, you can knock the target prone or move it up to 10 feet in any direction horizontally.", "Característica de 7º nível do Guerreiro Psíquico\n\nVocê dominou novas maneiras de usar suas habilidades telecinéticas, detalhadas abaixo.\n\nSalto Potencializado por Psi. Com uma ação bônus, você pode impulsionar seu corpo com a mente. Você ganha um deslocamento de voo igual ao dobro do seu deslocamento de caminhada até o final do turno atual. Depois de realizar esta ação bônus, você não poderá fazê-lo novamente até terminar um descanso curto ou longo, a menos que gaste um Dado de Energia Psiônica para usá-la de novo.\n\nEmpurrão Telecinético. Quando você causar dano a um alvo com seu Golpe Psiônico, poderá forçar o alvo a fazer uma salvaguarda de Força contra uma CD igual a 8 + seu bônus de proficiência + seu modificador de Inteligência. Se falhar na salvaguarda, você poderá deixar o alvo caído ou movê-lo até 3 metros em qualquer direção horizontalmente."],
      [10, 'Guarded Mind', 'Mente Protegida', "10th-level Psi Warrior feature\n\nThe psionic energy flowing through you has bolstered your mind. You have resistance to psychic damage. Moreover, if you start your turn charmed or frightened, you can expend a Psionic Energy die and end every effect on yourself subjecting you to those conditions.", "Característica de 10º nível do Guerreiro Psíquico\n\nA energia psiônica que flui através de você fortaleceu sua mente. Você tem resistência a dano psíquico. Além disso, se começar o seu turno enfeitiçado ou amedrontado, poderá gastar um Dado de Energia Psiônica e encerrar em si mesmo todos os efeitos que o estejam sujeitando a essas condições."],
      [15, 'Bulwark of Force', 'Baluarte de Força', "15th-level Psi Warrior feature\n\nYou can shield yourself and others with telekinetic force. As a bonus action, you can choose creatures, which can include you, that you can see within 30 feet of you, up to a number of creatures equal to your Intelligence modifier (minimum of one creature). Each of the chosen creatures is protected by half cover for 1 minute or until you’re incapacitated.\n\nOnce you take this bonus action, you can’t do so again until you finish a long rest, unless you spend a Psionic Energy die to take it again.", "Característica de 15º nível do Guerreiro Psíquico\n\nVocê pode proteger a si mesmo e a outros com força telecinética. Com uma ação bônus, você pode escolher criaturas, o que pode incluir você, que possa ver a até 9 metros de você, até um número de criaturas igual ao seu modificador de Inteligência (mínimo de uma criatura). Cada uma das criaturas escolhidas fica protegida por meia cobertura por 1 minuto ou até você ficar incapacitado.\n\nDepois de realizar esta ação bônus, você não poderá fazê-lo novamente até terminar um descanso longo, a menos que gaste um Dado de Energia Psiônica para usá-la de novo."],
      [18, 'Telekinetic Master', 'Mestre Telecinético', "18th-level Psi Warrior feature\n\nYour ability to move creatures and objects with your mind is matched by few. You can cast the telekinesis spell, requiring no components, and your spellcasting ability for the spell is Intelligence. On each of your turns while you concentrate on the spell, including the turn when you cast it, you can make one attack with a weapon as a bonus action.\n\nOnce you cast the spell with this feature, you can’t do so again until you finish a long rest, unless you expend a Psionic Energy die to cast it again.", "Característica de 18º nível do Guerreiro Psíquico\n\nSua capacidade de mover criaturas e objetos com a mente é igualada por poucos. Você pode conjurar a magia telecinese sem exigir componentes, e sua habilidade de conjuração para a magia é Inteligência. Em cada um dos seus turnos enquanto se concentrar na magia, incluindo o turno em que a conjurou, você pode realizar um ataque com arma como uma ação bônus.\n\nDepois de conjurar a magia com esta característica, você não poderá fazê-lo novamente até terminar um descanso longo, a menos que gaste um Dado de Energia Psiônica para conjurá-la de novo."],
    ],
    runeknight: [
      [3, 'Bonus Proficiencies', 'Proficiências Adicionais', "You gain proficiency with three skills of your choice.", "Você ganha proficiência em três perícias à sua escolha."],
      [3, 'Rune Carver', 'Entalhador de Runas', "3rd-level Rune Knight feature\n\nYou can use magic runes to enhance your gear. You learn two runes of your choice, from among the runes described below, and each time you gain a level in this class, you can replace one rune you know with a different one from this feature. When you reach certain levels in this class, you learn additional runes, as shown in the Runes Known table.\n\nRunes Known\n\n| Fighter Level | Number of Runes |\n\n| 3rd | 2 |\n\n| 7th | 3 |\n\n| 10th | 4 |\n\n| 15th | 5 |\n\nWhenever you finish a long rest, you can touch a number of objects equal to the number of runes you know, and you inscribe a different rune onto each of the objects. To be eligible, an object must be a weapon, suit of armor, a shield, a piece of jewelry, or something else you can wear or hold in a hand. Your rune remains on an object until you finish a long rest, and an object can bear only one of your runes at a time.\n\nThe following runes are available to you when you learn a rune. If a rune has a level requirement, you must be at least that level in this class to learn the rune. If a rune requires a saving throw, your Rune Magic save DC equals 8 + your proficiency bonus + your Constitution modifier.\n\nCloud Rune. This rune emulates the deceptive magic used by some cloud giants. While wearing or carrying an object inscribed with this rune, you have advantage on Dexterity (Sleight of Hand) checks and Charisma (Deception) checks.\n\nIn addition, when you or a creature you can see within 30 feet of you is hit by an attack roll, you can use your reaction to invoke the rune and choose a different creature within 30 feet of you, other than the attacker. The chosen creature becomes the target of the attack, using the same roll. This magic can transfer the attack’s effects regardless of the attack’s range. Once you invoke this rune, you can’t do so again until you finish a short or long rest.\n\nFire Rune. This rune’s magic channels the masterful craftsmanship of great smiths. While wearing or carrying an object inscribed with this rune, your proficiency bonus is doubled for any ability check you make that uses your proficiency with a tool.\n\nIn addition, when you hit a creature with an attack using a weapon, you can invoke the rune to summon fiery shackles: the target takes an extra 2d6 fire damage, and it must succeed on a Strength saving throw or be restrained for 1 minute. While restrained by the shackles, the target takes 2d6 fire damage at the start of each of its turns. The target can repeat the saving throw at the end of each of its turns, banishing the shackles on a success. Once you invoke this rune, you can’t do so again until you finish a short or long rest.\n\nFrost Rune. This rune’s magic evokes the might of those who survive in the wintry wilderness, such as frost giants. While wearing or carrying an object inscribed with this rune, you have advantage on Wisdom (Animal Handling) checks and Charisma (Intimidation) checks.\n\nIn addition, you can invoke the rune as a bonus action to increase your sturdiness. For 10 minutes, you gain a +2 bonus to all ability checks and saving throws that use Strength or Constitution. Once you invoke this rune, you can’t do so again until you finish a short or long rest.\n\nStone Rune. This rune’s magic channels the judiciousness associated with stone giants. While wearing or carrying an object inscribed with this rune, you have advantage on Wisdom (Insight) checks, and you have darkvision out to a range of 120 feet.\n\nIn addition, when a creature you can see ends its turn within 30 feet of you, you can use your reaction to invoke the rune and force the creature to make a Wisdom saving throw. Unless the save succeeds, the creature is charmed by you for 1 minute. While charmed in this way, the creature has a speed of 0 and is incapacitated, descending into a dreamy stupor. The creature repeats the saving throw at the end of each of its turns, ending the effect on a success. Once you invoke this rune, you can’t do so again until you finish a short or long rest.\n\nHill Rune (7th Level or Higher). This rune’s magic bestows a resilience reminiscent of a hill giant. While wearing or carrying an object that bears this rune, you have advantage on saving throws against being poisoned, and you have resistance against poison damage.\n\nIn addition, you can invoke the rune as a bonus action, gaining resistance to bludgeoning, piercing, and slashing damage for 1 minute. Once you invoke this rune, you can’t do so again until you finish a short or long rest.\n\nStorm Rune (7th Level or Higher). Using this rune, you can glimpse the future like a storm giant seer. While wearing or carrying an object inscribed with this rune, you have advantage on Intelligence (Arcana) checks, and you can’t be surprised as long as you aren’t incapacitated.\n\nIn addition, you can invoke the rune as a bonus action to enter a prophetic state for 1 minute or until you’re incapacitated. Until the state ends, when you or another creature you can see within 60 feet of you makes an attack roll, a saving throw, or an ability check, you can use your reaction to cause the roll to have advantage or disadvantage. Once you invoke this rune, you can’t do so again until you finish a short or long rest.", "Recurso de Cavaleiro Rúnico de 3º nível\n\nVocê pode usar runas mágicas para aprimorar seu equipamento. Você aprende duas runas à sua escolha dentre as descritas abaixo e, sempre que ganha um nível nesta classe, pode substituir uma runa conhecida por outra diferente deste recurso. Ao alcançar certos níveis nesta classe, você aprende runas adicionais, conforme mostrado na tabela Runas Conhecidas.\n\nRunas Conhecidas\n\nNível de Guerreiro | Número de Runas\n\n3º | 2\n\n7º | 3\n\n10º | 4\n\n15º | 5\n\nSempre que terminar um descanso longo, você pode tocar um número de objetos igual ao número de runas que conhece e inscrever uma runa diferente em cada um dos objetos. Para ser elegível, um objeto deve ser uma arma, uma armadura, um escudo, uma joia ou algo que você possa vestir ou segurar em uma mão. Sua runa permanece no objeto até você terminar um descanso longo, e um objeto pode portar apenas uma das suas runas por vez.\n\nAs runas a seguir ficam disponíveis quando você aprende uma runa. Se uma runa tiver pré-requisito de nível, você deve ter pelo menos esse nível nesta classe para aprendê-la. Se uma runa exigir uma salvaguarda, a CD de resistência da sua Magia Rúnica é igual a 8 + seu bônus de proficiência + seu modificador de Constituição.\n\nRuna da Nuvem. Esta runa emula a magia enganosa usada por alguns gigantes das nuvens. Enquanto estiver vestindo ou carregando um objeto inscrito com esta runa, você tem vantagem em testes de Destreza (Prestidigitação) e em testes de Carisma (Enganação).\n\nAlém disso, quando você ou uma criatura que você possa ver a até 9 m de você for atingida por uma jogada de ataque, você pode usar sua reação para invocar a runa e escolher outra criatura a até 9 m de você que não seja o atacante. A criatura escolhida torna-se o alvo do ataque, usando a mesma jogada. Essa magia pode transferir os efeitos do ataque independentemente do alcance do ataque. Depois de invocar esta runa, você não pode fazê-lo novamente até terminar um descanso curto ou longo.\n\nRuna do Fogo. A magia desta runa canaliza a maestria artesanal de grandes ferreiros. Enquanto estiver vestindo ou carregando um objeto inscrito com esta runa, seu bônus de proficiência é dobrado para qualquer teste de atributo que você fizer usando sua proficiência com uma ferramenta.\n\nAlém disso, quando você atingir uma criatura com um ataque usando uma arma, pode invocar a runa para conjurar grilhões flamejantes: o alvo sofre 2d6 de dano de fogo adicional e deve ser bem-sucedido em uma salvaguarda de Força ou ficará impedido por 1 minuto. Enquanto estiver impedido pelos grilhões, o alvo sofre 2d6 de dano de fogo no início de cada um dos turnos dele. O alvo pode repetir a salvaguarda no final de cada um dos turnos dele, banindo os grilhões em caso de sucesso. Depois de invocar esta runa, você não pode fazê-lo novamente até terminar um descanso curto ou longo.\n\nRuna da Geada. A magia desta runa evoca o poder daqueles que sobrevivem nas regiões ermas invernais, como os gigantes do gelo. Enquanto estiver vestindo ou carregando um objeto inscrito com esta runa, você tem vantagem em testes de Sabedoria (Lidar com Animais) e em testes de Carisma (Intimidação).\n\nAlém disso, você pode invocar a runa como uma ação bônus para aumentar sua robustez. Por 10 minutos, você recebe um bônus de +2 em todos os testes de atributo e salvaguardas que usem Força ou Constituição. Depois de invocar esta runa, você não pode fazê-lo novamente até terminar um descanso curto ou longo.\n\nRuna da Pedra. A magia desta runa canaliza a lucidez associada aos gigantes das pedras. Enquanto estiver vestindo ou carregando um objeto inscrito com esta runa, você tem vantagem em testes de Sabedoria (Intuição) e possui visão no escuro com alcance de 36 m.\n\nAlém disso, quando uma criatura que você possa ver terminar o turno dela a até 9 m de você, você pode usar sua reação para invocar a runa e forçar a criatura a fazer uma salvaguarda de Sabedoria. A menos que obtenha sucesso, a criatura fica enfeitiçada por você por 1 minuto. Enquanto estiver enfeitiçada dessa forma, a criatura tem deslocamento 0 e fica incapacitada, mergulhando em um estupor sonhador. A criatura repete a salvaguarda no final de cada um dos turnos dela, encerrando o efeito em caso de sucesso. Depois de invocar esta runa, você não pode fazê-lo novamente até terminar um descanso curto ou longo.\n\nRuna da Colina (7º Nível ou Superior). A magia desta runa confere uma resiliência que remete a um gigante das colinas. Enquanto estiver vestindo ou carregando um objeto que porte esta runa, você tem vantagem em salvaguardas contra ficar envenenado e tem resistência contra dano de veneno.\n\nAlém disso, você pode invocar a runa como uma ação bônus, ganhando resistência a dano contundente, perfurante e cortante por 1 minuto. Depois de invocar esta runa, você não pode fazê-lo novamente até terminar um descanso curto ou longo.\n\nRuna da Tempestade (7º Nível ou Superior). Usando esta runa, você pode vislumbrar o futuro como um vidente gigante das tempestades. Enquanto estiver vestindo ou carregando um objeto inscrito com esta runa, você tem vantagem em testes de Inteligência (Arcanismo) e não pode ser surpreendido enquanto não estiver incapacitado.\n\nAlém disso, você pode invocar a runa como uma ação bônus para entrar em um estado profético por 1 minuto ou até ficar incapacitado. Até o estado terminar, quando você ou outra criatura que você possa ver a até 18 m de você fizer uma jogada de ataque, uma salvaguarda ou um teste de atributo, você pode usar sua reação para fazer com que a jogada tenha vantagem ou desvantagem. Depois de invocar esta runa, você não pode fazê-lo novamente até terminar um descanso curto ou longo."],
      [3, 'Giant\'s Might', 'Poder do Gigante', "3rd-level Rune Knight feature\n\nYou have learned how to imbue yourself with the might of giants. As a bonus action, you magically gain the following benefits, which last for 1 minute:\n\n• If you are smaller than Large, you become Large, along with anything you are wearing. If you lack the room to become Large, your size doesn’t change.\n\n• You have advantage on Strength checks and Strength saving throws.\n\n• Once on each of your turns, one of your attacks with a weapon or an unarmed strike can deal an extra 1d6 damage to a target on a hit.\n\nYou can use this feature a number of times equal to your proficiency bonus, and you regain all expended uses of it when you finish a long rest.", "Característica de 3º nível do Cavaleiro Rúnico\n\nVocê aprendeu como imbuir a si mesmo com o poder dos gigantes. Como uma ação bônus, você ganha magicamente os seguintes benefícios, que duram por 1 minuto:\n\n• Se você for menor que Grande, você se torna Grande, junto com tudo o que estiver vestindo ou carregando. Se você não tiver espaço para se tornar Grande, seu tamanho não muda.\n\n• Você tem vantagem em testes de Força e salvaguardas de Força.\n\n• Uma vez em cada um dos seus turnos, um de seus ataques com uma arma ou um golpe desarmado pode causar 1d6 de dano adicional a um alvo ao acertar.\n\nVocê pode usar esta característica um número de vezes igual ao seu bônus de proficiência, e você recupera todos os usos gastos dela ao terminar um descanso longo."],
      [7, 'Runic Shield', 'Escudo Rúnico', "7th-level Rune Knight feature\n\nYou learn to invoke your rune magic to protect your allies. When another creature you can see within 60 feet of you is hit by an attack roll, you can use your reaction to force the attacker to reroll the d20 and use the new roll.\n\nYou can use this feature a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.", "Característica de 7º nível do Cavaleiro Rúnico\n\nVocê aprende a invocar sua magia rúnica para proteger seus aliados. Quando outra criatura que você possa ver a até 18 metros de você for atingida por uma jogada de ataque, você pode usar sua reação para forçar o atacante a rolar novamente o d20 e usar a nova rolagem.\n\nVocê pode usar esta característica um número de vezes igual ao seu bônus de proficiência, e você recupera todos os usos gastos ao terminar um descanso longo."],
      [10, 'Great Stature', 'Grande Estatura', "10th-level Rune Knight feature\n\nThe magic of your runes permanently alters you. When you gain this feature, roll 3d4. You grow a number of inches in height equal to the roll.\n\nMoreover, the extra damage you deal with your Giant’s Might feature increases to 1d8.", "Característica de 10º nível do Cavaleiro Rúnico\n\nA magia das suas runas altera você permanentemente. Quando obtiver esta característica, role 3d4. Sua altura aumenta em um número de centímetros igual ao resultado multiplicado por 2,5 (número de polegadas igual à rolagem).\n\nAlém disso, o dano adicional que você causa com sua característica Poder dos Gigantes aumenta para 1d8."],
      [15, 'Master of Runes', 'Mestre das Runas', "15th-level Rune Knight feature\n\nYou can invoke each rune you know from your Rune Carver feature twice, rather than once, and you regain all expended uses when you finish a short or long rest.", "Característica de 15º nível do Cavaleiro Rúnico\n\nVocê pode invocar cada runa que conhece da sua característica Escultor de Runas duas vezes, em vez de uma, e você recupera todos os usos gastos ao terminar um descanso curto ou longo."],
      [18, 'Runic Juggernaut', 'Colosso Rúnico', "18th-level Rune Knight feature\n\nYou learn to amplify your rune-powered transformation. As a result, the extra damage you deal with the Giant’s Might feature increases to 1d10. Moreover, when you use that feature, your size can increase to Huge, and while you are that size, your reach increases by 5 feet.", "Característica de 18º nível do Cavaleiro Rúnico\n\nVocê aprende a ampliar sua transformação alimentada por runas. Como resultado, o dano adicional que você causa com a característica Poder dos Gigantes aumenta para 1d10. Além disso, quando você usa essa característica, seu tamanho pode aumentar para Enorme e, enquanto estiver desse tamanho, seu alcance aumenta em 1,5 metro."],
    ],
  },
  monk: {
    longdeath: [
      [3, 'Touch of Death', 'Toque da Morte', "Starting when you choose this tradition at 3rd level, your study of death allows you to extract vitality from a nother creature as it nears its demise. When you reduce a creature within 5 feet of you to 0 hit points, you gain temporary hit points equal to your Wisdom modifier + your monk level (minimum of 1 temporary hit point).", "A partir do momento em que escolhe esta tradição no 3º nível, seu estudo da morte permite que você extraia vitalidade de outra criatura quando ela se aproxima do seu fim. Quando você reduz uma criatura a 1,5 metro de você a 0 pontos de vida, você ganha pontos de vida temporários iguais ao seu modificador de Sabedoria + seu nível de monge (mínimo de 1 ponto de vida temporário)."],
      [6, 'Hour of Reaping', 'Hora da Colheita', "At 6th level, you gain the ability to unsettle or terrify those around you as an action, for your soul has been touched by the shadow of death. When you take this action, each creature within 30 feet of you that can see you must succeed on a Wisdom saving throw or be frightened of you until the end of your next turn.", "No 6º nível, você ganha a capacidade de perturbar ou aterrorizar aqueles ao seu redor como uma ação, pois sua alma foi tocada pela sombra da morte. Ao realizar essa ação, cada criatura a até 9 metros de você que puder vê-lo deve ser bem-sucedida em uma salvaguarda de Sabedoria ou ficará amedrontada por você até o fim do seu próximo turno."],
      [11, 'Mastery of Death', 'Maestria da Morte', "Beginning at 11th level, you use your familiarity with death to escape its grasp. When you are reduced to 0 hit points, you can expend 1 ki point (no action required) to have 1 hit point instead.", "A partir do 11º nível, você usa sua familiaridade com a morte para escapar do seu aperto. Quando você é reduzido a 0 pontos de vida, pode gastar 1 ponto de ki (nenhuma ação necessária) para, em vez disso, ficar com 1 ponto de vida."],
      [17, 'Touch of the Long Death', 'Toque da Longa Morte', "Starting at 17th level, your touch can channel the energy of death into a creature. As an action, you touch one creature within 5 feet of you, and you expend 1 to 10 ki points. The target must make a Constitution saving throw, and it takes 2d10 necrotic damage per ki point spent on a failed save, or half as much damage on a successful one.", "A partir do 17º nível, seu toque pode canalizar a energia da morte para uma criatura. Como uma ação, você toca uma criatura a até 1,5 metro de você e gasta de 1 a 10 pontos de ki. O alvo deve fazer uma salvaguarda de Constituição e sofre 2d10 de dano necrótico por ponto de ki gasto se falhar na salvaguarda, ou metade desse dano se obtiver sucesso."],
    ],
    sunsoul: [
      [3, 'Radiant Sun Bolt', 'Raio Solar Radiante', "Starting when you choose this tradition at 3rd level, you can hurl searing bolts of magical radiance.\n\nYou gain a new attack option that you can use with the Attack action. This special attack is a ranged spell attack with a range of 30 feet. You are proficient with it, and you add your Dexterity modifier to its attack and damage rolls. Its damage is radiant, and its damage die is a d4. This die changes as you gain monk levels, as shown in the Martial Arts column of the Monk table.\n\nWhen you take the Attack action on your turn and use this special attack as part of it, you can spend 1 ki point to make the special attack twice as a bonus action.\n\nWhen you gain the Extra Attack feature, this special attack can be used for any of the attacks you make as part of the Attack action.", "A partir do momento em que você escolhe esta tradição no 3º nível, você pode arremessar raios abrasadores de radiância mágica.\n\nVocê ganha uma nova opção de ataque que pode usar com a ação de Ataque. Este ataque especial é um ataque à distância com magia com alcance de 9 m. Você é proficiente com ele e adiciona seu modificador de Destreza às jogadas de ataque e de dano. Seu dano é radiante e seu dado de dano é 1d4. Esse dado muda conforme você ganha níveis de monge, como mostrado na coluna Artes Marciais da tabela do Monge.\n\nQuando você realiza a ação de Ataque no seu turno e usa este ataque especial como parte dela, pode gastar 1 ponto de ki para realizar o ataque especial duas vezes como uma ação bônus.\n\nQuando você ganha o recurso Ataque Extra, este ataque especial pode ser usado para qualquer um dos ataques realizados como parte da ação de Ataque."],
      [6, 'Searing Arc Strike', 'Golpe do Arco Ardente', "At 6th level, you gain the ability to channel your ki into searing waves of energy. Immediately after you take the Attack action on your turn, you can spend 2 ki points to cast the 1st-level spell burning hands as a bonus action.\n\nYou can spend additional ki points to cast burning hands as a higher level spell. Each additional ki point you spend increases the spell's level by 1. The maximum number of ki points (2 plus any additional points) that you can spend on the spell equals half your monk level (round down).", "No 6º nível, você ganha a capacidade de canalizar seu ki em ondas abrasadoras de energia. Imediatamente após realizar a ação de Ataque em seu turno, você pode gastar 2 pontos de ki para conjurar a magia de 1º círculo mãos flamejantes como uma ação bônus.\n\nVocê pode gastar pontos de ki adicionais para conjurar mãos flamejantes como uma magia de círculo superior. Cada ponto de ki adicional que você gasta aumenta o círculo da magia em 1. O número máximo de pontos de ki (2 mais quaisquer pontos adicionais) que você pode gastar na magia é igual à metade do seu nível de monge (arredondado para baixo)."],
      [11, 'Searing Sunburst', 'Explosão Solar Ardente', "At 11th level, you gain the ability to create an orb of light that erupts into a devastating explosion. As an action, you magically create an orb and hurl it at a point you choose within 150 feet, where it erupts into a sphere of radiant light for a brief but deadly instant.\n\nEach creature in that 20-foot-radius sphere must succeed on a Constitution saving throw or take 2d6 radiant damage. A creature doesn't need to make the save if the creature is behind total cover that is opaque.\n\nYou can increase the sphere's damage by spending ki points. Each point you spend, up to a maximum of 3, increases the damage by 2d6.", "No 11º nível, você ganha a habilidade de criar um orbe de luz que irrompe em uma explosão devastadora. Como uma ação, você cria magicamente um orbe e o arremessa em um ponto à sua escolha a até 45 m, onde ele irrompe em uma esfera de luz radiante por um instante breve, porém mortal.\n\nCada criatura nessa esfera de 6 m de raio deve ser bem-sucedida em uma salvaguarda de Constituição ou sofrerá 2d6 de dano radiante. Uma criatura não precisa fazer a salvaguarda se estiver atrás de cobertura total opaca.\n\nVocê pode aumentar o dano da esfera gastando pontos de ki. Cada ponto gasto, até o máximo de 3, aumenta o dano em 2d6."],
      [17, 'Sun Shield', 'Escudo Solar', "At 17th level, you become wreathed in a magical, luminous aura. You shed bright light in a 30-foot radius and dim light for an additional 30 feet. You can extinguish or restore the light as a bonus action.\n\nIf a creature hits you with a melee attack while this light shines, you can use your reaction to deal radiant damage to the creature. The radiant damage equals 5 + your Wisdom modifier.", "No 17º nível, você fica envolto por uma aura luminosa mágica. Você emite luz plena em um raio de 9 m e penumbra por mais 9 m adicionais. Você pode extinguir ou restaurar a luz como uma ação bônus.\n\nSe uma criatura atingir você com um ataque corpo a corpo enquanto essa luz brilhar, você pode usar sua reação para causar dano radiante à criatura. O dano radiante é igual a 5 + seu modificador de Sabedoria."],
    ],
    drunkenmaster: [
      [3, 'Bonus Proficiencies', 'Proficiências Adicionais', "You gain proficiency with three skills of your choice.", "Você ganha proficiência em três perícias à sua escolha."],
      [3, 'Drunken Technique', 'Técnica Embriagada', "At 3rd level, you learn how to twist and turn quickly as part of your Flurry of Blows. Whenever you use Flurry of Blows, you gain the benefit of the Disengage action, and your walking speed increases by 10 feet until the end of the current turn.", "No 3º nível, você aprende a girar e se esquivar rapidamente como parte de sua Rajada de Golpes. Sempre que você usa Rajada de Golpes, recebe o benefício da ação de Desengajar, e seu deslocamento de caminhada aumenta em 3 metros até o final do turno atual."],
      [6, 'Tipsy Sway', 'Balanço Ébrio', "Starting at 6th level, you can move in sudden, swaying ways. You gain the following benefits.\n\nLeap to Your Feet. When you’re prone, you can stand up by spending 5 feet of movement, rather than half your speed.\n\nRedirect Attack. When a creature misses you with a melee attack roll, you can spend 1 ki point as a reaction to cause that attack to hit one creature of your choice, other than the attacker, that you can see within 5 feet of you.", "A partir do 6º nível, você pode se mover de maneiras súbitas e oscilantes. Você ganha os seguintes benefícios.\n\nPular para Ficar de Pé. Quando estiver caído, você pode se levantar gastando 1,5 m de deslocamento, em vez da metade do seu deslocamento.\n\nRedirecionar Ataque. Quando uma criatura errar você com uma jogada de ataque corpo a corpo, você pode gastar 1 ponto de ki como uma reação para fazer com que esse ataque atinja uma criatura à sua escolha, diferente do atacante, que você possa ver a até 1,5 m de você."],
      [11, 'Drunkard\'s Luck', 'Sorte do Bêbado', "Starting at 11th level, you always seem to get a lucky bounce at the right moment. When you make an ability check, an attack roll, or a saving throw and have disadvantage on the roll, you can spend 2 ki points to cancel the disadvantage for that roll.", "A partir do 11º nível, você sempre parece dar uma guinada de sorte no momento certo. Quando fizer um teste de atributo, uma jogada de ataque ou uma salvaguarda e tiver desvantagem na jogada, você pode gastar 2 pontos de ki para cancelar a desvantagem daquela jogada."],
      [17, 'Intoxicated Frenzy', 'Frenesi Embriagado', "At 17th level, you gain the ability to make an overwhelming number of attacks against a group of enemies. When you use your Flurry of Blows, you can make up to three additional attacks with it (up to a total of five Flurry of Blows attacks), provided that each Flurry of Blows attack targets a different creature this turn.", "No 17º nível, você ganha a capacidade de realizar uma quantidade avassaladora de ataques contra um grupo de inimigos. Quando você usa sua Rajada de Golpes, pode fazer até três ataques adicionais com ela (até um total de cinco ataques de Rajada de Golpes), desde que cada ataque da Rajada de Golpes tenha como alvo uma criatura diferente neste turno."],
    ],
    kensei: [
      [3, 'Path of the Kensei', 'Caminho do Kensei', "When you choose this tradition at 3rd level, your special martial arts training leads you to master the use of certain weapons. This path also includes instruction in the deft strokes of calligraphy or painting. You gain the following benefits.\n\nKensei Weapons. Choose two types of weapons to be your kensei weapons: one melee weapon and one ranged weapon. Each of these weapons can be any simple or martial weapon that lacks the heavy and special properties. The longbow is also a valid choice. You gain proficiency with these weapons if you don’t already have it. Weapons of the chosen types are monk weapons for you. Many of this tradition’s features work only with your kensei weapons. When you reach 6th, 11th, and 17th level in this class, you can choose another type of weapon—either melee or ranged—to be a kensei weapon for you following the criteria above.\n\nAgile Parry. If you make an unarmed strike as part of the Attack action on your turn and are holding a kensei weapon, you can use it to defend yourself if it is a melee weapon. You gain a +2 bonus to AC until the start of your next turn, while the weapon is in your hand and you aren't incapacitated.\n\nKensei’s Shot. You can use a bonus action on your turn to make your ranged attacks with a kensei weapon more deadly. When you do so, any target you hit with a ranged attack using a kensei weapon takes an extra 1d4 damage of the weapons type. You retain this benefit until the end of the current turn.\n\nWay of the Brush. You gain proficiency with your choice of calligrapher's supplies or painter's supplies.", "Quando você escolhe esta tradição no 3º nível, seu treinamento especial nas artes marciais leva você a dominar o uso de certas armas. Este caminho também inclui instrução nos traços precisos da caligrafia ou da pintura. Você ganha os seguintes benefícios.\n\nArmas de Kensei. Escolha dois tipos de armas para serem suas armas de kensei: uma arma corpo a corpo e uma arma à distância. Cada uma dessas armas pode ser qualquer arma simples ou marcial que não possua as propriedades pesada e especial. O arco longo também é uma escolha válida. Você ganha proficiência com essas armas caso ainda não a tenha. Armas dos tipos escolhidos são armas de monge para você. Muitos dos recursos desta tradição funcionam apenas com suas armas de kensei. Quando você alcança o 6º, 11º e 17º nível nesta classe, pode escolher outro tipo de arma — corpo a corpo ou à distância — para ser uma arma de kensei para você seguindo os critérios acima.\n\nAparo Ágil. Se você fizer um ataque desarmado como parte da ação de Ataque no seu turno e estiver segurando uma arma de kensei, pode usá-la para se defender se ela for uma arma corpo a corpo. Você ganha um bônus de +2 na CA até o início do seu próximo turno, enquanto a arma estiver em sua mão e você não estiver incapacitado.\n\nDisparo de Kensei. Você pode usar uma ação bônus no seu turno para tornar seus ataques à distância com uma arma de kensei mais mortais. Quando faz isso, qualquer alvo que você atingir com um ataque à distância usando uma arma de kensei sofre 1d4 de dano adicional do tipo da arma. Você mantém esse benefício até o final do turno atual.\n\nCaminho do Pincel. Você ganha proficiência com suprimentos de caligrafia ou suprimentos de pintura, à sua escolha."],
      [6, 'One with the Blade', 'Um com a Lâmina', "At 6th level, you extend your ki into your kensei weapons, granting you the following benefits.\n\nMagic Kensei Weapons. Your attacks with your kensei weapons count as magical for the purpose of overcoming resistance and immunity to nonmagical attacks and damage.\n\nDeft Strike. When you hit a target with a kensei weapon, you can spend 1 ki point to cause the weapon to deal extra damage to the target equal to your Martial Arts die. You can use this feature only once on each of your turns.", "No 6º nível, você estende seu ki para suas armas de kensei, concedendo os seguintes benefícios.\n\nArmas de Kensei Mágicas. Seus ataques com suas armas de kensei contam como mágicos para o propósito de superar resistência e imunidade a ataques e danos não mágicos.\n\nGolpe Preciso. Quando você atingir um alvo com uma arma de kensei, pode gastar 1 ponto de ki para fazer a arma causar dano adicional ao alvo igual ao seu dado de Artes Marciais. Você pode usar este recurso apenas uma vez em cada um dos seus turnos."],
      [11, 'Sharpen the Blade', 'Afiar a Lâmina', "At 11th level, you gain the ability to augment your weapons further with your ki. As a bonus action, you can expend up to 3 ki points to grant one kensei weapon you touch a bonus to attack and damage rolls when you attack with it. The bonus equals the number of ki points you spent. This bonus lasts for 1 minute or until you use this feature again. This feature has no effect on a magic weapon that already has a bonus to attack and damage rolls.", "No 11º nível, você ganha a habilidade de aprimorar ainda mais suas armas com seu ki. Como uma ação bônus, você pode gastar até 3 pontos de ki para conceder a uma arma de kensei que você tocar um bônus nas jogadas de ataque e de dano quando atacar com ela. O bônus é igual ao número de pontos de ki gastos. Esse bônus dura 1 minuto ou até você usar este recurso novamente. Este recurso não tem efeito em uma arma mágica que já possua um bônus nas jogadas de ataque e de dano."],
      [17, 'Unerring Accuracy', 'Precisão Infalível', "At 17th level, your mastery of weapons grants you extraordinary accuracy. If you miss with an attack roll using a monk weapon on your turn, you can reroll it. You can use this feature only once on each of your turns.", "No 17º nível, seu domínio das armas concede a você uma precisão extraordinária. Se errar uma jogada de ataque usando uma arma de monge em seu turno, você pode rolá-la novamente. Você pode usar esta característica apenas uma vez em cada um de seus turnos."],
    ],
    astralself: [
      [3, 'Arms of the Astral Self', 'Braços do Eu Astral', "3rd-level Way of the Astral Self feature\n\nYour mastery of your ki allows you to summon a portion of your astral self. As a bonus action, you can spend 1 ki point to summon the arms of your astral self. When you do so, each creature of your choice that you can see within 10 feet of you must succeed on a Dexterity saving throw or take force damage equal to two rolls of your Martial Arts die.\n\nFor 10 minutes, these spectral arms hover near your shoulders or surround your arms (your choice). You determine the arms’ appearance, and they vanish early if you are incapacitated or die.\n\nWhile the spectral arms are present, you gain the following benefits:\n\n• You can use your Wisdom modifier in place of your Strength modifier when making Strength checks and Strength saving throws.\n\n• You can use the spectral arms to make unarmed strikes.\n\n• When you make an unarmed strike with the arms on your turn, your reach for it is 5 feet greater than normal.\n\n• The unarmed strikes you make with the arms can use your Wisdom modifier in place of your Strength or Dexterity modifier for the attack and damage rolls, and their damage type is force.", "Recurso de Caminho do Eu Astral de 3º nível\n\nSeu domínio do ki permite invocar uma porção do seu eu astral. Como uma ação bônus, você pode gastar 1 ponto de ki para invocar os braços do seu eu astral. Ao fazê-lo, cada criatura à sua escolha que você possa ver a até 3 m de você deve ser bem-sucedida em uma salvaguarda de Destreza ou sofrerá dano de força igual a duas rolagens do seu dado de Artes Marciais.\n\nPor 10 minutos, esses braços espectrais pairam perto dos seus ombros ou envolvem seus braços (à sua escolha). Você determina a aparência dos braços, e eles desaparecem prematuramente se você ficar incapacitado ou morrer.\n\nEnquanto os braços espectrais estiverem presentes, você ganha os seguintes benefícios:\n\n• Você pode usar seu modificador de Sabedoria no lugar do modificador de Força ao fazer testes de Força e salvaguardas de Força.\n\n• Você pode usar os braços espectrais para realizar ataques desarmados.\n\n• Quando fizer um ataque desarmado com os braços no seu turno, seu alcance para ele é 1,5 m maior que o normal.\n\n• Os ataques desarmados que você faz com os braços podem usar seu modificador de Sabedoria no lugar do modificador de Força ou Destreza para as jogadas de ataque e de dano, e o tipo de dano deles é força."],
      [6, 'Visage of the Astral Self', 'Semblante do Eu Astral', "6th-level Way of the Astral Self feature\n\nYou can summon the visage of your astral self. As a bonus action, or as a part of the bonus action you take to activate Arms of the Astral Self, you can spend 1 ki point to summon this visage for 10 minutes. It vanishes early if you are incapacitated or die.\n\nThe spectral visage covers your face like a helmet or mask. You determine its appearance.\n\nWhile the spectral visage is present, you gain the following benefits:\n\nAstral Sight. You can see normally in darkness, both magical and nonmagical, to a distance of 120 feet.\n\nWisdom of the Spirit. You have advantage on Wisdom (Insight) and Charisma (Intimidation) checks.\n\nWord of the Spirit. When you speak, you can direct your words to a creature of your choice that you can see within 60 feet of you, making it so only the creature can hear you. Alternatively, you can amplify your voice so that all creatures within 600 feet can hear you.", "Recurso de Caminho do Eu Astral de 6º nível\n\nVocê pode invocar o semblante do seu eu astral. Como uma ação bônus, ou como parte da ação bônus que você realiza para ativar os Braços do Eu Astral, você pode gastar 1 ponto de ki para invocar esse semblante por 10 minutos. Ele desaparece prematuramente se você ficar incapacitado ou morrer.\n\nO semblante espectral cobre seu rosto como um elmo ou uma máscara. Você determina sua aparência.\n\nEnquanto o semblante espectral estiver presente, você ganha os seguintes benefícios:\n\nVisão Astral. Você pode enxergar normalmente na escuridão, tanto mágica quanto não mágica, a uma distância de 36 m.\n\nSabedoria do Espírito. Você tem vantagem em testes de Sabedoria (Intuição) e Carisma (Intimidação).\n\nPalavra do Espírito. Quando você fala, pode direcionar suas palavras a uma criatura à sua escolha que você possa ver a até 18 m de você, fazendo com que apenas ela possa ouvi-lo. Alternativamente, você pode amplificar sua voz para que todas as criaturas a até 180 m possam ouvi-lo."],
      [11, 'Body of the Astral Self', 'Corpo do Eu Astral', "11th-level Way of the Astral Self feature\n\nWhen you have both your astral arms and visage summoned, you can cause the body of your astral self to appear (no action required). This spectral body covers your physical form like a suit of armor, connecting with the arms and visage. You determine its appearance.\n\nWhile the spectral body is present, you gain the following benefits:\n\nDeflect Energy. When you take acid, cold, fire, force, lightning, or thunder damage, you can use your reaction to deflect it. When you do so, the damage you take is reduced by 1d10 + your Wisdom modifier (minimum reduction of 1).\n\nEmpowered Arms. Once on each of your turns when you hit a target with the Arms of the Astral Self, you can deal extra damage to the target equal to your Martial Arts die.", "Recurso de Caminho do Eu Astral de 11º nível\n\nQuando você tiver tanto os braços quanto o semblante astrais invocados, pode fazer o corpo do seu eu astral aparecer (sem gastar ação). Este corpo espectral cobre sua forma física como uma armadura, conectando-se aos braços e ao semblante. Você determina sua aparência.\n\nEnquanto o corpo espectral estiver presente, você ganha os seguintes benefícios:\n\nDesviar Energia. Quando você sofre dano ácido, de frio, fogo, força, elétrico ou trovejante, pode usar sua reação para desviá-lo. Quando faz isso, o dano que você sofre é reduzido em 1d10 + seu modificador de Sabedoria (redução mínima de 1).\n\nBraços Poderosos. Uma vez em cada um dos seus turnos, quando você atingir um alvo com os Braços do Eu Astral, você pode causar dano adicional ao alvo igual ao seu dado de Artes Marciais."],
      [17, 'Awakened Astral Self', 'Eu Astral Desperto', "17th-level Way of the Astral Self feature\n\nYour connection to your astral self is complete, allowing you to unleash its full potential. As a bonus action, you can spend 5 ki points to summon the arms, visage, adn body of your astral self and awaken it for 10 minutes. This awakening ends early if you are incapacitated or die.\n\nWhile your astral self is awakened, you gain the following benefits:\n\nArmor of the Spirit. You gain a +2 bonus to Armor Class.\n\nAstral Barrage. Whenever you use the Extra Attack feature to attack twice, you can instead attack three times if all the attacks are made with your astral arms.", "Característica de 17º nível do Caminho do Eu Astral\n\nSua conexão com seu eu astral está completa, permitindo que você libere todo o potencial dele. Como uma ação bônus, você pode gastar 5 pontos de ki para invocar os braços, semblante e corpo do seu eu astral e despertá-lo por 10 minutos. Este despertar termina mais cedo se você ficar incapacitado ou morrer.\n\nEnquanto seu eu astral estiver desperto, você recebe os seguintes benefícios:\n\nArmadura do Espírito. Você ganha um bônus de +2 na Classe de Armadura.\n\nBarragem Astral. Sempre que você usar a característica Ataque Extra para atacar duas vezes, pode, em vez disso, atacar três vezes se todos os ataques forem feitos com seus braços astrais."],
    ],
    mercy: [
      [3, 'Implements of Mercy', 'Instrumentos da Misericórdia', "3rd-level Way of Mercy feature\n\nYou gain proficiency in the Insight and Medicine skills, and you gain proficiency with the herbalism kit.\n\nYou also gain a special mask, which you often wear when using the feature of this subclass. You determine its appearance, or generate it randomly by rolling on the Merciful Mask table.\n\nMerciful Mask\n\n| d6 | Mask Appearance |\n\n| 1 | Raven |\n\n| 2 | Blank and white |\n\n| 3 | Crying visage |\n\n| 4 | Laughing visage |\n\n| 5 | Skull |\n\n| 6 | Butterfly |", "Característica de 3º nível do Caminho da Misericórdia\n\nVocê ganha proficiência nas perícias Intuição e Medicina, e ganha proficiência com o kit de herborismo.\n\nVocê também recebe uma máscara especial, a qual costuma usar ao utilizar as características desta subclasse. Você determina a aparência dela ou a gera aleatoriamente rolando na tabela Máscara Misericordiosa.\n\nMáscara Misericordiosa\n\n| d6 | Aparência da Máscara |\n\n| 1 | Corvo |\n\n| 2 | Branca e lisa |\n\n| 3 | Rosto chorando |\n\n| 4 | Rosto sorrindo |\n\n| 5 | Crânio |\n\n| 6 | Borboleta |"],
      [3, 'Hand of Healing', 'Mão da Cura', "3rd-level Way of Mercy feature\n\nYour mystical touch can mend wounds. As an action you can spend 1 ki point to touch a creature and restore a number of hit points equal to a roll of your Martial Arts die + your Wisdom modifier.\n\nWhen you use your Flurry of Blows, you can replace one of the unarmed strikes with a use of this feature without spending a ki point for the healing.", "Recurso de Caminho da Misericórdia de 3º nível\n\nSeu toque místico pode curar ferimentos. Como uma ação, você pode gastar 1 ponto de ki para tocar uma criatura e restaurar uma quantidade de Pontos de Vida igual a uma rolagem do seu dado de Artes Marciais + seu modificador de Sabedoria.\n\nQuando você usar sua Rajada de Golpes, pode substituir um dos ataques desarmados por um uso deste recurso sem gastar um ponto de ki pela cura."],
      [3, 'Hand of Harm', 'Mão do Dano', "3rd-level Way of Mercy feature\n\nYou use your ki to inflict wounds. When you hit a creature with an unarmed strike, you can spend 1 ki point to deal extra necrotic damage equal to one roll of your Martial Arts die + your Wisdom modifier. You can use this feature only once per turn.", "Recurso de Caminho da Misericórdia de 3º nível\n\nVocê usa seu ki para infligir ferimentos. Quando atingir uma criatura com um ataque desarmado, você pode gastar 1 ponto de ki para causar dano necrótico adicional igual a uma rolagem do seu dado de Artes Marciais + seu modificador de Sabedoria. Você pode usar este recurso apenas uma vez por turno."],
      [6, 'Physician\'s Touch', 'Toque do Médico', "6th-level Way of Mercy feature\n\nYou can administer even greater cures with a touch, and if you feel it’s necessary, you can use your knowledge to cause harm.\n\nWhen you use Hand of Healing on a creature, you can also end one disease or one of the following conditions affecting the creature: blinded, deafened, paralyzed, poisoned, or stunned.\n\nWhen you use Hand of Harm on a creature, you can subject that creature to the poisoned condition until the end of your next turn.", "Característica de 6º nível do Caminho da Misericórdia\n\nVocê pode ministrar curas ainda maiores com um toque e, se achar necessário, pode usar seu conhecimento para causar dano.\n\nQuando você usa Mãos da Cura em uma criatura, também pode encerrar uma doença ou uma das seguintes condições que afetam a criatura: atordoado, cego, envenenado, paralisado ou surdo.\n\nQuando você usa Mãos do Dano em uma criatura, pode sujeitar essa criatura à condição envenenado até o final do seu próximo turno."],
      [11, 'Flurry of Healing and Harm', 'Rajada de Cura e Dano', "11th-level Way of Mercy feature\n\nYou can now mete out a flurry of comfort and hurt. When you use Flurry of Blows, you can now replace each of the unarmed strikes with a use of your Hand of Healing without spending ki points for the healing.\n\nIn addition, when you make an unarmed strike with Flurry of Blows, you can use Hand of Harm with that strike without spending the ki point for Hand of Harm. You can still use Hand of Harm only once per turn.", "Recurso de Caminho da Misericórdia de 11º nível\n\nAgora você pode desferir uma rajada de alívio e dor. Quando você usar Rajada de Golpes, agora pode substituir cada um dos ataques desarmados por um uso de sua Mão Curativa sem gastar pontos de ki pela cura.\n\nAlém disso, quando você fizer um ataque desarmado com Rajada de Golpes, pode usar Mão Nociva com esse ataque sem gastar o ponto de ki para Mão Nociva. Você ainda pode usar Mão Nociva apenas uma vez por turno."],
      [17, 'Hand of Ultimate Mercy', 'Mão da Misericórdia Final', "17th-level Way of Mercy feature\n\nYour mastery of life energy opens the door to the ultimate mercy. As an action, you can touch the corpse of a creature that died within the past 24 hours and expend 5 ki points. The creature then returns to life, regaining a number of hit points equal to 4d10 + you Wisdom modifier. If the creature died while subject to any of the following conditions, it revives with them removed: blinded, deafened, paralyzed, poisoned, and stunned.\n\nOnce you use this feature, you can’t use it again until you finish a long rest.", "Recurso de Caminho da Misericórdia de 17º nível\n\nSeu domínio da energia vital abre a porta para a misericórdia suprema. Como uma ação, você pode tocar o cadáver de uma criatura que tenha morrido nas últimas 24 horas e gastar 5 pontos de ki. A criatura então retorna à vida, recuperando uma quantidade de Pontos de Vida igual a 4d10 + seu modificador de Sabedoria. Se a criatura morreu enquanto estava sujeita a qualquer uma das seguintes condições, ela revive com essas condições removidas: cega, surda, paralisada, envenenada e atordoada.\n\nDepois de usar este recurso, você não pode usá-lo novamente até terminar um descanso longo."],
    ],
    ascendantdragon: [
      [3, 'Draconic Disciple', 'Discípulo Dracônico', "3rd-Level Way of the Ascendant Dragon Feature\n\nYou can channel draconic power to magnify your presence and imbue your unarmed strikes with the essence of a dragon’s breath. You gain the following benefits:\n\nDraconic Presence. If you fail a Charisma (Intimidation) or Charisma (Persuasion) check, you can use your reaction to reroll the check, as you tap into the mighty presence of dragons. Once this feature turns a failure into a success, you can’t use it again until you finish a long rest.\n\nDraconic Strike. When you damage a target with an unarmed strike, you can change the damage type to acid, cold, fire, lightning, or poison.\n\nTongue of Dragons. You learn to speak, read, and write Draconic or one other language of your choice.", "Recurso de Caminho do Dragão Ascendente de 3º Nível\n\nVocê pode canalizar poder dracônico para magnificar sua presença e imbuir seus ataques desarmados com a essência do sopro de um dragão. Você ganha os seguintes benefícios:\n\nPresença Dracônica. Se você falhar em um teste de Carisma (Intimidação) ou Carisma (Persuasão), pode usar sua reação para rolar o teste novamente, recorrendo à presença imponente dos dragões. Depois que este recurso transformar uma falha em sucesso, você não pode usá-lo novamente até terminar um descanso longo.\n\nGolpe Dracônico. Quando você causar dano a um alvo com um ataque desarmado, pode mudar o tipo de dano para ácido, frio, fogo, elétrico ou veneno.\n\nLíngua dos Dragões. Você aprende a falar, ler e escrever Dracônico ou outro idioma à sua escolha."],
      [3, 'Breath of the Dragon', 'Sopro do Dragão', "3rd-Level Way of the Ascendant Dragon Feature\n\nYou can channel destructive waves of energy, like those created by the dragons you emulate. When you take the Attack action on your turn, you can replace one of the attacks with an exhalation of draconic energy in either a 20-foot cone or a 30-foot line that is 5 feet wide (your choice). Choose a damage type: acid, cold, fire, lightning, or poison. Each creature in that area must make a Dexterity saving throw against your ki save DC, taking damage of the chosen type equal to two rolls of your Martial Arts die on a failed save, or half as much damage on a successful one.\n\nAt 11th level, the damage of this feature increases to three rolls of your Martial Arts die.\n\nYou can use this feature a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest. While you have no uses available, you can spend 2 ki points to use this feature again.", "Recurso de Caminho do Dragão Ascendente de 3º Nível\n\nVocê pode canalizar ondas destrutivas de energia, como as criadas pelos dragões que você emula. Quando você realizar a ação de Ataque no seu turno, pode substituir um dos ataques por uma exalação de energia dracônica em um cone de 6 m ou em uma linha de 9 m com 1,5 m de largura (à sua escolha). Escolha um tipo de dano: ácido, frio, fogo, elétrico ou veneno. Cada criatura nessa área deve fazer uma salvaguarda de Destreza contra a CD de resistência do seu ki, sofrendo dano do tipo escolhido igual a duas rolagens do seu dado de Artes Marciais se falhar, ou metade desse dano se obtiver sucesso.\n\nNo 11º nível, o dano deste recurso aumenta para três rolagens do seu dado de Artes Marciais.\n\nVocê pode usar este recurso um número de vezes igual ao seu bônus de proficiência e recupera todos os usos gastos quando termina um descanso longo. Enquanto não tiver usos disponíveis, você pode gastar 2 pontos de ki para usar este recurso novamente."],
      [6, 'Wings Unfurled', 'Asas Abertas', "6th-Level Way of the Ascendant Dragon Feature\n\nWhen you use your Step of the Wind, you can unfurl spectral draconic wings from your back that vanish at the end of your turn. While the wings exist, you have a flying speed equal to your walking speed.\n\nYou can use this feature a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.", "Característica de 6º Nível do Caminho do Dragão Ascendente\n\nQuando você usa seu Passo do Vento, pode desdobrar asas dracônicas espectrais de suas costas que desaparecem no final do seu turno. Enquanto as asas existirem, você tem um deslocamento de voo igual ao seu deslocamento de caminhada.\n\nVocê pode usar esta característica um número de vezes igual ao seu bônus de proficiência e recupera todos os usos gastos ao terminar um descanso longo."],
      [11, 'Aspect of the Wyrm', 'Aspecto da Serpe', "11th-Level Way of the Ascendant Dragon Feature\n\nThe power of your draconic spirit now radiates from you, warding your allies or inspiring fear in your enemies. As a bonus action, you can create an aura of draconic power that radiates 10 feet from you for 1 minute. For the duration, you gain one of the following effects of your choice:\n\nFrightful Presence. When you create this aura, and as a bonus action on subsequent turns, you can choose a creature within the aura. The target must succeed on a Wisdom saving throw against your ki save DC or become frightened of you for 1 minute. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a successful save.\n\nResistance. Choose a damage type when you activate this aura: acid, cold, fire, lightning, or poison. You and your allies within the aura have resistance to that damage.\n\nOnce you create this aura, you can’t create it again until you finish a long rest, unless you expend 3 ki points to create it again.", "Recurso de Caminho do Dragão Ascendente de 11º Nível\n\nO poder do seu espírito dracônico agora irradia de você, protegendo seus aliados ou inspirando medo nos seus inimigos. Como uma ação bônus, você pode criar uma aura de poder dracônico que irradia 3 m a partir de você por 1 minuto. Pela duração, você ganha um dos seguintes efeitos à sua escolha:\n\nPresença Aterradora. Quando criar esta aura, e como uma ação bônus em turnos subsequentes, você pode escolher uma criatura dentro da aura. O alvo deve ser bem-sucedido em uma salvaguarda de Sabedoria contra a CD de resistência do seu ki ou ficará amedrontado por você por 1 minuto. O alvo pode repetir a salvaguarda no final de cada um dos turnos dele, encerrando o efeito em si mesmo em caso de sucesso.\n\nResistência. Escolha um tipo de dano ao ativar esta aura: ácido, frio, fogo, elétrico ou veneno. Você e seus aliados dentro da aura têm resistência a esse dano.\n\nDepois de criar esta aura, você não pode criá-la novamente até terminar um descanso longo, a menos que gaste 3 pontos de ki para criá-la outra vez."],
      [17, 'Ascendant Aspect', 'Aspecto Ascendente', "17th-Level Way of the Ascendant Dragon Feature\n\nYour draconic spirit reaches its peak. You gain the following benefits:\n\nAugment Breath. When you use your Breath of the Dragon, you can spend 1 ki point to augment its shape and power. The exhalation of draconic energy becomes either a 60-foot cone or a 90-foot line that is 5 feet wide (your choice), and each creature in that area takes damage equal to four rolls of your Martial Arts die on a failed save, or half as much damage on a successful one.\n\nBlindsight. You gain blindsight out to 10 feet. Within that range, you can effectively see anything that isn’t behind total cover, even if you’re blinded or in darkness. Moreover, you can see an invisible creature within that range, unless the creature successfully hides from you.\n\nExplosive Fury. When you activate your Aspect of the Wyrm, draconic fury explodes from you. Choose any number of creatures you can see in your aura. Each of those creatures must succeed on a Dexterity saving throw against your ki save DC or take 3d10 acid, cold, fire, lightning, or poison damage (your choice).", "Recurso de Caminho do Dragão Ascendente de 17º Nível\n\nSeu espírito dracônico atinge o auge. Você ganha os seguintes benefícios:\n\nAmpliar Sopro. Quando usar seu Sopro do Dragão, você pode gastar 1 ponto de ki para ampliar sua forma e poder. A exalação de energia dracônica torna-se um cone de 18 m ou uma linha de 27 m com 1,5 m de largura (à sua escolha), e cada criatura nessa área sofre dano igual a quatro rolagens do seu dado de Artes Marciais se falhar na salvaguarda, ou metade desse dano se obtiver sucesso.\n\nPercepção às Cegas. Você ganha percepção às cegas com alcance de 3 m. Dentro desse alcance, você pode ver efetivamente qualquer coisa que não esteja atrás de cobertura total, mesmo se estiver cego ou na escuridão. Além disso, pode ver uma criatura invisível dentro desse alcance, a menos que a criatura se esconda com sucesso de você.\n\nFúria Explosiva. Quando você ativar seu Aspecto do Wyrm, fúria dracônica explode a partir de você. Escolha qualquer número de criaturas que você possa ver na sua aura. Cada uma dessas criaturas deve ser bem-sucedida em uma salvaguarda de Destreza contra a CD de resistência do seu ki ou sofrerá 3d10 de dano ácido, de frio, fogo, elétrico ou veneno (à sua escolha)."],
    ],
  },
  paladin: {
    oathbreaker: [
      [3, 'Channel Divinity: Control Undead', 'Canalizar Divindade: Controlar Mortos-Vivos', "As an action, the paladin targets one undead creature he or she can see within 30 feet of him or her. The target must make a Wisdom saving throw. On a failed save, the target must obey the paladin's commands for the next 24 hours, or until the paladin uses this Channel Divinity option again. An undead whose challenge rating is equal to or greater than the paladin's level is immune to this effect.", "Como uma ação, o paladino escolhe como alvo uma criatura morta-viva que possa ver a até 9 m dele. O alvo deve fazer uma salvaguarda de Sabedoria. Em uma falha na salvaguarda, o alvo deve obedecer aos comandos do paladino pelas próximas 24 horas ou até que o paladino use esta opção de Canalizar Divindade novamente. Um morto-vivo cujo nível de desafio seja igual ou superior ao nível do paladino é imune a este efeito."],
      [3, 'Channel Divinity: Dreadful Aspect', 'Canalizar Divindade: Aspecto Terrível', "As an action, the paladin channels the darkest emotions and focuses them into a burst of magical menace. Each creature of the paladin's choice within 30 feet of the paladin must make a Wisdom saving throw if it can see the paladin. On a failed save, the target is frightened of the paladin for 1 minute. If a creature frightened by this effect ends its turn more than 30 feet away from the paladin, it can attempt another Wisdom saving throw to end the effect on it.", "Como uma ação, o paladino canaliza as emoções mais sombrias e as concentra em uma explosão de ameaça mágica. Cada criatura à escolha do paladino a até 9 metros do paladino deve fazer uma salvaguarda de Sabedoria se puder ver o paladino. Em uma falha na salvaguarda, o alvo fica amedrontado pelo paladino por 1 minuto. Se uma criatura amedrontada por este efeito terminar seu turno a mais de 9 metros de distância do paladino, ela pode tentar outra salvaguarda de Sabedoria para encerrar o efeito sobre si."],
      [7, 'Aura of Hate', 'Aura de Ódio', "Starting at 7th level, the paladin, as well any fiends and undead within 10 feet of the paladin, gains a bonus to melee weapon damage rolls equal to the paladin's Charisma modifier (minimum of +1). A creature can benefit from this feature from only one paladin at a time.\n\nAt 18th level, the range of this aura increases to 30 feet.", "A partir do 7º nível, o paladino, bem como quaisquer corruptores e mortos-vivos a até 3 metros do paladino, ganham um bônus nas jogadas de dano de armas corpo a corpo igual ao modificador de Carisma do paladino (mínimo de +1). Uma criatura pode se beneficiar desta característica de apenas um paladino por vez.\n\nNo 18º nível, o alcance desta aura aumenta para 9 metros."],
      [15, 'Supernatural Resistance', 'Resistência Sobrenatural', "At 15th level, the paladin gains resistance to bludgeoning, piercing, and slashing damage from nonmagical weapons.", "No 15º nível, o paladino ganha resistência a dano contundente, perfurante e cortante de armas não mágicas."],
      [20, 'Dread Lord', 'Senhor do Pavor', "At 20th-level, the paladin can, as an action, surround himself or herself with an aura of gloom that lasts for 1 minute. The aura reduces any bright light in a 30-foot radius around the paladin to dim light. Whenever an enemy that is frightened by the paladin starts its turn in the aura, it takes 4d10 psychic damage. Additionally, the paladin and creatures he or she chooses in the aura are draped in deeper shadow. Creatures that rely on sight have disadvantage on attack rolls against creatures draped in this shadow.\n\nWhile the aura lasts, the paladin can use a bonus action on his or her turn to cause the shadows in the aura to attack one creature. The paladin makes a melee spell attack against the target. If the attack hits, the target takes necrotic damage equal to 3d10 + the paladin's Charisma modifier.\n\nAfter activating the aura, the paladin can't do so again until he or she finishes a long rest.", "No 20º nível, o paladino pode, como uma ação, cercar-se com uma aura de penumbra sombria que dura 1 minuto. A aura reduz qualquer luz plena em um raio de 9 m ao redor do paladino para penumbra. Sempre que um inimigo que esteja amedrontado pelo paladino iniciar o turno na aura, ele sofre 4d10 de dano psíquico. Além disso, o paladino e as criaturas que ele escolher na aura ficam envoltos em sombras mais densas. Criaturas que dependem da visão têm desvantagem nas jogadas de ataque contra criaturas envoltas nessa sombra.\n\nEnquanto a aura durar, o paladino pode usar uma ação bônus no turno dele para fazer as sombras na aura atacarem uma criatura. O paladino faz um ataque corpo a corpo com magia contra o alvo. Se o ataque acertar, o alvo sofre dano necrótico igual a 3d10 + o modificador de Carisma do paladino.\n\nApós ativar a aura, o paladino não pode fazê-lo novamente até terminar um descanso longo."],
    ],
    crown: [
      [3, 'Channel Divinity: Champion Challenge', 'Canalizar Divindade: Desafio do Campeão', "As a bonus action, you issue a challenge that compels other creatures to do battle with you. Each creature of your choice that you can see within 30 feet of you must make a Wisdom saving throw. On a failed save, a creature can't willingly move more than 30 feet away from you. This effect ends on the creature if you are incapacitated or die or if the creature is more than 30 feet away from you.", "Como uma ação bônus, você emite um desafio que compele outras criaturas a batalhar com você. Cada criatura à sua escolha que você possa ver a até 9 m de você deve fazer uma salvaguarda de Sabedoria. Em uma falha na salvaguarda, a criatura não pode se afastar voluntariamente para mais de 9 m de você. Esse efeito termina na criatura se você ficar incapacitado ou morrer, ou se a criatura ficar a mais de 9 m de você."],
      [3, 'Channel Divinity: Turn the Tide', 'Canalizar Divindade: Virar a Maré', "As a bonus action, you can bolster injured creatures with your Channel Divinity. Each creature of your choice that can hear you within 30 feet of you regains hit points equal to 1d6 + your Charisma modifier (minimum of 1) if it has no more than half of its hit points.", "Como uma ação bônus, você pode revigorar criaturas feridas com sua Canalizar Divindade. Cada criatura à sua escolha que possa ouvi-lo a até 9 metros de você recupera pontos de vida iguais a 1d6 + seu modificador de Carisma (mínimo de 1) se ela não tiver mais do que metade dos seus pontos de vida."],
      [7, 'Divine Allegiance', 'Lealdade Divina', "Starting at 7th level, when a creature within 5 feet of you takes damage, you can use your reaction to magically substitute your own health for that of the target creature, causing that creature not to take the damage. Instead, you take the damage. This damage to you can't be reduced or prevented in any way.", "A partir do 7º nível, quando uma criatura a até 1,5 metro de você sofrer dano, você pode usar sua reação para substituir magicamente a sua própria saúde pela da criatura alvo, fazendo com que aquela criatura não sofra o dano. Em vez disso, você sofre o dano. Este dano causado a você não pode ser reduzido nem prevenido de nenhuma forma."],
      [15, 'Unyielding Spirit', 'Espírito Inquebrantável', "Starting at 15th level, you have advantage on saving throws to avoid becoming paralyzed or stunned.", "A partir do 15º nível, você tem vantagem em salvaguardas para evitar ficar paralisado ou atordoado."],
      [20, 'Exalted Champion', 'Campeão Exaltado', "At 20th level, your presence on the field of battle is an inspiration to those dedicated to your cause. You can use your action to gain the following benefits for 1 hour:\n\n• You have resistance to bludgeoning, piercing, and slashing damage from nonmagical weapons.\n\n• Your allies have advantage on death saving throws while within 30 feet of you.\n\n• You have advantage on Wisdom saving throws, as do your allies within 30 feet of you.\n\nThis effect ends early if you are incapacitated or die. Once you use this feature, you can't use it again until you finish a long rest.", "No 20º nível, sua presença no campo de batalha é uma inspiração para aqueles dedicados à sua causa. Você pode usar sua ação para ganhar os seguintes benefícios por 1 hora:\n\n• Você tem resistência a dano contundente, perfurante e cortante de armas não mágicas.\n\n• Seus aliados têm vantagem em salvaguardas contra a morte enquanto estiverem a até 9 m de você.\n\n• Você tem vantagem em salvaguardas de Sabedoria, assim como seus aliados a até 9 m de você.\n\nEsse efeito termina prematuramente se você ficar incapacitado ou morrer. Depois de usar este recurso, você não pode usá-lo novamente até terminar um descanso longo."],
    ],
    conquest: [
      [3, 'Channel Divinity: Conquering Presence', 'Canalizar Divindade: Presença Conquistadora', "You can use your Channel Divinity to exude a terrifying presence. As an action, you force each creature of your choice that you can see within 30 feet of you to make a Wisdom saving throw. On a failed save, a creature becomes frightened of you for 1 minute. The frightened creature can repeat this saving throw at the end of each of its turns, ending the effect on itself on a success.", "Você pode usar sua Canalizar Divindade para exalar uma presença aterrorizante. Como uma ação, você força cada criatura à sua escolha que possa ver a até 9 metros de você a fazer uma salvaguarda de Sabedoria. Em uma falha na salvaguarda, a criatura fica amedrontada por você durante 1 minuto. A criatura amedrontada pode repetir essa salvaguarda no final de cada um de seus turnos, encerrando o efeito sobre si com um sucesso."],
      [3, 'Channel Divinity: Guided Strike', 'Canalizar Divindade: Golpe Guiado', "You can use your Channel Divinity to strike with supernatural accuracy. When you make an attack roll, you can use your Channel Divinity to gain a +10 bonus to the roll. You make this choice after you see the roll, but before the DM says whether the attack hits or misses.", "Você pode usar sua Canalizar Divindade para desferir um golpe com precisão sobrenatural. Ao fazer uma jogada de ataque, você pode usar sua Canalizar Divindade para ganhar um bônus de +10 na jogada. Você faz essa escolha após ver a jogada, mas antes do Mestre dizer se o ataque acertou ou errou."],
      [7, 'Aura of Conquest', 'Aura da Conquista', "Starting at 7th level, you constantly emanate a menacing aura while you’re not incapacitated. The aura extends 10 feet from you in every direction, but not through total cover.\n\nIf a creature is frightened of you, its speed is reduced to 0 while in the aura, and that creature takes psychic damage equal to half your paladin level if it starts its turn there.\n\nAt 18th level, the range of this aura increases to 30 feet.", "A partir do 7º nível, você emana constantemente uma aura ameaçadora enquanto não estiver incapacitado. A aura se estende por 3 m a partir de você em todas as direções, mas não atravessa cobertura total.\n\nSe uma criatura estiver amedrontada por você, o deslocamento dela é reduzido a 0 enquanto estiver na aura, e essa criatura sofre dano psíquico igual à metade do seu nível de paladino se iniciar o turno nela.\n\nNo 18º nível, o alcance desta aura aumenta para 9 m."],
      [15, 'Scornful Rebuke', 'Repreensão Desdenhosa', "Starting at 15th level, those who dare to strike you are psychically punished for their audacity. Whenever a creature hits you with an attack, that creature takes psychic damage equal to your Charisma modifier (minimum of 1) if you’re not incapacitated.", "A partir do 15º nível, aqueles que ousam golpeá-lo são punidos psiquicamente por sua audácia. Sempre que uma criatura acertar você com um ataque, ela sofrerá dano psíquico igual ao seu modificador de Carisma (mínimo de 1) se você não estiver incapacitado."],
      [20, 'Invincible Conqueror', 'Conquistador Invencível', "At 20th level, you gain the ability to harness extraordinary martial prowess. >As an action, you can magically become an avatar of conquest, gaining the following benefits for 1 minute:\n\n• You have resistance to all damage dealt by other creatures (their attacks, spells, and other effects).\n\n• When you take the Attack action on your turn, you can make one additional attack as part of that action.\n\n• Your melee weapon attacks score a critical hit on a roll of 19 or 20 on the d20.\n\nOnce you use this feature, you can’t use it again until you finish a long rest.", "No 20º nível, você adquire a capacidade de canalizar uma proeza marcial extraordinária. >Como uma ação, você pode se transformar magicamente em um avatar da conquista, recebendo os seguintes benefícios por 1 minuto:\n\n• Você tem resistência a todo dano causado por outras criaturas (seus ataques, magias e outros efeitos).\n\n• Ao realizar a ação de Ataque em seu turno, você pode fazer um ataque adicional como parte dessa ação.\n\n• Seus ataques corpo a corpo com arma desferem um acerto crítico com um resultado de 19 ou 20 no d20.\n\nUma vez usada essa característica, você não pode usá-la novamente até terminar um descanso longo."],
    ],
    redemption: [
      [3, 'Channel Divinity: Emissary of Peace', 'Canalizar Divindade: Emissário da Paz', "You can use your Channel Divinity to augment your presence with divine power. As a bonus action, you grant yourself a +5 bonus to Charisma (Persuasion) checks for the next 10 minutes.", "Você pode usar sua Canalizar Divindade para aprimorar sua presença com poder divino. Como uma ação bônus, você concede a si mesmo um bônus de +5 em testes de Carisma (Persuasão) pelos próximos 10 minutos."],
      [3, 'Channel Divinity: Rebuke the Violent', 'Canalizar Divindade: Repreender o Violento', "You can use your Channel Divinity to rebuke those who use violence. Immediately after an attacker within 30 feet of you deals damage with an attack against a creature other than you, you can use your reaction to force the attacker to make a Wisdom saving throw. On a failed save, the attacker takes radiant damage equal to the damage it just dealt. On a successful save, it takes half as much damage.", "Você pode usar seu Canalizar Divindade para repreender aqueles que usam violência. Imediatamente após um atacante a até 9 m de você causar dano com um ataque contra uma criatura que não seja você, você pode usar sua reação para forçar o atacante a fazer uma salvaguarda de Sabedoria. Em uma falha na salvaguarda, o atacante sofre dano radiante igual ao dano que acabou de causar. Em caso de sucesso, sofre metade desse dano."],
      [7, 'Aura of the Guardian', 'Aura do Guardião', "Starting at 7th level, you can shield others from harm at the cost of your own health. When a creature within 10 feet of you takes damage, you can use your reaction to magically take that damage, instead of that creature taking it. This feature doesn't transfer any other effects that might accompany the damage, and this damage can't be reduced in any way.\n\nAt 18th level, the range of this aura increases to 30 feet.", "A partir do 7º nível, você pode proteger outros contra danos ao custo de sua própria integridade física. Quando uma criatura a até 3 metros de você sofre dano, você pode usar sua reação para assumir magicamente esse dano, em vez de a criatura sofrê-lo. Esta característica não transfere nenhum outro efeito que possa acompanhar o dano, e esse dano não pode ser reduzido de forma alguma.\n\nNo 18º nível, o alcance desta aura aumenta para 9 metros."],
      [15, 'Protective Spirit', 'Espírito Protetor', "Starting at 15th level, a holy presence mends your wounds in battle. You regain hit points equal to 1d6 + half your paladin level if you end your turn in combat with fewer than half of your hit points remaining and you aren't incapacitated.", "A partir do 15º nível, uma presença sagrada sara suas feridas em batalha. Você recupera pontos de vida iguais a 1d6 + metade do seu nível de paladino se terminar o seu turno em combate com menos da metade dos seus pontos de vida restantes e não estiver incapacitado."],
      [20, 'Emissary of Redemption', 'Emissário da Redenção', "At 20th level, you become an avatar of peace, which gives you two benefits:\n\n• You have resistance to all damage dealt by other creatures (their attacks, spells, and other effects).\n\n• Whenever a creature hits you with an attack, it takes radiant damage equal to half the damage you take from the attack.\n\nIf you attack a creature, cast a spell on it, or deal damage to it by any means but this feature, neither benefit works against that creature until you finish a long rest.", "No 20º nível, você se torna um avatar da paz, o que lhe concede dois benefícios:\n\n• Você tem resistência a todo dano causado por outras criaturas (seus ataques, magias e outros efeitos).\n\n• Sempre que uma criatura atingir você com um ataque, ela sofre dano radiante igual à metade do dano que você sofreu com o ataque.\n\nSe você atacar uma criatura, conjurar uma magia sobre ela ou causar dano a ela por qualquer meio que não seja este recurso, nenhum dos dois benefícios funciona contra essa criatura até você terminar um descanso longo."],
    ],
    glory: [
      [3, 'Channel Divinity: Peerless Athlete', 'Canalizar Divindade: Atleta Inigualável', "As a bonus action, you can use your Channel Divinity to augment your athleticism. For the next 10 minutes, you have advantage on Strength (Athletics) and Dexterity (Acrobatics) checks; you can carry, push, drag, and lift twice as much weight as normal; and the distance of your long and high jumps increases by 10 feet (this extra distance costs movement as normal).", "Como uma ação bônus, você pode usar seu Canalizar Divindade para aprimorar seu atletismo. Pelos próximos 10 minutos, você tem vantagem em testes de Força (Atletismo) e Destreza (Acrobacia); pode carregar, empurrar, arrastar e erguer o dobro do peso normal; e a distância dos seus saltos em distância e em altura aumenta em 3 m (essa distância extra consome deslocamento normalmente)."],
      [3, 'Channel Divinity: Inspiring Smite', 'Canalizar Divindade: Destruição Inspiradora', "Immediately after you deal damage to a creature with your Divine Smite feature, you can use your Channel Divinity as a bonus action and distribute temporary hit points to creatures of your choice within 30 feet of you, which can include you. The total number of temporary hit points equals 2d8 + your level in this class, divided among the chosen creatures however you like.", "Imediatamente após causar dano a uma criatura com sua característica Destruição Divina, você pode usar sua Canalizar Divindade como uma ação bônus e distribuir pontos de vida temporários para criaturas à sua escolha a até 9 metros de você, podendo incluir você mesmo. O número total de pontos de vida temporários é igual a 2d8 + seu nível nesta classe, dividido entre as criaturas escolhidas da forma que preferir."],
      [7, 'Aura of Alacrity', 'Aura da Agilidade', "7th- and 18th-level Oath of Glory feature\n\nYou emanate an aura that fills you and your companions with supernatural speed, allowing you to race across a battlefield in formation. Your walking speed increases by 10 feet. In addition, if you aren’t incapacitated, the walking speed of any ally who starts their turn within 5 feet of you increases by 10 feet until the end of that turn.\n\nWhen you reach 18th level in this class, the range of the aura increases to 10 feet.", "Recurso de Juramento da Glória de 7º e 18º nível\n\nVocê emana uma aura que preenche você e seus companheiros com velocidade sobrenatural, permitindo cruzar o campo de batalha em formação. Seu deslocamento de caminhada aumenta em 3 m. Além disso, se você não estiver incapacitado, o deslocamento de caminhada de qualquer aliado que iniciar o turno dele a até 1,5 m de você aumenta em 3 m até o final daquele turno.\n\nQuando você alcançar o 18º nível nesta classe, o alcance da aura aumenta para 3 m."],
      [15, 'Glorious Defense', 'Defesa Gloriosa', "15th-level Oath of Glory feature\n\nYou can turn defense into a sudden strike. When you or another creature you can see within 10 feet of you is hit by an attack roll, you can use your reaction to grant a bonus to the target's AC against that attack, potentially causing it to miss. The bonus equals your Charisma modifier (minimum of +1). If the attack misses, you can make one weapon attack against the attacker as part of this reaction, provided the attacker is within your weapon's range.\n\nYou can use this feature a number of times equal to your Charisma modifier (minimum of once), and you regain all expended uses when you finish a long rest.", "Recurso de Juramento da Glória de 15º nível\n\nVocê pode transformar defesa em um golpe súbito. Quando você ou outra criatura que você possa ver a até 3 m de você for atingida por uma jogada de ataque, você pode usar sua reação para conceder um bônus à CA do alvo contra esse ataque, potencialmente fazendo com que ele erre. O bônus é igual ao seu modificador de Carisma (mínimo de +1). Se o ataque errar, você pode fazer um ataque com arma contra o atacante como parte desta reação, desde que o atacante esteja dentro do alcance da sua arma.\n\nVocê pode usar este recurso um número de vezes igual ao seu modificador de Carisma (mínimo de uma vez) e recupera todos os usos gastos quando termina um descanso longo."],
      [20, 'Living Legend', 'Lenda Viva', "20th-level Oath of Glory feature\n\nYou can empower yourself with the legends—whether true or exaggerated—of your great deeds. As a bonus action, you gain the following benefits for 1 minute:\n\n• You are blessed with an otherworldly presence, gaining advantage on all Charisma checks.\n\n• Once on each of your turns when you make a weapon attack and miss, you can cause that attack to hit instead.\n\n• If you fail a saving throw, you can use your reaction to reroll it. You must use this new roll.\n\nOnce you use this bonus action, you can’t use it again until you finish a long rest, unless you expend a 5th-level spell slot to use it again.", "Recurso de Juramento da Glória de 20º nível\n\nVocê pode fortalecer a si mesmo com as lendas — verdadeiras ou exageradas — de seus grandes feitos. Como uma ação bônus, você ganha os seguintes benefícios por 1 minuto:\n\n• Você é abençoado com uma presença sobrenatural, ganhando vantagem em todos os testes de Carisma.\n\n• Uma vez em cada um dos seus turnos, quando você fizer um ataque com arma e errar, pode fazer com que esse ataque acerte em vez disso.\n\n• Se você falhar em uma salvaguarda, pode usar sua reação para rolá-la novamente. Você deve usar o novo resultado.\n\nDepois de usar esta ação bônus, você não pode usá-la novamente até terminar um descanso longo, a menos que gaste um espaço de magia de 5º círculo para usá-la novamente."],
    ],
    watchers: [
      [3, 'Channel Divinity: Watcher\'s Will', 'Canalizar Divindade: Vontade do Vigia', "You can use your Channel Divinity to invest your presence with the warding power of your faith. As an action, you can choose a number of creatures you can see within 30 feet of you, up to a number equal to your Charisma modifier (minimum of one creature). For 2 minutes, you and the chosen creatures have advantage on Intelligence, Wisdom, and Charisma saving throws.", "Você pode usar sua Canalizar Divindade para imbuir sua presença com o poder de proteção de sua fé. Como uma ação, você pode escolher um número de criaturas que possa ver a até 9 metros de você, até um número igual ao seu modificador de Carisma (mínimo de uma criatura). Durante 2 minutos, você e as criaturas escolhidas têm vantagem em salvaguardas de Inteligência, Sabedoria e Carisma."],
      [3, 'Channel Divinity: Abjure the Extraplanar', 'Canalizar Divindade: Abjurar o Extraplanar', "You can use your Channel Divinity to castigate unworldly beings. As an action, you present your holy symbol and each aberration, celestial, elemental, fey, or fiend within 30 feet of you that can hear you must make a Wisdom saving throw. On a failed save, the creature is turned for 1 minute or until it takes damage.\n\nA turned creature must spend its turns trying to move as far away from you as it can, and it can’t willingly end its move in a space within 30 feet of you. For its action, it can use only the Dash action or try to escape from an effect that prevents it from moving. If there’s nowhere to move, the creature can take the Dodge action.", "Você pode usar seu Canalizar Divindade para castigar seres extraplanares. Como uma ação, você apresenta seu símbolo sagrado e cada aberração, celestial, elemental, feérico ou corruptor a até 9 m de você que possa ouvi-lo deve fazer uma salvaguarda de Sabedoria. Em uma falha na salvaguarda, a criatura fica expulsa por 1 minuto ou até sofrer dano.\n\nUma criatura expulsa deve gastar seus turnos tentando se afastar de você o máximo que puder e não pode terminar voluntariamente seu movimento em um espaço a até 9 m de você. Para sua ação, ela pode usar apenas a ação de Disparada ou tentar escapar de um efeito que a impeça de se mover. Se não houver para onde se mover, a criatura pode realizar a ação de Esquiva."],
      [7, 'Aura of the Sentinel', 'Aura da Sentinela', "7th-level Oath of the Watchers feature\n\nYou emit an aura of alertness while you aren’t incapacitated. When you and any creatures of your choice within 10 feet of you roll initiative, you all gain a bonus to initiative equal to your proficiency bonus.\n\nAt 18th level, the range of this aura increases to 30 feet.", "Característica de 7º nível do Juramento dos Vigilantes\n\nVocê emite uma aura de alerta enquanto não estiver incapacitado. Quando você e quaisquer criaturas à sua escolha a até 3 metros de você rolarem iniciativa, todos vocês recebem um bônus na iniciativa igual ao seu bônus de proficiência.\n\nNo 18º nível, o alcance desta aura aumenta para 9 metros."],
      [15, 'Vigilant Rebuke', 'Repreensão Vigilante', "15th-level Oath of the Watchers feature\n\nYou’ve learned how to chastise anyone who dares wield beguilements against you and your wards. Whenever a creature you can see within 30 feet of you succeeds on an Intelligence, a Wisdom, or a Charisma saving throw, you can use your reaction to deal 2d8 + your Charisma modifier force damage to the creature that forced the saving throw.", "Característica de 15º nível do Juramento dos Vigilantes\n\nVocê aprendeu como castigar qualquer um que ouse empunhar ilusões e artimanhas contra você e seus protegidos. Sempre que uma criatura que você possa ver a até 9 metros de você obtiver sucesso em uma salvaguarda de Inteligência, Sabedoria ou Carisma, você pode usar sua reação para causar 2d8 + seu modificador de Carisma de dano de energia à criatura que exigiu a salvaguarda."],
      [20, 'Mortal Bulwark', 'Baluarte Mortal', "20th-level Oath of the Watchers feature\n\nYou manifest a spark of divine power in defense of the mortal realms. As a bonus action, you gain the following benefits for 1 minute:\n\n• You gain truesight with a range of 120 feet.\n\n• You have advantage on attack rolls against aberrations, celestials, elementals, fey, and fiends.\n\n• When you hit a creature with an attack roll and deal damage to it, you can also force it to make a Charisma saving throw against your spell save DC. On a failed save, the creature is magically banished to its native plane of existence if it’s currently not there. On a successful save, the creature can’t be banished by this feature for 24 hours.\n\nOnce you use this bonus action, you can’t use it again until you finish a long rest, unless you expend a 5th-level spell slot to use it again.", "Recurso de Juramento dos Sentinelas de 20º nível\n\nVocê manifesta uma centelha de poder divino em defesa dos reinos mortais. Como uma ação bônus, você ganha os seguintes benefícios por 1 minuto:\n\n• Você ganha visão verdadeira com alcance de 36 m.\n\n• Você tem vantagem nas jogadas de ataque contra aberrações, celestiais, elementais, feéricos e corruptores.\n\n• Quando você atingir uma criatura com uma jogada de ataque e causar dano a ela, também pode forçá-la a fazer uma salvaguarda de Carisma contra a CD da sua magia. Em uma falha na salvaguarda, a criatura é magicamente banida para seu plano de existência nativo se não estiver nele no momento. Em caso de sucesso, a criatura não pode ser banida por este recurso por 24 horas.\n\nDepois de usar esta ação bônus, você não pode usá-la novamente até terminar um descanso longo, a menos que gaste um espaço de magia de 5º círculo para usá-la novamente."],
    ],
  },
  ranger: {
    gloomstalker: [
      [3, 'Dread Ambusher', 'Emboscador Temível', "At 3rd level, you master the art of the ambush. You can give yourself a bonus to your initiative rolls equal to your Wisdom modifier.\n\nAt the start of your first turn of each combat, your walking speed increases by 10 feet, which lasts until the end of that turn. If you take the Attack action on that turn, you can make one additional weapon attack as part of that action. If that attack hits, the target takes an extra 1d8 damage of the weapons damage type.", "No 3º nível, você domina a arte da emboscada. Você pode conceder a si mesmo um bônus nas jogadas de iniciativa igual ao seu modificador de Sabedoria.\n\nNo início do seu primeiro turno em cada combate, seu deslocamento de caminhada aumenta em 3 m, durando até o final daquele turno. Se você realizar a ação de Ataque nesse turno, pode fazer um ataque com arma adicional como parte dessa ação. Se esse ataque acertar, o alvo sofre 1d8 de dano adicional do tipo de dano da arma."],
      [3, 'Umbral Sight', 'Visão Umbral', "At 3rd level, you gain darkvision out to a range of 60 feet. If you already have darkvision from your race, its range increases by 30 feet.\n\nYou are also adept at evading creatures that rely on darkvision. While in darkness, you are invisible to any creature that relies on darkvision to see you in that darkness.", "No 3º nível, você ganha visão no escuro com alcance de 18 metros. Se você já possuir visão no escuro proveniente de sua espécie, o alcance dela aumenta em 9 metros.\n\nVocê também é adepto em iludir criaturas que dependem de visão no escuro. Enquanto estiver na escuridão, você fica invisível para qualquer criatura que dependa de visão no escuro para enxergá-lo nessa escuridão."],
      [7, 'Iron Mind', 'Mente de Ferro', "By 7th level, you have honed your ability to resist the mind—altering powers of your prey. You gain proficiency in Wisdom saving throws. If you already have this proficiency, you instead gain proficiency in Intelligence or Charisma saving throws (your choice).", "No 7º nível, você aprimorou sua capacidade de resistir aos poderes de alteração mental de suas presas. Você ganha proficiência em salvaguardas de Sabedoria. Se você já possuir essa proficiência, em vez disso ganha proficiência em salvaguardas de Inteligência ou Carisma (à sua escolha)."],
      [11, 'Stalker\'s Flurry', 'Rajada do Espreitador', "At 11th level, you learn to attack with such unexpected speed that you can turn a miss into another strike. Once on each of your turns when you miss with a weapon attack, you can make another weapon attack as part of the same action.", "No 11º nível, você aprende a atacar com uma velocidade tão inesperada que pode transformar um erro em outro golpe. Uma vez em cada um dos seus turnos, quando você errar com um ataque com arma, pode fazer outro ataque com arma como parte da mesma ação."],
      [15, 'Shadowy Dodge', 'Esquiva Sombria', "Starting at 15th level, you can dodge in unforeseen ways, with wisps of supernatural shadow around you. Whenever a creature makes an attack roll against you and doesn’t have advantage on the roll, you can use your reaction to impose disadvantage on it. You must use this feature before you know the outcome of the attack roll.", "A partir do 15º nível, você pode se esquivar de maneiras imprevistas, envolto por filetes de sombras sobrenaturais. Sempre que uma criatura fizer uma jogada de ataque contra você e não tiver vantagem na jogada, você pode usar sua reação para impor desvantagem a ela. Você deve usar esta característica antes de saber o resultado da jogada de ataque."],
    ],
    horizonwalker: [
      [3, 'Detect Portal', 'Detectar Portal', "At 3rd level, you gain the ability to magically sense the presence of a planar portal. As an action, you detect the distance and direction to the closest planar portal within 1 mile of you.\n\nOnce you use this feature, you can’t use it again until you finish a short or long rest.\n\nSee the \"Planar Travel\" section in chapter 2 of the Dungeon Master’s Guide for examples of planar portals.", "No 3º nível, você adquire a capacidade de pressentir magicamente a presença de um portal planar. Como uma ação, você detecta a distância e a direção para o portal planar mais próximo a até 1,5 quilômetro de você.\n\nUma vez usada essa característica, você não pode usá-la novamente até terminar um descanso curto ou longo.\n\nConsulte a seção \"Viagem Planar\" no capítulo 2 do Guia do Mestre para exemplos de portais planares."],
      [3, 'Planar Warrior', 'Guerreiro Planar', "At 3rd level, you learn to draw on the energy of the multiverse to augment your attacks.\n\nAs a bonus action, choose one creature you can see within 30 feet of you. The next time you hit that creature on this turn with a weapon attack, all damage dealt by the attack becomes force damage, and the creature takes an extra 1d8 force damage from the attack. When you reach 11th level in this class, the extra damage increases to 2d8.", "No 3º nível, você aprende a extrair energia do multiverso para potencializar seus ataques.\n\nComo uma ação bônus, escolha uma criatura que possa ver a até 9 metros de você. Na próxima vez que atingir essa criatura neste turno com um ataque com arma, todo o dano causado pelo ataque se torna dano de energia, e a criatura sofre 1d8 de dano de energia adicional do ataque. Quando você alcançar o 11º nível nesta classe, o dano adicional aumenta para 2d8."],
      [7, 'Ethereal Step', 'Passo Etéreo', "At 7th level, you learn to step through the Ethereal Plane. As a bonus action, you can cast the etherealness spell with this feature, without expending a spell slot, but the spell ends at the end of the current turn.\n\nOnce you use this feature, you can’t use it again until you finish a short or long rest.", "No 7º nível, você aprende a transitar pelo Plano Etéreo. Como uma ação bônus, você pode conjurar a magia forma etérea com esta característica, sem gastar um espaço de magia, mas a magia termina no final do turno atual.\n\nUma vez usada essa característica, você não pode usá-la novamente até terminar um descanso curto ou longo."],
      [11, 'Distant Strike', 'Golpe Distante', "At 11th level, you gain the ability to pass between the planes in the blink of an eye. When you take the Attack action, you can teleport up to 10 feet before each attack to an unoccupied space you can see.\n\nIf you attack at least two different creatures with the action, you can make one additional attack with it against a third creature.", "No 11º nível, você adquire a habilidade de transitar entre os planos em um piscar de olhos. Ao realizar a ação de Ataque, você pode se teletransportar até 3 metros antes de cada ataque para um espaço desocupado que possa ver.\n\nSe atacar pelo menos duas criaturas diferentes com a ação, você pode fazer um ataque adicional com ela contra uma terceira criatura."],
      [15, 'Spectral Defense', 'Defesa Espectral', "At 15th level, your ability to move between planes enables you to slip through the planar boundaries to lessen the harm done to you during battle. When you take damage from an attack, you can use your reaction to give yourself resistance to all of that attack’s damage on this turn.", "No 15º nível, sua habilidade de se mover entre os planos permite que você deslize pelas fronteiras planares para atenuar o dano sofrido durante o combate. Quando você sofre dano de um ataque, pode usar sua reação para conceder a si mesmo resistência a todo o dano daquele ataque neste turno."],
    ],
    monsterslayer: [
      [3, 'Hunter\'s Sense', 'Sentido do Caçador', "At 3rd level, you gain the ability to peer at a creature and magically discern how best to hurt it. As an action, choose one creature you can see within 60 feet of you. You immediately learn whether the creature has any damage immunities, resistances, or vulnerabilities and what they are. If the creature is hidden from divination magic, you sense that it has no damage immunities, resistances, or vulnerabilities.\n\nYou can use this feature a number of times equal to your Wisdom modifier (minimum of once). You regain all expended uses of it when you finish a long rest.", "No 3º nível, você ganha a capacidade de perscrutar uma criatura e discernir magicamente a melhor forma de feri-la. Como uma ação, escolha uma criatura que possa ver a até 18 metros de você. Você imediatamente descobre se a criatura tem quaisquer imunidades, resistências ou vulnerabilidades a dano e quais são elas. Se a criatura estiver oculta de magia de adivinhação, você pressente que ela não tem imunidades, resistências ou vulnerabilidades a dano.\n\nVocê pode usar esta característica um número de vezes igual ao seu modificador de Sabedoria (mínimo de uma vez). Você recupera todos os usos gastos ao terminar um descanso longo."],
      [3, 'Slayer\'s Prey', 'Presa do Matador', "Starting at 3rd level, you can focus your ire on one foe, increasing the harm you inflict on it. As a bonus action, you designate one creature you can see within 60 feet of you as the target of this feature. The first time each turn that you hit that target with a weapon attack, it takes an extra 1d6 damage from the weapon.\n\nThis benefit lasts until you finish a short or long rest. It ends early if you designate a different creature.", "A partir do 3º nível, você pode focar sua ira em um adversário, aumentando o dano que inflige a ele. Como uma ação bônus, você designa uma criatura que possa ver a até 18 metros de você como alvo desta característica. Na primeira vez a cada turno em que acertar aquele alvo com um ataque com arma, ele sofre 1d6 de dano adicional da arma.\n\nEsse benefício dura até você terminar um descanso curto ou longo. Ele termina mais cedo se você designar uma criatura diferente."],
      [7, 'Supernatural Defense', 'Defesa Sobrenatural', "At 7th level, you gain extra resilience against your prey’s assaults on your mind and body. Whenever the target of your Slayer’s Prey forces you to make a saving throw and whenever you make an ability check to escape that targets grapple, add 1d6 to your roll.", "No 7º nível, você adquire resiliência adicional contra os ataques da sua presa à sua mente e corpo. Sempre que o alvo de sua Presa do Matador forçar você a realizar uma salvaguarda e sempre que você realizar um teste de atributo para escapar do agarrão desse alvo, adicione 1d6 à sua jogada."],
      [11, 'Magic-User\'s Nemesis', 'Nêmesis dos Conjuradores', "At 11th level, you gain the ability to thwart someone else’s magic. When you see a creature casting a spell or teleporting within 60 feet of you, you can use your reaction to try to magically foil it. The creature must succeed on a Wisdom saving throw against your spell save DC, or its spell or teleport fails and is wasted.\n\nOnce you use this feature, you can’t use it again until you finish a short or long rest.", "No 11º nível, você ganha a habilidade de frustrar a magia de outra pessoa. Quando você vir uma criatura conjurando uma magia ou se teletransportando a até 18 m de você, pode usar sua reação para tentar impedi-la magicamente. A criatura deve ser bem-sucedida em uma salvaguarda de Sabedoria contra a CD da sua magia, ou sua magia ou teletransporte falha e é desperdiçado.\n\nDepois de usar este recurso, você não pode usá-lo novamente até terminar um descanso curto ou longo."],
      [15, 'Slayer\'s Counter', 'Contra-ataque do Matador', "At 15th level, you gain the ability to counterattack when your prey tries to sabotage you. If the target of your Slayer’s Prey forces you to make a saving throw, you can use your reaction to make one weapon attack against the quarry. You make this attack immediately before making the saving throw. If your attack hits, your save automatically succeeds, in addition to the attack’s normal effects.", "No 15º nível, você ganha a capacidade de contra-atacar quando sua presa tenta sabotá-lo. Se o alvo da sua Presa do Matador forçar você a fazer uma salvaguarda, você pode usar sua reação para fazer um ataque com arma contra a presa. Você faz esse ataque imediatamente antes de fazer a salvaguarda. Se o seu ataque acertar, a sua salvaguarda tem sucesso automaticamente, além dos efeitos normais do ataque."],
    ],
    feywanderer: [
      [3, 'Dreadful Strikes', 'Golpes Temíveis', "3rd-level Fey Wanderer feature\n\nYou can augment your weapon strikes with mind-scarring magic, drawn from the gloomy hollows of the Feywild. When you hit a creature with a weapon, you can deal an extra 1d4 psychic damage to the target, which can take this extra damage only once per turn.\n\nThe extra damage increases to 1d6 when you reach 11th level in this class.", "Recurso de Andarilho Feérico de 3º nível\n\nVocê pode aprimorar seus golpes com arma usando magia que marca a mente, extraída das clareiras sombrias de Faéria. Quando você atingir uma criatura com uma arma, pode causar 1d4 de dano psíquico adicional ao alvo, que pode sofrer esse dano adicional apenas uma vez por turno.\n\nO dano adicional aumenta para 1d6 quando você alcança o 11º nível nesta classe."],
      [3, 'Otherworldly Glamour', 'Fascínio Sobrenatural', "3rd-level Fey Wanderer feature\n\nYour fey qualities give you a supernatural charm. As a result, whenever you make a Charisma check, you gain a bonus to the check equal to your Wisdom modifier (minimum of +1).\n\nIn addition, you gain proficiency in one of the following skills of your choice: Deception, Performance, or Persuasion.", "Característica de 3º nível do Andarilho Feérico\n\nSuas qualidades feéricas concedem a você um charme sobrenatural. Como resultado, sempre que fizer um teste de Carisma, você ganha um bônus no teste igual ao seu modificador de Sabedoria (mínimo de +1).\n\nAlém disso, você ganha proficiência em uma das seguintes perícias à sua escolha: Enganação, Atuação ou Persuasão."],
      [7, 'Beguiling Twist', 'Reviravolta Sedutora', "7th-level Fey Wanderer feature\n\nThe magic of the Feywild guards your mind. You have advantage on saving throws against being charmed or frightened.\n\nIn addition, whenever you or a creature you can see within 120 feet of you succeeds on a saving throw against begin charmed or frightened, you can use your reaction to force a different creature you can see within 120 feet of you to make a Wisdom saving throw against your spell save DC. If the spell fails, the target is charmed or frightened by you (your choice) for 1 minute. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a successful save.", "Recurso de Andarilho Feérico de 7º nível\n\nA magia de Faéria protege sua mente. Você tem vantagem em salvaguardas contra ficar enfeitiçado ou amedrontado.\n\nAlém disso, sempre que você ou uma criatura que você possa ver a até 36 m de você obtiver sucesso em uma salvaguarda contra ficar enfeitiçado ou amedrontado, você pode usar sua reação para forçar uma criatura diferente que você possa ver a até 36 m de você a fazer uma salvaguarda de Sabedoria contra a CD da sua magia. Se a salvaguarda falhar, o alvo fica enfeitiçado ou amedrontado por você (à sua escolha) por 1 minuto. O alvo pode repetir a salvaguarda no final de cada um dos turnos dele, encerrando o efeito em si mesmo em caso de sucesso."],
      [11, 'Fey Reinforcements', 'Reforços Feéricos', "11th-level Fey Wanderer feature\n\nThe royal courts of the Feywild have blessed you with the assistance of fey beings: you know summon fey (a spell in chapter 3). It doesn’t count against the number of ranger spells you know, and you can cast it without a material component. You can also cast it once without a spell slot, and you regain the ability to do so when you finish a long rest.\n\nWhenever you start casting the spell, you can modify it so that it doesn’t require concentration. If you do so, the spell’s duration becomes 1 minute for that casting.", "Característica de 11º nível do Andarilho Feérico\n\nAs cortes reais de Faéria abençoaram você com a ajuda de seres feéricos: você conhece invocar fada (uma magia no capítulo 3). Ela não conta no número de magias de patrulheiro que você conhece, e você pode conjurá-la sem componente material. Você também pode conjurá-la uma vez sem gastar um espaço de magia e recupera a capacidade de fazê-lo ao terminar um descanso longo.\n\nSempre que começar a conjurar a magia, você pode modificá-la para que não exija concentração. Se fizer isso, a duração da magia se torna 1 minuto para aquela conjuração."],
      [15, 'Misty Wanderer', 'Andarilho Nebuloso', "15th-level Fey Wanderer feature\n\nYou can slip in and out of the Feywild to move in a blink of an eye: you can cast misty step without expending a spell slot. You can do so a number of times equal to your Wisdom modifier (minimum of once), and you regain all expended uses when you finish a long rest.\n\nIn addition, whenever you cast misty step, you can bring along one willing creature you can see within 5 feet of you. That creature teleports to an unoccupied space of your choice within 5 feet of your destination space.", "Recurso de Andarilho Feérico de 15º nível\n\nVocê pode entrar e sair de Faéria para se mover num piscar de olhos: você pode conjurar passo nebuloso sem gastar um espaço de magia. Você pode fazer isso um número de vezes igual ao seu modificador de Sabedoria (mínimo de uma vez) e recupera todos os usos gastos quando termina um descanso longo.\n\nAlém disso, sempre que conjurar passo nebuloso, você pode levar consigo uma criatura voluntária que possa ver a até 1,5 m de você. Essa criatura se teletransporta para um espaço desocupado à sua escolha a até 1,5 m do seu espaço de destino."],
    ],
    swarmkeeper: [
      [3, 'Gathered Swarm', 'Enxame Reunido', "3rd-level Swarmkeeper feature\n\nA swarm of intangible nature spirits has bonded itself to you and can assist you in battle. While you're alive, the swarm remains in your space, crawling on you or flying and skittering around you within your space. You determine its appearance, or you generate its appearance by rolling on the Swarm Appearance table.\n\nSwarm Appearance\n\nd4 | Appearance\n\n1 | Swarming insects\n\n2 | Miniature twig blights\n\n3 | Fluttering birds\n\n4 | Playful pixies\n\nOnce on each of your turns, you can cause the swarm to assist you in one of the following ways, immediately after you hit a creature with an attack:\n\n• The attack’s target takes 1d6 piercing damage from the swarm.\n\n3 | Fluttering birds\n\n4 | Playful pixies\n\n• The attack’s target must succeed on a Strength saving throw against your spell save DC or be moved by the swarm up to 15 feet horizontally in a direction of your choice.\n\n• You are moved by the swarm 5 feet horizontally in a direction of your choice.\n\nIt’s Your Swarm\n\nA Swarmkeeper’s swarm and spells are reflections of the character’s bond with nature spirits. Take the opportunity to describe the swarm and the ranger’s magic in play. For example, when your ranger casts gaseous form, they might appear to melt into the swarm, instead of a cloud of mist, or the arcane eye spell could create an extension of your swarm that spies for you. Such descriptions don’t change the effects of spells, but they are an exciting opportunity to explore your character’s narrative through their class abilities. For more guidance on customizing spells, see the \"Personalizing Spells\" section in chapter 3.\n\nAlso, remember that the swarm’s appearance is yours to customize, and don’t feel confined to a single appearance. Perhaps the spirits’ look changes with the ranger’s mood or with the seasons. You decide!", "Recurso de Guarda do Enxame de 3º nível\n\nUm enxame de espíritos intangíveis da natureza se vinculou a você e pode auxiliá-lo em batalha. Enquanto você estiver vivo, o enxame permanece no seu espaço, rastejando sobre você ou voando e zumbindo ao seu redor dentro do seu espaço. Você determina a aparência dele, ou a gera rolando na tabela Aparência do Enxame.\n\nAparência do Enxame\n\nd4 | Aparência\n\n1 | Insetos em enxame\n\n2 | Pequenos arbustos maculados em miniatura\n\n3 | Pássaros esvoaçantes\n\n4 | Pixies brincalhões\n\nUma vez em cada um dos seus turnos, você pode fazer o enxame auxiliá-lo de uma das seguintes maneiras, imediatamente após você atingir uma criatura com um ataque:\n\n• O alvo do ataque sofre 1d6 de dano perfurante causado pelo enxame.\n\n• O alvo do ataque deve ser bem-sucedido em uma salvaguarda de Força contra a CD da sua magia ou ser movido pelo enxame até 4,5 m horizontalmente em uma direção à sua escolha.\n\n• Você é movido pelo enxame 1,5 m horizontalmente em uma direção à sua escolha.\n\nÉ o Seu Enxame\n\nO enxame e as magias de um Guarda do Enxame são reflexos do vínculo do personagem com os espíritos da natureza. Aproveite a oportunidade para descrever o enxame e a magia do guardião em jogo. Por exemplo, quando seu guardião conjura forma gasosa, ele pode parecer derreter no enxame em vez de se tornar uma nuvem de névoa, ou a magia olho arcano pode criar uma extensão do seu enxame que espiona para você. Essas descrições não alteram os efeitos das magias, mas são uma oportunidade empolgante de explorar a narrativa do seu personagem por meio de suas habilidades de classe. Para mais orientações sobre como personalizar magias, consulte a seção \"Personalizando Magias\" no capítulo 3.\n\nAlém disso, lembre-se de que a aparência do enxame é sua para personalizar, e não se sinta preso a uma única aparência. Talvez o visual dos espíritos mude conforme o humor do guardião ou com as estações. Você decide!"],
      [7, 'Writhing Tide', 'Maré Ondulante', "7th-level Swarmkeeper feature\n\nYou can condense part of your swarm into a focused mass that lifts you up. As a bonus action, you gain a flying speed of 10 feet and can hover. This effect lasts for 1 minute or until you are incapacitated.\n\nYou can use this feature a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.", "Característica de 7º nível do Guardião do Enxame\n\nVocê pode condensar parte do seu enxame em uma massa concentrada que o ergue. Como uma ação bônus, você ganha um deslocamento de voo de 3 metros e pode pairar. Esse efeito dura por 1 minuto ou até você ficar incapacitado.\n\nVocê pode usar esta característica um número de vezes igual ao seu bônus de proficiência e recupera todos os usos gastos ao terminar um descanso longo."],
      [11, 'Mighty Swarm', 'Enxame Poderoso', "11th-level Swarmkeeper feature\n\nYour Gathered Swarm grows mightier in the following ways:\n\n• The damage of Gathered Swarm increases to 1d8.\n\n• If a creature fails its saving throw against being moved by Gathering Swarm, you can also cause the swarm to knock the creature prone.\n\n• When you are moved by Gathered Swarm, it gives you half cover until the start of your next turn.", "Característica de 11º nível do Guardião do Enxame\n\nSeu Enxame Reunido torna-se mais poderoso das seguintes maneiras:\n\n• O dano do Enxame Reunido aumenta para 1d8.\n\n• Se uma criatura falhar na salvaguarda contra ser movida pelo Enxame Reunido, você também pode fazer com que o enxame a derrube caída.\n\n• Quando você for movido pelo Enxame Reunido, ele concede a você meia cobertura até o início do seu próximo turno."],
      [15, 'Swarming Dispersal', 'Dispersão do Enxame', "15th-level Swarmkeeper feature\n\nYou can discorporate into your swarm, avoiding danger. When you take damage, you can use your reaction to give yourself resistance to that damage. You vanish into your swarm and then teleport to an unoccupied space that you can see within 30 feet of you, where you reappear with the swarm.\n\nYou can use this feature a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.", "Recurso de Guarda do Enxame de 15º nível\n\nVocê pode se descorporificar em seu enxame, evitando o perigo. Quando sofrer dano, você pode usar sua reação para conceder a si mesmo resistência a esse dano. Você desaparece em seu enxame e então se teletransporta para um espaço desocupado que possa ver a até 9 m de você, onde reaparece com o enxame.\n\nVocê pode usar este recurso um número de vezes igual ao seu bônus de proficiência e recupera todos os usos gastos quando termina um descanso longo."],
    ],
    drakewarden: [
      [3, 'Draconic Gift', 'Dom Dracônico', "3rd-Level Drakewarden Feature\n\nThe bond you share with your drake creates a connection to dragonkind, granting you understanding and empowering your presence. You gain the following benefits:\n\nThaumaturgy. You learn the thaumaturgy cantrip, which is a ranger spell for you.\n\nTongue of Dragons. You learn to speak, read, and write Draconic or one other language of your choice.", "Característica de 3º Nível do Guardião dos Dracos\n\nO vínculo que você compartilha com seu draco cria uma conexão com a espécie dos dragões, concedendo-lhe compreensão e empoderando sua presença. Você recebe os seguintes benefícios:\n\nTaumaturgia. Você aprende o truque taumaturgia, que é uma magia de patrulheiro para você.\n\nLíngua dos Dragões. Você aprende a falar, ler e escrever em Dracônico ou em um outro idioma à sua escolha."],
      [3, 'Drake Companion', 'Companheiro Draco', "3rd-Level Drakewarden Feature\n\nAs an action, you can magically summon the drake that is bound to you. It appears in an unoccupied space of your choice within 30 feet of you.\n\nThe drake is friendly to you and your companions, and it obeys your commands. See its game statistics in the accompanying Drake Companion stat block, which uses your proficiency bonus (PB) in several places. Whenever you summon the drake, choose a damage type listed in its Draconic Essence trait. You can determine the cosmetic characteristics of the drake, such as its color, its scale texture, or any visible effect of its Draconic Essence; your choice has no effect on its game statistics.\n\nIn combat, the drake shares your initiative count, but it takes its turn immediately after yours. It can move and use its reaction on its own, but the only action it takes on its turn is the Dodge action, unless you take a bonus action on your turn to command it to take another action. That action can be one in its stat block or some other action. If you are incapacitated, the drake can take any action of its choice, not just Dodge.\n\nThe drake remains until it is reduced to 0 hit points, until you use this feature to summon the drake again, or until you die. Anything the drake was wearing or carrying is left behind when the drake vanishes.\n\nOnce you summon the drake, you can’t do so again until you finish a long rest, unless you expend a spell slot of 1st level or higher to summon it.", "Característica de Guardião Draconiano de 3º Nível\n\nComo uma ação, você pode invocar magicamente o draco que está vinculado a você. Ele surge em um espaço desocupado à sua escolha a até 9 metros de você.\n\nO draco é amistoso a você e a seus companheiros, e obedece aos seus comandos. Veja as estatísticas de jogo dele no bloco de estatísticas Companheiro Draco anexo, que utiliza o seu bônus de proficiência (BP) em vários locais. Sempre que invocar o draco, escolha um tipo de dano listado em sua característica Essência Dracônica. Você pode determinar as características cosméticas do draco, como sua cor, a textura de suas escamas ou qualquer efeito visível de sua Essência Dracônica; sua escolha não afeta suas estatísticas de jogo.\n\nEm combate, o draco compartilha sua contagem de iniciativa, mas realiza o turno dele imediatamente após o seu. Ele pode se mover e usar a reação dele por conta própria, mas a única ação que ele realiza no turno dele é a ação de Desviar, a menos que você use uma ação bônus em seu turno para comandá-lo a realizar outra ação. Essa ação pode ser uma em seu bloco de estatísticas ou alguma outra ação. Se você estiver incapacitado, o draco pode realizar qualquer ação à escolha dele, não apenas Desviar.\n\nO draco permanece até ser reduzido a 0 pontos de vida, até você usar esta característica para invocar o draco novamente, ou até você morrer. Qualquer coisa que o draco estivesse vestindo ou carregando é deixada para trás quando o draco desaparece.\n\nUma vez que você invoque o draco, não poderá fazê-lo novamente até terminar um descanso longo, a menos que gaste um espaço de magia de 1º círculo ou superior para invocá-lo."],
      [7, 'Bond of Fang and Scale', 'Laço de Presa e Escama', "7th-Level Drakewarden Feature\n\nThe bond you share with your drake intensifies, protecting you and stoking the drake’s fury. When you summon your drake, it grows wings on its back and gains a flying speed equal to its walking speed.\n\nIn addition, while your drake is summoned, you and the drake gain the following benefits:\n\nDrake Mount. The drake grows to Medium size. Reflecting your special bond, you can use the drake as a mount if your size is Medium or smaller. While you are riding your drake, it can’t use the flying speed of this feature.\n\nMagic Fang. The drake’s Bite attack deals an extra 1d6 damage of the type chosen for the drake’s Draconic Essence.\n\nResistance. You gain resistance to the damage type chosen for the drake’s Draconic Essence.", "Característica de Guardião Draconiano de 7º Nível\n\nO vínculo que você compartilha com seu draco se intensifica, protegendo você e atiçando a fúria do draco. Quando você invoca seu draco, brotam asas em suas costas e ele ganha um deslocamento de voo igual ao seu deslocamento de caminhada.\n\nAlém disso, enquanto seu draco estiver invocado, você e o draco recebem os seguintes benefícios:\n\nMontaria Draco. O draco cresce para o tamanho Médio. Refletindo o seu vínculo especial, você pode usar o draco como uma montaria se o seu tamanho for Médio ou menor. Enquanto estiver montado em seu draco, ele não pode usar o deslocamento de voo desta característica.\n\nPresa Mágica. O ataque de Mordida do draco causa 1d6 de dano adicional do tipo escolhido para a Essência Dracônica do draco.\n\nResistência. Você ganha resistência ao tipo de dano escolhido para a Essência Dracônica do draco."],
      [11, 'Drake\'s Breath', 'Sopro do Draco', "11th-Level Drakewarden Feature\n\nAs an action, you can exhale a 30-foot cone of damaging breath or cause your drake to exhale it. Choose acid, cold, fire, lightning, or poison damage (your choice doesn’t have to match your drake’s Draconic Essence). Each creature in the cone must make a Dexterity saving throw against your spell save DC, taking 8d6 damage on a failed save, or half as much damage on a successful one.\n\nThis damage increases to 10d6 when you reach 15th level in this class.\n\nOnce you use this feature, you can’t do so again until you finish a long rest, unless you expend a spell slot of 3rd level or higher to use it again.", "Característica de Guardião Draconiano de 11º Nível\n\nComo uma ação, você pode exalar um cone de 9 metros de sopro destrutivo ou fazer com que o seu draco o exale. Escolha dano de ácido, frio, fogo, elétrico ou veneno (sua escolha não precisa corresponder à Essência Dracônica do seu draco). Cada criatura no cone deve fazer um teste de resistência de Destreza contra a CD de suas magias, sofrendo 8d6 de dano se falhar na salvaguarda, ou metade desse dano se tiver sucesso.\n\nEsse dano aumenta para 10d6 quando você atinge o 15º nível nesta classe.\n\nUma vez que você use esta característica, não poderá fazê-lo novamente até terminar um descanso longo, a menos que gaste um espaço de magia de 3º círculo ou superior para usá-la novamente."],
      [15, 'Perfected Bond', 'Laço Perfeito', "15th-Level Drakewarden Feature\n\nYour bond to your drake reaches the pinnacle of its power. While your drake is summoned, you and the drake gain the following benefits:\n\nEmpowered Bite. The drake’s Bite attack deals an extra 1d6 damage of the type chosen for its Draconic Essence (for a total of 2d6 extra damage).\n\nLarge Drake. The drake grows to Large size. When you ride your drake, it is no longer prohibited from using the flying speed of Bond of Fang and Scale.\n\nReflexive Resistance. When either you or the drake takes damage while you’re within 30 feet of each other, you can use your reaction to give yourself or the drake resistance to that instance of damage. You can use this reaction a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.", "Característica de Guardião Draconiano de 15º Nível\n\nSeu vínculo com seu draco atinge o ápice do poder. Enquanto seu draco estiver invocado, você e o draco recebem os seguintes benefícios:\n\nMordida Aprimorada. O ataque de Mordida do draco causa 1d6 de dano adicional do tipo escolhido para a Essência Dracônica dele (para um total de 2d6 de dano adicional).\n\nDraco Grande. O draco cresce para o tamanho Grande. Quando você monta em seu draco, ele não está mais proibido de usar o deslocamento de voo de Vínculo de Presa e Escama.\n\nResistência Reflexiva. Quando você ou o draco sofrer dano enquanto estiverem a até 9 metros um do outro, você pode usar sua reação para conceder a si mesmo ou ao draco resistência àquela instância de dano. Você pode usar esta reação um número de vezes igual ao seu bônus de proficiência, e recupera todos os usos gastos ao terminar um descanso longo."],
    ],
  },
  rogue: {
    mastermind: [
      [3, 'Master of Intrigue', 'Mestre da Intriga', "When you choose this archetype at 3rd level, you gain proficiency with the disguise kit, the forgery kit, and one gaming set of your choice. You also learn two languages of your choice.\n\nAdditionally, you can unerringly mimic the speech patterns and accent of a creature that you hear speak for at least 1 minute, allowing you to pass yourself off as a native speaker of a particular land, provided that you know the language.", "Quando você escolhe este arquétipo no 3º nível, você ganha proficiência com o kit de disfarce, o kit de falsificação e um conjunto de jogos à sua escolha. Você também aprende dois idiomas à sua escolha.\n\nAlém disso, você pode imitar infalivelmente os padrões de fala e o sotaque de uma criatura que você ouvir falar por pelo menos 1 minuto, permitindo que você se passe por um falante nativo de uma terra em particular, desde que conheça o idioma."],
      [3, 'Master of Tactics', 'Mestre das Táticas', "Starting at 3rd level, you can use the Help action as a bonus action. Additionally, when you use the Help action to aid an ally in attacking a creature, the target of that attack can be within 30 feet of you, rather than 5 feet of you, if the target can see or hear you.", "A partir do 3º nível, você pode usar a ação de Ajudar como uma ação bônus. Além disso, quando você usa a ação de Ajudar para auxiliar um aliado a atacar uma criatura, o alvo daquele ataque pode estar a até 9 metros de você, em vez de 1,5 metro de você, se o alvo puder ver ou ouvir você."],
      [9, 'Insightful Manipulator', 'Manipulador Perspicaz', "Starting at 9th level, if you spend at least 1 minute observing or interacting with another creature outside combat, you can learn certain information about its capabilities compared to your own. The DM tells you if the creature is your equal, superior, or inferior in regard to two of the following characteris tics of your choice:\n\n• Intelligence score\n\n• Wisdom score\n\n• Charisma score\n\n• Class levels (if any)\n\nAt the DM's option, you might also realize you know a piece of the creature's his tory or one of its personality traits, if it has any.", "A partir do 9º nível, se você passar pelo menos 1 minuto observando ou interagindo com outra criatura fora de combate, poderá aprender certas informações sobre as capacidades dela em comparação com as suas. O Mestre diz a você se a criatura é igual, superior ou inferior a você em relação a duas das seguintes características à sua escolha:\n\n• Valor de Inteligência\n\n• Valor de Sabedoria\n\n• Valor de Carisma\n\n• Níveis de classe (se houver)\n\nÀ opção do Mestre, você também pode perceber que conhece um trecho da história da criatura ou um de seus traços de personalidade, se ela tiver algum."],
      [13, 'Misdirection', 'Despistar', "Beginning at 13th level, you can sometimes cause another creature to suffer an attack meant for you. When you are targeted by an attack while a creature within 5 feet of you is granting you cover against that attack, you can use your reaction to have the attack target that creature instead of you.", "A partir do 13º nível, você às vezes pode fazer com que outra criatura sofra um ataque direcionado a você. Quando você for alvo de um ataque enquanto uma criatura a até 1,5 metro de você estiver concedendo cobertura contra aquele ataque, você pode usar sua reação para fazer com que o ataque tenha aquela criatura como alvo em vez de você."],
      [17, 'Soul of Deceit', 'Alma do Engano', "Starting at 17th level, your thoughts can't be read by telepathy or other means, unless you allow it. You can present false thoughts by making a Charisma (Deception) check contested by the mind reader's Wisdom (Insight) check.\n\nAdditionally, no matter what you say, magic that would determine if you are telling the truth indicates you are being truthful, if you so choose, and you can't be compelled to tell the truth by magic.", "A partir do 17º nível, seus pensamentos não podem ser lidos por telepatia ou outros meios, a menos que você permita. Você pode apresentar pensamentos falsos fazendo um teste de Carisma (Enganação) resistido pelo teste de Sabedoria (Intuição) do leitor de mentes.\n\nAlém disso, não importa o que você diga, magias que determinariam se você está dizendo a verdade indicam que você está sendo verdadeiro, se assim você preferir, e você não pode ser compelido a dizer a verdade por meio de magia."],
    ],
    swashbuckler: [
      [3, 'Fancy Footwork', 'Jogo de Pés', "When you choose this archetype at 3rd level, you learn how to land a strike and then slip away without reprisal. During your turn, if you make a melee attack against a creature, that creature can't make opportunity attacks against you for the rest of your turn.", "Quando você escolhe este arquétipo no 3º nível, você aprende a desferir um golpe e depois escapar sem represálias. Durante o seu turno, se você fizer um ataque corpo a corpo contra uma criatura, essa criatura não pode fazer ataques de oportunidade contra você pelo resto do seu turno."],
      [3, 'Rakish Audacity', 'Audácia Libertina', "Starting at 3rd level, your unmistakable confidence propels you into battle. You can give yourself a bonus to your initiative rolls equal to your Charisma modifier.\n\nYou also gain an additional way to use your Sneak Attack; you don’t need advantage on your attack roll to use Sneak Attack against a creature if you are within 5 feet of it, no other creatures are within 5 feet of you, and you don’t have disadvantage on the attack roll. All the other rules for Sneak Attack still apply to you.", "A partir do 3º nível, sua confiança inconfundível o impulsiona para a batalha. Você pode conceder a si mesmo um bônus nas suas jogadas de iniciativa igual ao seu modificador de Carisma.\n\nVocê também ganha uma maneira adicional de usar seu Ataque Furtivo; você não precisa de vantagem na sua jogada de ataque para usar o Ataque Furtivo contra uma criatura se estiver a até 1,5 metro dela, nenhuma outra criatura estiver a até 1,5 metro de você e você não tiver desvantagem na jogada de ataque. Todas as outras regras para o Ataque Furtivo ainda se aplicam a você."],
      [9, 'Panache', 'Panache', "At 9th level, your charm becomes extraordinarily beguiling. As an action, you can make a Charisma (Persuasion) check contested by a creature's Wisdom (Insight) check. The creature must be able to hear you, and the two of you must share a language.\n\nIf you succeed on the check and the creature is hostile to you, it has disadvantage on attack rolls against targets other than you and can't make opportunity attacks against targets other than you. This effect lasts for 1 minute, until one of your companions attacks the target or affects it with a spell, or until you and the target are more than 60 feet apart.\n\nIf you succeed on the check and the creature isn't hostile to you, it is charmed by you for 1 minute. While charmed, it regards you as a friendly acquaintance. This effect ends immediately if you or your companions do anything harmful to it.", "No 9º nível, seu charme torna-se extraordinariamente sedutor. Como uma ação, você pode fazer um teste de Carisma (Persuasão) resistido pelo teste de Sabedoria (Intuição) de uma criatura. A criatura deve ser capaz de ouvir você, e vocês dois devem compartilhar um idioma.\n\nSe você for bem-sucedido no teste e a criatura for hostil a você, ela terá desvantagem em jogadas de ataque contra outros alvos além de você e não poderá fazer ataques de oportunidade contra outros alvos além de você. Esse efeito dura por 1 minuto, até que um de seus companheiros ataque o alvo ou o afete com uma magia, ou até que você e o alvo estejam a mais de 18 metros de distância um do outro.\n\nSe você for bem-sucedido no teste e a criatura não for hostil a você, ela fica enfeitiçada por você por 1 minuto. Enquanto estiver enfeitiçada, ela considera você um conhecido amigável. Esse efeito termina imediatamente se você ou seus companheiros fizerem qualquer coisa prejudicial a ela."],
      [13, 'Elegant Maneuver', 'Manobra Elegante', "Starting at 13th level, you can use a bonus action on your turn to gain advantage on the next Dexterity (Acrobatics) or Strength (Athletics) check you make during the same turn.", "A partir do 13º nível, você pode usar uma ação bônus no seu turno para ganhar vantagem no próximo teste de Destreza (Acrobacia) ou Força (Atletismo) que fizer durante o mesmo turno."],
      [17, 'Master Duelist', 'Duelista Mestre', "Beginning at 17th level, your mastery of the blade lets you turn failure into success in combat. If you miss with an attack roll, you can roll it again with advantage. Once you do so, you can't use this feature again until you finish a short or long rest.", "A partir do 17º nível, sua maestria com a lâmina permite que você transforme o fracasso em sucesso em combate. Se você errar uma jogada de ataque, pode rolá-la novamente com vantagem. Depois de fazer isso, você não pode usar esta característica novamente até terminar um descanso curto ou longo."],
    ],
    inquisitive: [
      [3, 'Ear for Deceit', 'Ouvido para Mentiras', "When you choose this archetype at 3rd level, you develop a talent for picking out lies. Whenever you make a Wisdom (Insight) check to determine whether a creature is lying, treat a roll of 7 or lower on the d20 as an 8.", "Quando você escolhe este arquétipo no 3º nível, desenvolve um talento para identificar mentiras. Sempre que fizer um teste de Sabedoria (Intuição) para determinar se uma criatura está mentindo, trate uma rolagem de 7 ou menos no d20 como um 8."],
      [3, 'Eye for Detail', 'Olho para Detalhes', "Starting at 3rd level, you can use a bonus action to make a Wisdom (Perception) check to spot a hidden creature or object or to make an Intelligence (Investigation) check to uncover or decipher clues.", "A partir do 3º nível, você pode usar uma ação bônus para fazer um teste de Sabedoria (Percepção) para avistar uma criatura ou objeto escondido ou para fazer um teste de Inteligência (Investigação) para descobrir ou decifrar pistas."],
      [3, 'Insightful Fighting', 'Luta Perspicaz', "At 3rd level, you gain the ability to decipher an opponent's tactics and develop a counter to them. As a bonus action, you can make a Wisdom (Insight) check against a creature you can see that isn’t incapacitated, contested by the target’s Charisma (Deception) check. If you succeed, you can use your Sneak Attack against that target even if you don’t have advantage on the attack roll, but not if you have disadvantage on it.\n\nThis benefit lasts for 1 minute or until you successfully use this feature against a different target.", "No 3º nível, você ganha a capacidade de decifrar as táticas de um oponente e desenvolver uma resposta contra elas. Como uma ação bônus, você pode fazer um teste de Sabedoria (Intuição) contra uma criatura que você possa ver e que não esteja incapacitada, resistido pelo teste de Carisma (Enganação) do alvo. Se tiver sucesso, você pode usar seu Ataque Furtivo contra esse alvo mesmo que não tenha vantagem na jogada de ataque, mas não se tiver desvantagem nela.\n\nEsse benefício dura por 1 minuto ou até você usar esta característica com sucesso contra um alvo diferente."],
      [9, 'Steady Eye', 'Olho Firme', "Starting at 9th level, you have advantage on any Wisdom (Perception) or Intelligence (Investigation) check if you move no more than half your speed on the same turn.", "A partir do 9º nível, você tem vantagem em qualquer teste de Sabedoria (Percepção) ou Inteligência (Investigação) se não se mover mais do que a metade do seu deslocamento no mesmo turno."],
      [13, 'Unerring Eye', 'Olho Infalível', "Beginning at 13th level, your senses are almost impossible to foil. As an action, you sense the presence of illusions, shapechangers not in their original form, and other magic designed to deceive the senses within 30 feet of you, provided you aren’t blinded or deafened. You sense that an effect is attempting to trick you, but you gain no insight into what is hidden or into its true nature.\n\nYou can use this feature a number of times equal to your Wisdom modifier (minimum of once), and you regain all expended uses of it when you finish a long rest.", "A partir do 13º nível, seus sentidos são quase impossíveis de ludibriar. Como uma ação, você percebe a presença de ilusões, metamorfos que não estejam em sua forma original e outras magias projetadas para enganar os sentidos a até 9 metros de você, desde que você não esteja cego ou surdo. Você percebe que um efeito está tentando enganá-lo, mas não obtém nenhuma percepção sobre o que está escondido ou sobre sua verdadeira natureza.\n\nVocê pode usar esta característica um número de vezes igual ao seu modificador de Sabedoria (mínimo de uma vez), e recupera todos os usos gastos dela ao terminar um descanso longo."],
      [17, 'Eye for Weakness', 'Olho para Fraquezas', "At 17th level, you learn to exploit a creature’s weaknesses by carefully studying its tactics and movement. While your Insightful Fighting feature applies to a creature, your Sneak Attack damage against that creature increases by 3d6.", "No 17º nível, você aprende a explorar as fraquezas de uma criatura ao estudar cuidadosamente suas táticas e movimentos. Enquanto sua característica Luta Perspicaz se aplicar a uma criatura, o dano do seu Ataque Furtivo contra aquela criatura aumenta em 3d6."],
    ],
    scout: [
      [3, 'Skirmisher', 'Escaramuçador', "Starting at 3rd level, you are difficult to pin down during a fight. You can move up to half your speed as a reaction when an enemy ends its turn within 5 feet of you. This movement doesn’t provoke opportunity attacks.", "A partir do 3º nível, você é difícil de encurralar durante uma luta. Você pode se mover até metade do seu deslocamento como uma reação quando um inimigo termina o turno dele a até 1,5 metro de você. Esse movimento não provoca ataques de oportunidade."],
      [3, 'Survivalist', 'Sobrevivente', "When you choose this archetype at 3rd level, you gain proficiency in the Nature and Survival skills if you don’t already have it. Your proficiency bonus is doubled for any ability check you make that uses either of those proficiencies.", "Quando você escolhe este arquétipo no 3º nível, você ganha proficiência nas perícias Natureza e Sobrevivência se ainda não as tiver. Seu bônus de proficiência é dobrado em qualquer teste de habilidade que você fizer que use qualquer uma dessas proficiências."],
      [9, 'Superior Mobility', 'Mobilidade Superior', "At 9th level, your walking speed increases by 10 feet. If you have a climbing or swimming speed, this increase applies to that speed as well.", "No 9º nível, seu deslocamento de caminhada aumenta em 3 metros. Se você tiver um deslocamento de escalada ou de natação, este aumento também se aplica a esse deslocamento."],
      [13, 'Ambush Master', 'Mestre da Emboscada', "Starting at 13th level, you excel at leading ambushes and acting first in a fight.\n\nYou have advantage on initiative rolls. In addition, the first creature you hit during the first round of a combat becomes easier for you and others to strike; attack rolls against that target have advantage until the start of your next turn.", "A partir do 13º nível, você se destaca em liderar emboscadas e agir primeiro em uma luta.\n\nVocê tem vantagem em jogadas de iniciativa. Além disso, a primeira criatura que você acertar durante a primeira rodada de um combate se torna mais fácil de ser atingida por você e por outros; jogadas de ataque contra aquele alvo têm vantagem até o início do seu próximo turno."],
      [17, 'Sudden Strike', 'Golpe Súbito', "Starting at 17th level, you can strike with deadly speed. If you take the Attack action on your turn, you can make one additional attack as a bonus action. This attack can benefit from your Sneak Attack even if you have already used it this turn, but you can’t use your Sneak Attack against the same target more than once in a turn.", "A partir do 17º nível, você pode atacar com velocidade mortal. Se você realizar a ação de Ataque no seu turno, pode fazer um ataque adicional como uma ação bônus. Este ataque pode se beneficiar do seu Ataque Furtivo mesmo se você já o tiver usado neste turno, mas você não pode usar seu Ataque Furtivo contra o mesmo alvo mais de uma vez em um turno."],
    ],
    phantom: [
      [3, 'Whispers of the Dead', 'Sussurros dos Mortos', "3rd-level Phantom feature\n\nEchoes of those who have died cling to you. Whenever you finish a short or long rest, you can choose one skill or tool proficiency that you lack and gain it, as a ghostly presence shares its knowledge with you. You lose this proficiency when you use this feature to choose a different proficiency that you lack.", "Característica de Fantasma de 3º nível\n\nEcos daqueles que morreram se apegam a você. Sempre que terminar um descanso curto ou longo, você pode escolher uma proficiência em perícia ou ferramenta que não possua e ganhá-la, enquanto uma presença fantasmagórica compartilha seu conhecimento com você. Você perde essa proficiência quando usar esta característica para escolher uma proficiência diferente que não possua."],
      [3, 'Wails from the Grave', 'Lamentos do Túmulo', "3rd-level Phantom feature\n\nAs you nudge someone closer to the grave, you can channel the power of death to harm someone else as well. Immediately after you deal your Sneak Attack damage to a creature on your turn, you can target a second creature that you can see within 30 feet of the first creature. Roll half the number of Sneak Attack dice for your level (round up), and the second creature takes necrotic damage equal to the roll’s total, as wails of the dead sound around them for a moment.\n\nYou can use this feature a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.", "Característica de Fantasma de 3º nível\n\nConforme você empurra alguém para mais perto do túmulo, pode canalizar o poder da morte para ferir outra pessoa também. Imediatamente após causar o dano do seu Ataque Furtivo a uma criatura no seu turno, você pode escolher como alvo uma segunda criatura que possa ver a até 9 metros da primeira criatura. Role metade do número de dados de Ataque Furtivo para o seu nível (arredondado para cima), e a segunda criatura sofre dano necrótico igual ao total da rolagem, enquanto lamentos dos mortos ecoam ao redor dela por um instante.\n\nVocê pode usar esta característica um número de vezes igual ao seu bônus de proficiência, e recupera todos os usos gastos ao terminar um descanso longo."],
      [9, 'Tokens of the Departed', 'Lembranças dos Partidos', "9th-level Phantom feature\n\nWhen a life ends in your presence, you’re able to snatch a token from the departing soul, a sliver of its life essence that takes physical form; as a reaction when a creature you can see dies within 30 feet of you, you can open your free hand and cause a Tiny trinket to appear there, a soul trinket. The DM determines the trinket’s form or has you roll on the Trinkets table in the Player’s Handbook to generate it.\n\nYou can have a maximum number of soul trinkets equal to your proficiency bonus, and you can’t create one while at your maximum.\n\nYou can use soul trinkets in the following ways:\n\n• While a soul trinket is on your person, you have advantage on death saving throws and Constitution saving throws, for your vitality is enhanced by the life essence within the object\n\n• When you deal Sneak Attack damage on your turn, you can destroy one of your soul trinkets that’s on your person and then immediately use Wails from the Grave, without expending a use of that feature.\n\n• As an action, you can destroy one of your soul trinkets, no matter where it’s located. When you do so, you can ask the spirit associated with the trinket one question. The spirit appears to you and answers in a language it knew in life. It’s under no obligation to be truthful, and it answers as concisely as possible, eager to be free. The spirit knows only what it knew in life, as determined by the DM.", "Característica de Fantasma de 9º nível\n\nQuando uma vida termina em sua presença, você é capaz de arrancar uma lembrança da alma que parte, uma lasca de sua essência vital que assume forma física; como uma reação quando uma criatura que você possa ver morre a até 9 metros de você, você pode abrir sua mão livre e fazer um berloque Miúdo surgir nela, um berloque de alma. O Mestre determina a forma do berloque ou faz você rolar na tabela de Berloques no Livro do Jogador para gerá-lo.\n\nVocê pode ter um número máximo de berloques de alma igual ao seu bônus de proficiência, e não pode criar um enquanto estiver no seu máximo.\n\nVocê pode usar os berloques de alma das seguintes maneiras:\n\nO Mestre determina a forma do berloque ou faz você rolar na tabela de Berloques no Livro do Jogador para gerá-lo.\n\n• Enquanto um berloque de alma estiver com você, você tem vantagem em salvaguardas contra a morte e testes de resistência de Constituição, pois sua vitalidade é aprimorada pela essência vital dentro do objeto.\n\n• Quando você causa o dano de Ataque Furtivo no seu turno, você pode destruir um dos seus berloques de alma que esteja com você e, em seguida, usar imediatamente Lamentos do Túmulo, sem gastar um uso dessa característica.\n\n• Como uma ação, você pode destruir um dos seus berloques de alma, não importa onde ele esteja localizado. Ao fazer isso, você pode fazer uma pergunta ao espírito associado ao berloque. O espírito aparece para você e responde em um idioma que conhecia em vida. Ele não tem obrigação de ser honesto e responde da forma mais concisa possível, ansioso para se libertar. O espírito sabe apenas o que sabia em vida, conforme determinado pelo Mestre."],
      [13, 'Ghost Walk', 'Caminhar Fantasma', "13th-level Phantom feature\n\nYou can phase partially into the realm of the dead, becoming like a ghost. As a bonus action, you assume a spectral form. While in this form, you have a flying speed of 10 feet, you can hover, and attack rolls have disadvantage against you. You can also move through creatures and objects as if they were difficult terrain, but you take 1d10 force damage if you end your turn inside a creature or object.\n\nYou stay in this form for 10 minutes or until you end it as a bonus action. To use this feature again, you must finish a long rest or destroy one of your soul trinkets as part of the bonus action you use to activate Ghost Walk.", "Característica de Fantasma de 13º nível\n\nVocê pode passar parcialmente para o reino dos mortos, tornando-se como um fantasma. Como uma ação bônus, você assume uma forma espectral. Enquanto estiver nesta forma, você tem um deslocamento de voo de 3 metros, pode pairar, e jogadas de ataque têm desvantagem contra você. Você também pode se mover através de criaturas e objetos como se fossem terreno difícil, mas sofre 1d10 de dano de força se terminar seu turno dentro de uma criatura ou objeto.\n\nVocê permanece nesta forma por 10 minutos ou até encerrá-la com uma ação bônus. Para usar esta característica novamente, você deve terminar um descanso longo ou destruir um dos seus berloques de alma como parte da ação bônus usada para ativar o Passo Fantasmagórico."],
      [17, 'Death\'s Friend', 'Amigo da Morte', "17th-level Phantom feature\n\nYour association with death has become so close that you gain the following benefits:\n\n• When you use your Wails from the Grave, you can deal the necrotic damage to both the first and second creature.\n\n• At the end of the long rest, a soul trinket appears in your hand if you don’t have any soul trinkets, as the spirits of the dead are drawn to you.", "Característica de Fantasma de 17º nível\n\nSua associação com a morte se tornou tão próxima que você recebe os seguintes benefícios:\n\n• Quando você usa seus Lamentos do Túmulo, pode causar o dano necrótico tanto à primeira quanto à segunda criatura.\n\n• Ao final de um descanso longo, uma bugiganga de alma aparece na sua mão se você não tiver nenhuma bugiganga de alma, conforme os espíritos dos mortos são atraídos para você."],
    ],
    soulknife: [
      [3, 'Psionic Power', 'Poder Psiônico', "3rd-level Soulknife feature\n\nYou harbor a wellspring of psionic energy within yourself. This energy is represented by your Psionic Energy dice, which are each a d6. You have a number of these dice equal to twice your proficiency bonus, and they fuel various psionic powers you have, which are detailed below.\n\nSome of your powers expend the Psionic Energy die they use, as specified in a power’s description, and you can’t use a power if it requires you to use a die when your dice are all expended. You regain all your expended Psionic Energy dice when you finish a long rest. In addition, as a bonus action, you can regain one expended Psionic Energy die, but you can’t do so again until you finish a short or long rest.\n\nWhen you reach certain levels in this class, the size of your Psionic Energy dice increases: at 5th level (d8), 11th level (d10), and 17th level (d12).\n\nThe powers below use your Psionic Energy dice.\n\nPsi-Bolstered Knack. When your nonpsionic training fails you, your psionic power can help: if you fail an ability check using a skill or tool with which you have proficiency, you can roll one Psionic Energy die and add the number rolled to the check, potentially turning failure into success. You expend the die only if the roll succeeds.\n\nPsychic Whispers. You can establish telepathic communication between yourself and others—perfect for quiet infiltration. As an action, choose one or more creatures you can see, up to a number of creatures equal to your proficiency bonus, and then roll one Psionic Energy die. For a number of hours equal to the number rolled, the chosen creatures can speak telepathically with you, and you can speak telepathically with them. To send or receive a message (no action required), you and the other creature must be within 1 mile of each other. A creature can’t use this telepathy if it can’t speak any languages, and a creature can end the telepathic connection at any time (no action required). You and the creature don’t need to speak a common language to understand each other.\n\nThe first time you use this power after each long rest, you don’t expend the Psionic Energy die. All other times you use the power, you expend the die.", "Característica de Lâmina Mental de 3º nível\n\nVocê abriga uma fonte de energia psiônica dentro de si. Essa energia é representada por seus dados de Energia Psiônica, que são dados de d6 cada. Você tem um número desses dados igual ao dobro do seu bônus de proficiência, e eles abastecem vários poderes psiônicos que você possui, os quais estão detalhados abaixo.\n\nAlguns dos seus poderes gastam o dado de Energia Psiônica que utilizam, conforme especificado na descrição do poder, e você não pode usar um poder se ele exigir o uso de um dado quando todos os seus dados estiverem gastos. Você recupera todos os seus dados de Energia Psiônica gastos ao terminar um descanso longo. Além disso, como uma ação bônus, você pode recuperar um dado de Energia Psiônica gasto, mas não pode fazer isso novamente até terminar um descanso curto ou longo.\n\nQuando você atinge certos níveis nesta classe, o tamanho dos seus dados de Energia Psiônica aumenta: no 5º nível (d8), no 11º nível (d10) e no 17º nível (d12).\n\nOs poderes abaixo usam seus dados de Energia Psiônica.\n\nTalento Fortalecido por Psi. Quando seu treinamento não psiônico falha, seu poder psiônico pode ajudar: se falhar em um teste de atributo usando uma perícia ou ferramenta na qual tenha proficiência, você pode rolar um dado de Energia Psiônica e adicionar o número rolado ao teste, potencialmente transformando a falha em sucesso. Você gasta o dado apenas se o teste for bem-sucedido.\n\nSussurros Psíquicos. Você pode estabelecer comunicação telepática entre você e outros — perfeito para infiltração silenciosa. Como uma ação, escolha uma ou mais criaturas que possa ver, até um número de criaturas igual ao seu bônus de proficiência, e então role um dado de Energia Psiônica. Por um número de horas igual ao número rolado, as criaturas escolhidas podem falar telepaticamente com você, e você pode falar telepaticamente com elas. Para enviar ou receber uma mensagem (nenhuma ação necessária), você e a outra criatura devem estar a até 1,5 quilômetro uma da outra. Uma criatura não pode usar esta telepatia se não souber falar nenhum idioma, e uma criatura pode encerrar a conexão telepática a qualquer momento (nenhuma ação necessária). Você e a criatura não precisam falar um idioma comum para se entenderem.\n\nA primeira vez que você usa este poder após cada descanso longo, você não gasta o dado de Energia Psiônica. Todas as outras vezes em que usar o poder, você gasta o dado."],
      [3, 'Psychic Blades', 'Lâminas Psíquicas', "3rd-level Soulknife feature\n\nYou can manifest your psionic power as shimmering blades of psychic energy. Whenever you take the Attack action, you can manifest a psychic blade from your free hand and make the attack with that blade. This magic blade is a simple melee weapon with the finesse and thrown properties. It has a normal range of 60 feet and no long range, and on a hit, it deals psychic damage equal to 1d6 plus the ability modifier you used for the attack roll. The blade vanishes immediately after it hits or misses its target, and it leaves no mark on its target if it deals damage.\n\nAfter you attack with the blade, you can make a melee or ranged attack with a second psychic blade as a bonus action on the same turn, provided your other hand is free to create it. The damage die of this bonus attack is 1d4, instead of 1d6.", "Característica de Lâmina Mental de 3º nível\n\nVocê pode manifestar seu poder psiônico como lâminas brilhantes de energia psíquica. Sempre que você realizar a ação de Ataque, pode manifestar uma lâmina psíquica a partir da sua mão livre e fazer o ataque com essa lâmina. Esta lâmina mágica é uma arma simples corpo a corpo com as propriedades acuidade e arremesso. Ela tem um alcance normal de 18 metros e nenhum alcance longo e, em um acerto, causa dano psíquico igual a 1d6 mais o modificador de atributo que você usou para a jogada de ataque. A lâmina desaparece imediatamente após acertar ou errar o alvo, e não deixa marcas no alvo se causar dano.\n\nDepois de atacar com a lâmina, você pode fazer um ataque corpo a corpo ou à distância com uma segunda lâmina psíquica como uma ação bônus no mesmo turno, desde que sua outra mão esteja livre para criá-la. O dado de dano deste ataque bônus é 1d4, em vez de 1d6."],
      [9, 'Soul Blades', 'Lâminas da Alma', "9th-level Soulknife feature\n\nYour Psychic Blades are now an expression of your psi-suffused soul, giving you these powers that use your Psionic Energy dice:\n\nHoming Strikes. If you make an attack roll with your Psychic Blades and miss the target, you can roll one Psionic Energy die and add the number rolled to the attack roll. If this causes the attack to hit, you expend the Psionic Energy die.\n\nPsychic Teleportation. As a bonus action, you manifest one of your Psychic Blades, expend one Psionic Energy die and roll it, and throw the blade at an unoccupied space you can see, up to a number of feet away equal to 10 times the number rolled. You then teleport to that space, and the blade vanishes.", "Característica de Lâmina Mental de 9º nível\n\nSuas Lâminas Psíquicas agora são uma expressão de sua alma repleta de psi, concedendo-lhe estes poderes que usam seus dados de Energia Psiônica:\n\nAtaques Guiados. Se você fizer uma jogada de ataque com suas Lâminas Psíquicas e errar o alvo, poderá rolar um dado de Energia Psiônica e adicionar o número rolado à jogada de ataque. Se isso fizer o ataque acertar, você gasta o dado de Energia Psiônica.\n\nTeletransporte Psíquico. Como uma ação bônus, você manifesta uma de suas Lâminas Psíquicas, gasta um dado de Energia Psiônica, rola-o e arremessa a lâmina em um espaço desocupado que possa ver, a até um número de metros de distância igual a 3 vezes o número rolado. Você então se teletransporta para esse espaço, e a lâmina desaparece."],
      [13, 'Psychic Veil', 'Véu Psíquico', "13th-level Soulknife feature\n\nYou can weave a veil of psychic static to mask yourself. As an action, you can magically become invisible, along with anything you are wearing or carrying, for 1 hour or until you dismiss this effect (no action required). This invisibility ends early immediately after you deal damage to a creature or you force a creature to make a saving throw.\n\nOnce you use this feature, you can’t do so again until you finish a long rest, unless you expend a Psionic Energy die to use this feature again.", "Característica de Lâmina Mental de 13º nível\n\nVocê pode tecer um véu de estática psíquica para se ocultar. Como uma ação, você pode magicamente ficar invisível, junto com tudo o que estiver vestindo ou carregando, por 1 hora ou até dispensar este efeito (nenhuma ação necessária). Esta invisibilidade termina prematuramente imediatamente após você causar dano a uma criatura ou forçar uma criatura a fazer um teste de resistência.\n\nUma vez que você use esta característica, não poderá usá-la novamente até terminar um descanso longo, a menos que gaste um dado de Energia Psiônica para usá-la novamente."],
      [17, 'Rend Mind', 'Rasgar a Mente', "17th-level Soulknife feature\n\nYou can sweep your Psychic Blades directly through a creature’s mind. When you use your Psychic Blades to deal Sneak Attack damage to a creature, you can force that target to make a Wisdom saving throw (DC equal to 8 + your proficiency bonus + your Dexterity modifier). If the save fails, the target is stunned for 1 minute. The stunned target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.\n\nOnce you use this feature, you can’t do so again until you finish a long rest, unless you expend three Psionic Energy dice to use it again.", "Característica de Lâmina Mental de 17º nível\n\nVocê pode passar suas Lâminas Psíquicas diretamente pela mente de uma criatura. Quando você usa suas Lâminas Psíquicas para causar dano de Ataque Furtivo a uma criatura, pode forçar esse alvo a fazer um teste de resistência de Sabedoria (CD igual a 8 + seu bônus de proficiência + seu modificador de Destreza). Se falhar na salvaguarda, o alvo fica atordoado por 1 minuto. O alvo atordoado pode repetir o teste de resistência no final de cada um dos turnos dele, encerrando o efeito sobre si em caso de sucesso.\n\nUma vez que você use esta característica, não poderá usá-la novamente até terminar um descanso longo, a menos que gaste três dados de Energia Psiônica para usá-la de novo."],
    ],
  },
  sorcerer: {
    shadow: [
      [1, 'Eyes of the Dark', 'Olhos do Escuro', "Starting at 1st level, you have darkvision with a range of 120 feet. When you reach 3rd level in this class, you learn the darkness spell, which doesn’t count against your number of sorcerer spells known. In addition, you can cast it by spending 2 sorcery points or by expending a spell slot. If you cast it with sorcery points, you can see through the darkness created by the spell.", "A partir do 1º nível, você tem visão no escuro com alcance de 36 metros. Quando você alcança o 3º nível nesta classe, aprende a magia escuridão, que não conta no número de magias de feiticeiro conhecidas. Além disso, você pode conjurá-la gastando 2 pontos de feitiçaria ou gastando um espaço de magia. Se conjurá-la com pontos de feitiçaria, você pode ver através da escuridão criada pela magia."],
      [1, 'Strength of the Grave', 'Força do Túmulo', "Starting at 1st level, your existence in a twilight state between life and death makes you difficult to defeat. When damage reduces you to 0 hit points, you can make a Charisma saving throw (DC 5 + the damage taken). On a success, you instead drop to 1 hit point. You can’t use this feature if you are reduced to 0 hit points by radiant damage or by a critical hit.\n\nAfter the saving throw succeeds, you can’t use this feature again until you finish a long rest.", "A partir do 1º nível, sua existência em um estado de penumbra entre a vida e a morte torna difícil derrotá-lo. Quando o dano reduz você a 0 pontos de vida, você pode fazer uma salvaguarda de Carisma (CD 5 + o dano sofrido). Em caso de sucesso, em vez disso você cai para 1 ponto de vida. Você não pode usar esta característica se for reduzido a 0 pontos de vida por dano radiante ou por um acerto crítico.\n\nApós o sucesso na salvaguarda, você não pode usar esta característica novamente até terminar um descanso longo."],
      [6, 'Hound of Ill Omen', 'Cão do Mau Agouro', "At 6th level, you gain the ability to call forth a howling creature of darkness to harass your foes. As a bonus action, you can spend 3 sorcery points to magically summon a hound of ill omen to target one creature you can see within 120 feet of you. The hound uses the dire wolf’s statistics (see the Monster Manual or appendix C in the Player’s Handbook), with the following changes: The hound is size Medium, not Large, and it counts as a monstrosity, not a beast.\n\n• It appears with a number of temporary hit points equal to half your sorcerer level.\n\n• It can move through other creatures and objects as if they were difficult terrain. The hound takes 5 force damage if it ends its turn inside an object.\n\n• At the start of its turn, the hound automatically knows its target's location. If the target was hidden, it is no longer hidden from the hound.\n\norcerer level.\n\nThe hound appears in an unoccupied space of your choice within 30 feet of the target. Roll initiative for the hound. On its turn, it can move only toward its target by the most direct route, and it can use its action only to attack its target. The hound can make opportunity attacks, but only against its target. Additionally, while the hound is within 5 feet of the target, the target has disadvantage on saving throws against any spell you cast. The hound disappears if it is reduced to 0 hit points, if its target is reduced to 0 hit points, or after 5 minutes.", "No 6º nível, você ganha a habilidade de convocar uma criatura uivante da escuridão para atormentar seus inimigos. Como uma ação bônus, você pode gastar 3 pontos de feitiçaria para invocar magicamente um cão de mau agouro para ter como alvo uma criatura que você possa ver a até 36 metros de você. O cão usa as estatísticas do lobo atroz (consulte o Manual dos Monstros ou o apêndice C do Livro do Jogador), com as seguintes alterações: o cão é de tamanho Médio, não Grande, e conta como uma monstruosidade, não uma besta.\n\n• Ele surge com um número de pontos de vida temporários igual à metade do seu nível de feiticeiro.\n\n• Ele pode se mover através de outras criaturas e objetos como se fossem terreno difícil. O cão sofre 5 de dano de energia se terminar o turno dele dentro de um objeto.\n\n• No início do turno dele, o cão sabe automaticamente a localização do alvo dele. Se o alvo estava escondido, ele não está mais escondido do cão.\n\nnível de feiticeiro.\n\nO cão surge em um espaço desocupado à sua escolha a até 9 metros do alvo. Role iniciativa para o cão. No turno dele, ele só pode se mover em direção ao alvo pela rota mais direta, e só pode usar sua ação para atacar o alvo. O cão pode fazer ataques de oportunidade, mas apenas contra o alvo dele. Além disso, enquanto o cão estiver a até 1,5 metro do alvo, o alvo tem desvantagem em salvaguardas contra qualquer magia que você conjurar. O cão desaparece se for reduzido a 0 pontos de vida, se o alvo for reduzido a 0 pontos de vida ou após 5 minutos."],
      [14, 'Shadow Walk', 'Caminhar pelas Sombras', "At 14th level, you gain the ability to step from one shadow into another. When you are in dim light or darkness, as a bonus action, you can magically teleport up to 120 feet to an unoccupied space you can see that is also in dim light or darkness.", "No 14º nível, você ganha a habilidade de passar de uma sombra para outra. Quando você estiver na penumbra ou na escuridão, como uma ação bônus, você pode se teletransportar magicamente a até 36 metros para um espaço desocupado que você possa ver que também esteja na penumbra ou na escuridão."],
      [18, 'Umbral Form', 'Forma Umbral', "Starting at 18th level, you can spend 6 sorcery points as a bonus action to magically transform yourself into a shadowy form. In this form, you have resistance to all damage except force and radiant damage, and you can move through other creatures and objects as if they were difficult terrain. You take 5 force damage if you end your turn inside an object.\n\nYou remain in this form for 1 minute. It ends early if you are incapacitated, if you die, or if you dismiss it as a bonus action.", "A partir do 18º nível, você pode gastar 6 pontos de feitiçaria como uma ação bônus para se transformar magicamente em uma forma sombria. Nesta forma, você tem resistência a todos os danos, exceto dano de força e radiante, e pode se mover através de outras criaturas e objetos como se fossem terreno difícil. Você sofre 5 de dano de força se terminar seu turno dentro de um objeto.\n\nVocê permanece nesta forma por 1 minuto. Ela termina prematuramente se você for incapacitado, se morrer ou se a dispensar como uma ação bônus."],
    ],
    storm: [
      [1, 'Wind Speaker', 'Voz do Vento', "The arcane magic you command is infused with elemental air. You can speak, read, and write Primordial. (Knowing this language allows you to understand and be understood by those who speak its dialects: Aquan, Auran, Ignan, and Terran.)", "A magia arcana que você comanda é infundida com ar elemental. Você pode falar, ler e escrever Primordial. (Conhecer este idioma permite que você compreenda e seja compreendido por aqueles que falam seus dialetos: Aquan, Auran, Ignan e Terran.)"],
      [1, 'Tempestuous Magic', 'Magia Tempestuosa', "Starting at 1st level, you can use a bonus action on your turn to cause whirling gusts of elemental air to briefly surround you, immediately before or after you cast a spell of 1st level or higher. Doing so allows you to fly up to 10 feet without provoking opportunity attacks.", "A partir do 1º nível, você pode usar uma ação bônus no seu turno para fazer com que rajadas rodopiantes de ar elemental envolvam você brevemente, imediatamente antes ou depois de conjurar uma magia de 1º círculo ou superior. Fazer isso permite que você voe até 3 metros sem provocar ataques de oportunidade."],
      [6, 'Heart of the Storm', 'Coração da Tempestade', "At 6th level, you gain resistance to lightning and thunder damage. In addition, whenever you start casting a spell of 1st level or higher that deals lightning or thunder damage, stormy magic erupts from you. This eruption causes creatures of your choice that you can see within 10 feet of you to take lightning or thunder damage (choose each time this ability activates) equal to half your sorcerer level.", "No 6º nível, você ganha resistência a dano elétrico e trovejante. Além disso, sempre que começar a conjurar uma magia de 1º círculo ou superior que cause dano elétrico ou trovejante, uma magia tempestuosa irrompe de você. Essa erupção faz com que criaturas à sua escolha que você possa ver a até 3 metros de você sofram dano elétrico ou trovejante (escolha a cada vez que esta habilidade for ativada) igual à metade do seu nível de feiticeiro."],
      [6, 'Storm Guide', 'Guia da Tempestade', "At 6th level, you gain the ability to subtly control the weather around you.\n\nIf it is raining, you can use an action to cause the rain to stop falling in a 20-foot-radius sphere centered on you. You can end this effect as a bonus action.\n\nIf it is windy, you can use a bonus action each round to choose the direction that the wind blows in a 100-foot-radius sphere centered on you. The wind blows in that direction until the end of your next turn. This feature doesn't alter the speed of the wind.", "No 6º nível, você adquire a habilidade de controlar sutilmente o clima ao seu redor.\n\nSe estiver chovendo, você pode usar uma ação para fazer a chuva parar de cair em uma esfera de 6 metros de raio centrada em você. Você pode encerrar este efeito como uma ação bônus.\n\nSe estiver ventando, você pode usar uma ação bônus a cada rodada para escolher a direção em que o vento sopra em uma esfera de 30 metros de raio centrada em você. O vento sopra nessa direção até o final do seu próximo turno. Esta característica não altera a velocidade do vento."],
      [14, 'Storm\'s Fury', 'Fúria da Tempestade', "Starting at 14th level, when you are hit by a melee attack, you can use your reaction to deal lightning damage to the attacker. The damage equals your sorcerer level. The attacker must also make a Strength saving throw against your sorcerer spell save DC. On a failed save, the attacker is pushed in a straight line up to 20 feet away from you.", "A partir do 14º nível, quando você for atingido por um ataque corpo a corpo, você pode usar sua reação para causar dano elétrico ao atacante. O dano é igual ao seu nível de feiticeiro. O atacante também deve fazer uma salvaguarda de Força contra a CD de salvaguarda da sua magia de feiticeiro. Se falhar na salvaguarda, o atacante é empurrado em linha reta a até 6 metros de distância de você."],
      [18, 'Wind Soul', 'Alma do Vento', "At 18th level, you gain immunity to lightning and thunder damage.\n\nYou also gain a magical flying speed of 60 feet. As an action, you can reduce your flying speed to 30 feet for 1 hour and choose a number of creatures within 30 feet of you equal to 3 + your Charisma modifier. The chosen creatures gain a magical flying speed of 30 feet for 1 hour. Once you reduce your flying speed in this way, you can't do so again until you finish a short or long rest.", "No 18º nível, você ganha imunidade a dano elétrico e trovejante.\n\nVocê também ganha um deslocamento de voo mágico de 18 metros. Como uma ação, você pode reduzir seu deslocamento de voo para 9 metros por 1 hora e escolher um número de criaturas a até 9 metros de você igual a 3 + seu modificador de Carisma. As criaturas escolhidas ganham um deslocamento de voo mágico de 9 metros por 1 hora. Depois de reduzir seu deslocamento de voo dessa forma, você não pode fazê-lo novamente até terminar um descanso curto ou longo."],
    ],
    aberrantmind: [
      [1, 'Psionic Spells', 'Magias Psiônicas', "1st-level Aberrant Mind feature\n\nYou learn additional spells when you reach certain levels in this class, as shown on the Psionic Spells table. Each of these spells counts as a sorcerer spell for you, but it doesn’t count against the number of sorcerer spells you know.\n\nWhenever you gain a sorcerer level, you can replace one spell you gained from this feature with another spell of the same level. The new spell must be a divination or an enchantment spell from the sorcerer, warlock, or wizard spell list.\n\nPsionic Spells\n\nSorcerer Level | Spells\n\n1st | arms of Hadar, dissonant whispers, mind sliver\n\n3rd | calm emotions, detect thoughts\n\n5th | hunger of Hadar, sending\n\n7th | Evard’s black tentacles, summon aberration\n\n9th | Rary’s telepathic bond, telekinesis", "Característica de Mente Aberrante de 1º nível\n\nVocê aprende magias adicionais quando atinge certos níveis nesta classe, conforme mostrado na tabela Magias Psiônicas. Cada uma dessas magias conta como uma magia de feiticeiro para você, mas não conta no número de magias de feiticeiro que você conhece.\n\nSempre que você ganha um nível de feiticeiro, pode substituir uma magia que obteve desta característica por outra magia de mesmo círculo. A nova magia deve ser uma magia de adivinhação ou encantamento da lista de magias de bruxo, feiticeiro ou mago.\n\nMagias Psiônicas\n\nNível de Feiticeiro | Magias\n\n1º | braços de Hadar, sussurros dissonantes, lasca mental\n\n3º | acalmar emoções, detectar pensamentos\n\n5º | fome de Hadar, mensagem enviada\n\n7º | tentáculos negros de Evard, invocar aberração\n\n9º | vínculo telepático de Rary, telecinese"],
      [1, 'Telepathic Speech', 'Fala Telepática', "1st-level Aberrant Mind feature\n\nYou can form a telepathic connection between your mind and the mind of another. As a bonus action, choose one creature you can see within 30 feet of you. You and the chosen creature can speak telepathically with each other while the two of you are within a number of miles of each other equal to your Charisma modifier (minimum of 1 mile). To understand each other, you each must speak mentally in a language the other knows.\n\nThe telepathic connection lasts for a number of minutes equal to your sorcerer level. It ends early if you are incapacitated or die or if you use this ability to form a connection with a different creature.", "Característica de Mente Aberrante de 1º nível\n\nVocê pode formar uma conexão telepática entre a sua mente e a mente de outro. Como uma ação bônus, escolha uma criatura que você possa ver a até 9 metros de você. Você e a criatura escolhida podem falar telepaticamente um com o outro enquanto vocês dois estiverem a uma distância de até 1,5 quilômetro vezes o seu modificador de Carisma um do outro (mínimo de 1,5 quilômetro). Para compreenderem um ao outro, cada um deve falar mentalmente em um idioma que o outro conheça.\n\nA conexão telepática dura por um número de minutos igual ao seu nível de feiticeiro. Ela termina mais cedo se você estiver incapacitado ou morrer, ou se você usar esta habilidade para formar uma conexão com uma criatura diferente."],
      [6, 'Psionic Sorcery', 'Feitiçaria Psiônica', "6th-level Aberrant Mind feature\n\nWhen you cast any spell of 1st level or higher from your Psionic Spells feature, you can cast it by expending a spell slot as normal or by spending a number of sorcery points equal to the spell's level.\n\nIf you cast the spell using sorcery points, it requires no verbal or somatic components, and it requires no material components, unless they are consumed by the spell.", "Característica de Mente Aberrante de 6º nível\n\nQuando você conjura qualquer magia de 1º círculo ou superior da sua característica Magias Psiônicas, você pode conjurá-la gastando um espaço de magia como o normal ou gastando um número de pontos de feitiçaria igual ao círculo da magia.\n\nSe você conjurar a magia usando pontos de feitiçaria, ela não requer componentes verbais ou somáticos, e não requer componentes materiais, a menos que sejam consumidos pela magia."],
      [6, 'Psychic Defenses', 'Defesas Psíquicas', "6th-level Aberrant Mind feature\n\nYou gain resistance to psychic damage, and you have advantage on saving throws against being charmed or frightened.", "Característica de Mente Aberrante de 6º nível\n\nVocê ganha resistência a dano psíquico e tem vantagem em salvaguardas contra ser enfeitiçado ou amedrontado."],
      [14, 'Revelation in Flesh', 'Revelação na Carne', "14th-level Aberrant Mind feature\n\nYou can unleash the aberrant truth hidden within yourself. As a bonus action, you can spend 1 or more sorcery points to magically transform your body for 10 minutes. For each sorcery point you spend, you can gain one of the following benefits of your choice, the effects of which last until the transformation ends:\n\n• You can see any invisible creature within 60 feet of you, provided it isn’t behind total cover. Your eyes also turn black or become writhing sensory tendrils.\n\n• You gain a flying speed equal to your walking speed, and you can hover. As you fly, your skin glistens with mucus or shines with an otherworldly light.\n\n• You gain a swimming speed equal to twice your walking speed, and you can breathe underwater. Moreover, gills grow from your neck or fan out from behind your ears, your fingers become webbed, or you grow writhing cilia that extend through your clothing.\n\n• Your body, along with any equipment you are wearing or carrying, becomes slimy and pliable. You can move through any space as narrow as 1 inch without squeezing, and you can spend 5 feet of movement to escape from nonmagical restraints or being grappled.", "Característica de Mente Aberrante de 14º nível\n\nVocê pode liberar a verdade aberrante oculta dentro de si mesmo. Como uma ação bônus, você pode gastar 1 ou mais pontos de feitiçaria para transformar magicamente seu corpo por 10 minutos. Para cada ponto de feitiçaria gasto, você pode obter um dos seguintes benefícios à sua escolha, cujos efeitos duram até a transformação terminar:\n\n• Você pode ver qualquer criatura invisível a até 18 metros de você, desde que ela não esteja atrás de cobertura total. Seus olhos também ficam pretos ou se tornam tentáculos sensoriais que se contorcem.\n\n• Você ganha um deslocamento de voo igual ao seu deslocamento de caminhada e pode pairar. Enquanto voa, sua pele brilha com muco ou resplandece com uma luz sobrenatural.\n\n• Você ganha um deslocamento de natação igual ao dobro do seu deslocamento de caminhada e pode respirar debaixo d'água. Além disso, guelras crescem em seu pescoço ou se abrem atrás de suas orelhas, seus dedos se tornam palmados ou você desenvolve cílios que se contorcem e se estendem através de suas roupas.\n\n• Seu corpo, juntamente com qualquer equipamento que você esteja vestindo ou carregando, torna-se viscoso e flexível. Você pode se mover através de qualquer espaço tão estreito quanto 2,5 centímetros sem se espremer, e pode gastar 1,5 metro de movimento para escapar de amarras não mágicas ou da condição agarrado."],
      [18, 'Warping Implosion', 'Implosão Distorcida', "18th-level Aberrant Mind feature\n\nYou can unleash your aberrant power as a space-warping anomaly. As an action, you can teleport to an unoccupied space you can see within 120 feet of you. Immediately after you disappear, each creature within 30 feet of the space you left must make a Strength saving throw against your spell save DC. On a failed save, a creature takes 3d10 force damage and is pulled straight toward the space you left, ending in an unoccupied space as close to your former space as possible. On a successful save, the creature takes half as much damage and isn't pulled.\n\nOnce you use this feature, you can't do so again until you finish a long rest, unless you spend 5 sorcery points to use it again.", "Característica de 18º nível da Mente Aberrante\n\nVocê pode liberar seu poder aberrante como uma anomalia de distorção espacial. Com uma ação, você pode se teletransportar para um espaço desocupado que possa ver a até 36 metros de você. Imediatamente após você desaparecer, cada criatura a até 9 metros do espaço que você deixou deve realizar uma salvaguarda de Força contra a CD de suas magias. Se falhar na salvaguarda, a criatura sofre 3d10 de dano de energia e é puxada diretamente em direção ao espaço que você deixou, parando em um espaço desocupado o mais próximo possível do seu antigo espaço. Se obtiver sucesso na salvaguarda, a criatura sofre metade desse dano e não é puxada.\n\nDepois de usar esta característica, você não pode fazê-lo novamente até terminar um descanso longo, a menos que gaste 5 pontos de feitiçaria para usá-la de novo."],
    ],
    clockworksoul: [
      [1, 'Clockwork Magic', 'Magia Mecânica', "1st-level Clockwork Soul feature\n\nYou learn additional spells when you reach certain levels in this class, as shown on the Clockwork Spells table. Each of these spells counts as a sorcerer spell for you, but it doesn't count against the number of sorcerer spells you know.\n\nWhenever you gain a sorcerer level, you can replace one spell you gained from this feature with another spell of the same level. The new spell must be an abjuration or a transmutation spell from the sorcerer, warlock, or wizard spell list.\n\nClockwork Spells\n\nSorcerer Level | Spells\n\n1st | alarm, protection from evil and good\n\n3rd | aid, lesser restoration\n\n5th | dispel magic, protection from energy\nss=\"caption\">Clockwork Spells\n\nSorcerer Level | Spells\n\n5th | dispel magic, protection from energy\n\n7th | freedom of movement, summon construct\n\n9th | greater restoration, wall of force\n\nIn addition, consult the Manifestations of Order table and choose or randomly determine a way your connection to order manifests while you are casting any of your sorcerer spells.\n\nManifestations of Order\n\nd6 | Manifestation\n\n1 | Spectral cogwheels hover behind you\n\n2 | The hands of a clock spin in your eyes\n\n3 | Your skin glows with a brassy sheen\n\n4 | Floating equations and geometric objects overlay your body\n\n5 | Your spellcasting focus temporarily takes the form of a Tiny clockwork mechanism\n\n6 | The ticking of gears or ringing of a clock can be heard by you and those aﬀected by your magic", "Característica de Alma Mecânica de 1º nível\n\nVocê aprende magias adicionais quando atinge certos níveis nesta classe, conforme mostrado na tabela Magias Mecânicas. Cada uma dessas magias conta como uma magia de feiticeiro para você, mas não conta no número de magias de feiticeiro que você conhece.\n\nSempre que você ganha um nível de feiticeiro, pode substituir uma magia que obteve desta característica por outra magia de mesmo círculo. A nova magia deve ser uma magia de abjuração ou transmutação da lista de magias de bruxo, feiticeiro ou mago.\n\nMagias Mecânicas\n\nNível de Feiticeiro | Magias\n\n1º | alarme, proteção contra o bem e mal\n\n3º | ajuda, restauração menor\n\n5º | dissipar magia, proteção contra energia\nss=\"caption\">Magias Mecânicas\n\nNível de Feiticeiro | Magias\n\n5º | dissipar magia, proteção contra energia\n\n7º | movimentação livre, invocar constructo\n\n9º | restauração maior, muralha de força\n\nAlém disso, consulte a tabela Manifestações da Ordem e escolha ou determine aleatoriamente uma maneira como sua conexão com a ordem se manifesta enquanto você conjura qualquer uma de suas magias de feiticeiro.\n\nManifestações da Ordem\n\nd6 | Manifestação\n\n1 | Rodas dentadas espectrais pairam atrás de você\n\n2 | Os ponteiros de um relógio giram em seus olhos\n\n3 | Sua pele brilha com um reflexo de latão\n\n4 | Equações flutuantes e objetos geométricos sobrepõem-se ao seu corpo\n\n5 | Seu foco de conjuração assume temporariamente a forma de um mecanismo de engrenagens Miúdo\n\n6 | O tique-taque de engrenagens ou o soar de um relógio podem ser ouvidos por você e por aqueles afetados por sua magia"],
      [1, 'Restore Balance', 'Restaurar o Equilíbrio', "1st-level Clockwork Soul feature\n\nYour connection to the plane of absolute order allows you to equalize chaotic moments. When a creature you can see within 60 feet of you is about to roll a d20 with advantage or disadvantage, you can use your reaction to prevent the roll from being affected by advantage and disadvantage.\n\nYou can use this feature a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.", "Característica de Alma Mecânica de 1º nível\n\nSua conexão com o plano da ordem absoluta permite que você equalize momentos caóticos. Quando uma criatura que você possa ver a até 18 metros de você estiver prestes a rolar um d20 com vantagem ou desvantagem, você pode usar sua reação para impedir que a rolagem seja afetada por vantagem e desvantagem.\n\nVocê pode usar esta característica um número de vezes igual ao seu bônus de proficiência, e recupera todos os usos gastos ao terminar um descanso longo."],
      [6, 'Bastion of Law', 'Bastião da Lei', "6th-level Clockwork Soul feature\n\nYou can tap into the grand equation of existence to imbue a creature with a shimmering shield of order. As an action, you can expend 1 to 5 sorcery points to create a magical ward around yourself or another creature you can see within 30 feet of you. The ward lasts until you finish a long rest or until you use this feature again.\n\nThe ward is represented by a number of d8s equal to the number of sorcery points spent to create it. When the warded creature takes damage, it can expend a number of those dice, roll them, and reduce the damage taken by the total rolled on those dice.", "Característica de Alma Mecânica de 6º nível\n\nVocê pode acessar a grande equação da existência para imbuir uma criatura com um escudo cintilante de ordem. Como uma ação, você pode gastar de 1 a 5 pontos de feitiçaria para criar uma proteção mágica ao redor de si mesmo ou de outra criatura que você possa ver a até 9 metros de você. A proteção dura até você terminar um descanso longo ou até você usar esta característica novamente.\n\nA proteção é representada por um número de d8s igual ao número de pontos de feitiçaria gastos para criá-la. Quando a criatura protegida sofre dano, ela pode gastar um número desses dados, rolá-los e reduzir o dano sofrido pelo total rolado nesses dados."],
      [14, 'Trance of Order', 'Transe da Ordem', "14th-level Clockwork Soul feature\n\nYou gain the ability to align your consciousness to the endless calculations of Mechanus. As a bonus action, you can enter this state for 1 minute. For the duration, attack rolls against you can’t benefit from advantage, and whenever you make an attack roll, an ability check, or a saving throw, you can treat a roll of 9 or lower on the d20 as a 10.\n\nOnce you use this bonus action, you can’t use it again until you finish a long rest, unless you spend 5 sorcery points to use it again.", "Característica de Alma Mecânica de 14º nível\n\nVocê ganha a habilidade de alinhar sua consciência aos cálculos infinitos de Mecânus. Como uma ação bônus, você pode entrar nesse estado por 1 minuto. Pela duração, jogadas de ataque contra você não podem se beneficiar de vantagem e, sempre que fizer uma jogada de ataque, teste de habilidade ou salvaguarda, você pode tratar uma rolagem de 9 ou menos no d20 como um 10.\n\nDepois de usar esta ação bônus, você não pode usá-la novamente até terminar um descanso longo, a menos que gaste 5 pontos de feitiçaria para usá-la novamente."],
      [18, 'Clockwork Cavalcade', 'Cavalgada Mecânica', "18th-level Clockwork Soul feature\n\nYou summon spirits of order to expunge disorder around you. As an action, you summon the spirits in a 30-foot cube originating from you. The spirits look like modrons or other constructs of your choice. The spirits are intangible and invulnerable, and they create the following effects within the cube before vanishing:\n\n• The spirits restore up to 100 hit points, divided as you choose among any number of creatures of your choice in the cube.\n\n• Any damaged objects entirely in the cube are repaired instantly.\n\n• Every spell of 6th level or lower ends on creatures and objects of your choice in the cube.\n\nOnce you use this action, you can't use it again until you finish a long rest, unless you spend 7 sorcery points to use it again.", "Característica de Alma Mecânica de 18º nível\n\nVocê invoca espíritos da ordem para expurgar a desordem ao seu redor. Como uma ação, você invoca os espíritos em um cubo de 9 metros originado a partir de você. Os espíritos se parecem com modrons ou outros constructos à sua escolha. Os espíritos são intangíveis e invulneráveis, e criam os seguintes efeitos dentro do cubo antes de desaparecerem:\n\n• Os espíritos restauram até 100 pontos de vida, divididos conforme você escolher entre qualquer número de criaturas à sua escolha no cubo.\n\n• Quaisquer objetos danificados inteiramente dentro do cubo são reparados instantaneamente.\n\n• Toda magia de 6º círculo ou inferior termina nas criaturas e objetos à sua escolha no cubo.\n\nUma vez que você use esta ação, não poderá usá-la novamente até terminar um descanso longo, a menos que gaste 7 pontos de feitiçaria para usá-la de novo."],
    ],
    lunar: [
      [1, 'Lunar Embodiment', 'Encarnação Lunar', "1st-Level Lunar Sorcery Feature\n\nYou learn additional spells when you reach certain levels in this class, as shown on the Lunar Spells table. Each of these spells counts as a sorcerer spell for you, but it doesn’t count against the number of sorcerer spells you know.\n\nLunar Spells\n\nSorcerer Level | Full Moon Spell | New Moon Spell | Crescent Moon Spell\n\n1st | shield | ray of sickness | color spray\nrer spell for you, but it doesn’t count against the number of sorcerer spells you know.", "Característica de Feitiçaria Lunar de 1º Nível\n\nVocê aprende magias adicionais quando atinge certos níveis nesta classe, conforme mostrado na tabela Magias Lunares. Cada uma dessas magias conta como uma magia de feiticeiro para você, mas não conta no número de magias de feiticeiro que você conhece.\n\nMagias Lunares\n\nNível de Feiticeiro | Magia da Lua Cheia | Magia da Lua Nova | Magia da Lua Crescente\n\n1º | escudo arcano | raio de adoecimento | leque cromático\nmagia de feiticeiro para você, mas não conta no número de magias de feiticeiro que você conhece."],
      [1, 'Moon Fire', 'Fogo da Lua', "1st-Level Lunar Sorcery Feature\n\nYou can call down the radiant light of the moon on command. You learn the sacred flame spell, which doesn’t count against the number of sorcerer cantrips you know. When you cast the spell, you can target one creature as normal or target two creatures within range that are within 5 feet of each other.", "Característica de Feitiçaria Lunar de 1º Nível\n\nVocê pode invocar a luz radiante da lua sob comando. Você aprende a magia chama sagrada, que não conta no número de truques de feiticeiro que você conhece. Quando você conjura a magia, pode ter como alvo uma criatura normalmente ou ter como alvo duas criaturas dentro do alcance que estejam a até 1,5 metro uma da outra."],
      [6, 'Lunar Boons', 'Dádivas Lunares', "6th-Level Lunar Sorcery Feature\n\nThe current phase of your Lunar Embodiment can affect your Metamagic feature. Each Lunar Embodiment phase is associated with certain schools of magic, as shown here:\n\n• Full Moon. Abjuration and conjuration spells\n\n• New Moon. Evocation and necromancy spells\n\n• Crescent Moon. Divination and transmutation spells\n\nWhenever you use Metamagic on a spell of a school of magic associated with your current Lunar Embodiment phase, you can reduce the sorcery points spent by 1 (minimum 0). You can reduce the sorcery points spent for your Metamagic a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.", "Característica de Feitiçaria Lunar de 6º Nível\n\nA fase atual de sua Incorporação Lunar pode afetar sua característica Metamagia. Cada fase da Incorporação Lunar está associada a certas escolas de magia, conforme mostrado aqui:\n\n• Lua Cheia. Magias de abjuração e conjuração\n\n• Lua Nova. Magias de evocação e necromancia\n\n• Lua Crescente. Magias de adivinhação e transmutação\n\nSempre que usar a Metamagia em uma magia de uma escola associada à sua fase atual de Incorporação Lunar, você pode reduzir os pontos de feitiçaria gastos em 1 (mínimo de 0). Você pode reduzir os pontos de feitiçaria gastos pela sua Metamagia um número de vezes igual ao seu bônus de proficiência, e recupera todos os usos gastos ao terminar um descanso longo."],
      [6, 'Waxing and Waning', 'Crescente e Minguante', "6th-Level Lunar Sorcery Feature\n\nYou gain greater control over the phases of your lunar magic. As a bonus action, you can spend 1 sorcery point to change your current Lunar Embodiment phase for a different one.\n\nYou can now cast one 1st-level spell from each lunar phase of the Lunar Spells table once without expending a spell slot, provided your current phase is the same as the lunar phase spell. Once you cast a lunar phase spell in this way, you can't do so again until you finish a long rest.", "Característica de 6º nível da Feitiçaria Lunar\n\nVocê adquire maior controle sobre as fases de sua magia lunar. Com uma ação bônus, você pode gastar 1 ponto de feitiçaria para alterar sua fase atual de Encarnação Lunar para uma diferente.\n\nAgora você pode conjurar uma magia de 1º círculo de cada fase lunar da tabela Magias Lunares uma vez sem gastar um espaço de magia, desde que sua fase atual seja a mesma da magia da fase lunar. Uma vez que conjure uma magia de fase lunar dessa forma, não poderá fazê-lo novamente até terminar um descanso longo."],
      [14, 'Lunar Empowerment', 'Fortalecimento Lunar', "14th-Level Lunar Sorcery Feature\n\nThe power of a lunar phase saturates your being. While you are in a Lunar Embodiment phase, you also gain the following benefit associated with that phase:\n\n• Full Moon. You can use a bonus action to shed bright light in a 10-foot radius and dim light for an additional 10 feet or to douse the light. In addition, you and creatures of your choice have advantage on Intelligence (Investigation) and Wisdom (Perception) checks while within the bright light you shed.\n\n• New Moon. You have advantage on Dexterity (Stealth) checks. In addition, while you are entirely in darkness, attack rolls have disadvantage against you.\n\n• Crescent Moon. You have resistance to necrotic and radiant damage.", "Característica de Feitiçaria Lunar de 14º Nível\n\nO poder de uma fase lunar satura seu ser. Enquanto você estiver em uma fase de Manifestação Lunar, você também ganha o seguinte benefício associado àquela fase:\n\n• Lua Cheia. Você pode usar uma ação bônus para emitir luz plena em um raio de 3 metros e penumbra por mais 3 metros adicionais ou para apagar a luz. Além disso, você e criaturas à sua escolha têm vantagem em testes de Inteligência (Investigação) e Sabedoria (Percepção) enquanto estiverem dentro da luz plena emitida por você.\n\n• Lua Nova. Você tem vantagem em testes de Destreza (Furtividade). Além disso, enquanto estiver totalmente na escuridão, jogadas de ataque contra você têm desvantagem.\n\n• Quarto Crescente. Você tem resistência a dano necrótico e radiante."],
      [18, 'Lunar Phenomenon', 'Fenômeno Lunar', "18th-Level Lunar Sorcery Feature\n\nAs a bonus action, you can tap into a special power of your current Lunar Embodiment phase. Alternatively, as part of the bonus action you take to change your lunar phase using your Waxing and Waning feature, you can immediately use the power of the lunar phase you are entering:\n\n• Full Moon. You radiate moonlight for a moment. Each creature of your choice within 30 feet of you must succeed on a Constitution saving throw against your spell save DC or be blinded until the end of its next turn. In addition, one creature of your choice in that area regains 3d8 hit points.\n\n• New Moon. You momentarily emanate gloom. Each creature of your choice within 30 feet of you must succeed on a Dexterity saving throw against your spell save DC or take 3d10 necrotic damage and have its speed reduced to 0 until the end of its next turn. In addition, you become invisible until the end of your next turn, or until you make an attack or cast a spell.\n\n• Crescent Moon. You can magically teleport to an unoccupied space you can see within 60 feet of yourself. You can bring along one willing creature you can see within 5 feet of yourself. That creature teleports to an unoccupied space of your choice that you can see within 5 feet of your destination space. In addition, you and that creature gain resistance to all damage until the start of your next turn.\n\nOnce you use one of these bonus action benefits, you can’t use that benefit again until you finish a long rest, unless you spend 5 sorcery points to use it again.", "Característica de Feitiçaria Lunar de 18º Nível\n\nComo uma ação bônus, você pode acessar um poder especial da sua fase atual de Manifestação Lunar. Como alternativa, como parte da ação bônus que você realiza para mudar sua fase lunar usando sua característica Crescente e Minguante, você pode usar imediatamente o poder da fase lunar na qual está entrando:\n\n• Lua Cheia. Você irradia a luz da lua por um instante. Cada criatura à sua escolha a até 9 metros de você deve ser bem-sucedida em uma salvaguarda de Constituição contra a CD da sua magia ou ficará cega até o final do próximo turno dela. Além disso, uma criatura à sua escolha naquela área recupera 3d8 pontos de vida.\n\n• Lua Nova. Você emana penumbra momentaneamente. Cada criatura à sua escolha a até 9 metros de você deve ser bem-sucedida em uma salvaguarda de Destreza contra a CD da sua magia ou sofrerá 3d10 de dano necrótico e terá seu deslocamento reduzido a 0 até o final do próximo turno dela. Além disso, você fica invisível até o final do seu próximo turno, ou até fazer um ataque ou conjurar uma magia.\ntariamente emana penumbra. Cada criatura à sua escolha a até 9 metros de você deve ser bem-sucedida em uma salvaguarda de Destreza contra a CD da sua magia ou sofrerá 3d10 de dano necrótico e terá seu deslocamento reduzido a 0 até o final do próximo turno dela. Além disso, você fica invisível até o final do seu próximo turno, ou até fazer um ataque ou conjurar uma magia.\n\n• Quarto Crescente. Você pode se teletransportar magicamente para um espaço desocupado que você possa ver a até 18 metros de você. Você pode levar junto uma criatura voluntária que possa ver a até 1,5 metro de você. Essa criatura se teletransporta para um espaço desocupado à sua escolha que você possa ver a até 1,5 metro do seu espaço de destino. Além disso, você e essa criatura ganham resistência a todo dano até o início do seu próximo turno.\n\nDepois de usar um desses benefícios de ação bônus, você não pode usar aquele benefício novamente até terminar um descanso longo, a menos que gaste 5 pontos de feitiçaria para usá-lo novamente."],
    ],
  },
  warlock: {
    undying: [
      [1, 'Among the Dead', 'Entre os Mortos', "Starting at 1st level, you learn the spare the dying cantrip, which counts as a warlock cantrip for you. You also have advantage on saving throws against any disease.\n\nAdditionally, undead have difficulty harming you. If an undead targets you directly with an attack or a harmful spell, that creature must make a Wisdom saving throw against your spell save DC (an undead needn't make the save when it includes you in an area effect, such as the explosion of fireball). On a failed save, the creature must choose a new target or forfeit targeting someone instead of you, potentially wasting the attack or spell. On a successful save, the creature is immune to this effect for 24 hours. An undead is also immune to this effect for 24 hours if you target it with an attack or a harmful spell.", "A partir do 1º nível, você aprende o truque poupar os moribundos, que conta como um truque de bruxo para você. Você também tem vantagem em testes de resistência contra qualquer doença.\n\nAlém disso, mortos-vivos têm dificuldade em ferir você. Se um morto-vivo escolher você diretamente como alvo de um ataque ou de uma magia prejudicial, essa criatura deve fazer um teste de resistência de Sabedoria contra a CD de suas magias (um morto-vivo não precisa fazer a salvaguarda quando inclui você em uma área de efeito, como a explosão de uma bola de fogo). Se falhar na salvaguarda, a criatura deve escolher um novo alvo ou perder a oportunidade de escolher alguém como alvo em vez de você, potencialmente desperdiçando o ataque ou a magia. Em caso de sucesso na salvaguarda, a criatura fica imune a este efeito por 24 horas. Um morto-vivo também fica imune a este efeito por 24 horas se você o escolher como alvo de um ataque ou de uma magia prejudicial."],
      [6, 'Defy Death', 'Desafiar a Morte', "Starting at 6th level, you can give yourself vitality when you cheat death or when you help someone else cheat it. You can regain hit points equal to 1d8 + your Constitution modifier (minimum of 1 hit point) when you succeed on a death saving throw or when you stabilize a creature with spare the dying.\n\nOnce you use this feature, you can't use it again until you finish a long rest.", "A partir do 6º nível, você pode conceder vitalidade a si mesmo quando enganar a morte ou quando ajudar outra pessoa a enganá-la. Você pode recuperar pontos de vida iguais a 1d8 + seu modificador de Constituição (mínimo de 1 ponto de vida) quando obtiver sucesso em uma salvaguarda contra a morte ou quando estabilizar uma criatura com poupar os moribundos.\n\nDepois de usar esta característica, você não pode usá-la novamente até terminar um descanso longo."],
      [10, 'Undying Nature', 'Natureza Imortal', "Beginning at 10th level, you can hold your breath indefinitely, and you don't require food, water, or sleep, although you still require rest to reduce exhaustion and still benefit from finishing short and long rests.\n\nIn addition, you age at a slower rate. For every 10 years that pass, your body ages only 1 year, and you are immune to being magically aged.", "A partir do 10º nível, você pode prender a respiração indefinidamente e não precisa de comida, água ou sono, embora ainda precise de descanso para reduzir a exaustão e ainda receba os benefícios de terminar descansos curtos e longos.\n\nAlém disso, você envelhece em um ritmo mais lento. A cada 10 anos que passam, seu corpo envelhece apenas 1 ano, e você é imune a ser envelhecido magicamente."],
      [14, 'Indestructible Life', 'Vida Indestrutível', "When you reach 14th level, you partake of some of the true secrets of the Undying. On your turn, you can use a bonus action to regain hit points equal to 1d8 + your warlock level. Additionally, if you put a severed body part of yours back in place when you use this feature, the part reattaches.\n\nOnce you use this feature, you can't use it again until you finish a short or long rest.", "Quando você alcança o 14º nível, você compartilha de alguns dos verdadeiros segredos do Imortal. No seu turno, você pode usar uma ação bônus para recuperar pontos de vida iguais a 1d8 + seu nível de bruxo. Além disso, se você colocar uma parte amputada do seu corpo de volta no lugar ao usar esta característica, a parte se reconecta.\n\nDepois de usar esta característica, você não pode usá-la novamente até terminar um descanso curto ou longo."],
    ],
    celestial: [
      [1, 'Bonus Cantrips', 'Truques Adicionais', "At 1st level, you learn the sacred flame and light cantrips. They count as warlock cantrips for you, but they don’t count against your number of cantrips known.", "No 1º nível, você aprende os truques chama sagrada e luz. Eles contam como truques de bruxo para você, mas não contam no seu número de truques conhecidos."],
      [1, 'Healing Light', 'Luz Curativa', "At 1st level, you gain the ability to channel celestial energy to heal wounds. You have a pool of d6s that you spend to fuel this healing. The number of dice in the pool equals 1 + your warlock level.\n\nAs a bonus action, you can heal one creature you can see within 60 feet of you, spending dice from the pool. The maximum number of dice you can spend at once equals your Charisma modifier (minimum of one die). Roll the dice you spend, add them together, and restore a number of hit points equal to the total.\n\nYour pool regains all expended dice when you finish a long rest.", "No 1º nível, você ganha a capacidade de canalizar energia celestial para curar ferimentos. Você tem uma reserva de d6s que gasta para alimentar essa cura. O número de dados na reserva é igual a 1 + seu nível de bruxo.\n\nComo uma ação bônus, você pode curar uma criatura que possa ver a até 18 metros de você, gastando dados da reserva. O número máximo de dados que você pode gastar de uma só vez é igual ao seu modificador de Carisma (mínimo de um dado). Role os dados que gastar, some-os e restaure um número de pontos de vida igual ao total.\n\nSua reserva recupera todos os dados gastos ao terminar um descanso longo."],
      [6, 'Radiant Soul', 'Alma Radiante', "Starting at 6th level, your link to the Celestial allows you to serve as a conduit for radiant energy. You have resistance to radiant damage, and when you cast a spell that deals radiant or fire damage, you can add your Charisma modifier to one radiant or fire damage roll of that spell against one of its targets.", "A partir do 6º nível, seu elo com o Celestial permite que você sirva como um canalizador de energia radiante. Você tem resistência a dano radiante e, quando conjura uma magia que cause dano radiante ou de fogo, pode adicionar seu modificador de Carisma a uma rolagem de dano radiante ou de fogo dessa magia contra um de seus alvos."],
      [10, 'Celestial Resilience', 'Resiliência Celestial', "Starting at 10th level, you gain temporary hit points whenever you finish a short or long rest. These temporary hit points equal your warlock level + your Charisma modifier. Additionally, choose up to five creatures you can see at the end of the rest. Those creatures each gain temporary hit points equal to half your warlock level + your Charisma modifier.", "A partir do 10º nível, você ganha pontos de vida temporários sempre que terminar um descanso curto ou longo. Esses pontos de vida temporários são iguais ao seu nível de bruxo + seu modificador de Carisma. Além disso, escolha até cinco criaturas que possa ver ao final do descanso. Cada uma dessas criaturas ganha pontos de vida temporários iguais à metade do seu nível de bruxo + seu modificador de Carisma."],
      [14, 'Searing Vengeance', 'Vingança Ardente', "Starting at 14th level, the radiant energy you channel allows you to resist death. When you have to make a death saving throw at the start of your turn, you can instead spring back to your feet with a burst of radiant energy. You regain hit points equal to half your hit point maximum, and then you stand up if you so choose. Each creature of your choice that is within 30 feet of you takes radiant damage equal to 2d8 + your Charisma modifier, and it is blinded until the end of the current turn.\n\nOnce you use this feature, you can’t use it again until you finish a long rest.", "A partir do 14º nível, a energia radiante que você canaliza permite resistir à morte. Quando tiver que fazer um teste de resistência contra a morte no início do seu turno, você pode, em vez disso, voltar a ficar de pé em um salto com uma explosão de energia radiante. Você recupera pontos de vida iguais à metade dos seus pontos de vida máximos e então se levanta, se assim desejar. Cada criatura à sua escolha a até 9 metros de você sofre dano radiante igual a 2d8 + seu modificador de Carisma e fica cega até o final do turno atual.\n\nUma vez que você use esta característica, não poderá usá-la novamente até terminar um descanso longo."],
    ],
    fathomless: [
      [1, 'Tentacle of the Deeps', 'Tentáculo das Profundezas', "1st-level Fathomless feature\n\nYou can magically summon a spectral tentacle that strikes at your foes. As a bonus action, you create a 10-foot-long tentacle at a point you can see within 60 feet of you. The tentacle lasts for 1 minute or until you use this feature to create another tentacle.\n\nWhen you create the tentacle, you can make a melee spell attack against one creature within 10 feet of it. On a hit, the target takes 1d8 cold damage, and its speed is reduced by 10 feet until the start of your next turn. When you reach 10th level in this class, the damage increases to 2d8.\n\nAs a bonus action on your turn, you can move the tentacle up to 30 feet and repeat the attack.\n\nYou can summon the tentacle a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.", "Característica das Profundezas de 1º nível\n\nVocê pode invocar magicamente um tentáculo espectral que ataca seus inimigos. Como uma ação bônus, você cria um tentáculo de 3 metros de comprimento em um ponto que possa ver a até 18 metros de você. O tentáculo dura por 1 minuto ou até você usar esta característica para criar outro tentáculo.\n\nQuando cria o tentáculo, você pode fazer um ataque mágico corpo a corpo contra uma criatura a até 3 metros dele. Em um acerto, o alvo sofre 1d8 de dano de frio e o deslocamento dele é reduzido em 3 metros até o início do seu próximo turno. Quando você atinge o 10º nível nesta classe, o dano aumenta para 2d8.\n\nComo uma ação bônus em seu turno, você pode mover o tentáculo em até 9 metros e repetir o ataque.\n\nVocê pode invocar o tentáculo um número de vezes igual ao seu bônus de proficiência, e recupera todos os usos gastos ao terminar um descanso longo."],
      [1, 'Gift of the Sea', 'Dádiva do Mar', "1st-level Fathomless feature\n\nYou gain a swimming speed of 40 feet, and you can breathe underwater.", "Característica de Profundezas de 1º nível\n\nVocê ganha um deslocamento de natação de 12 metros e pode respirar debaixo d'água."],
      [6, 'Oceanic Soul', 'Alma Oceânica', "6th-level Fathomless feature\n\nYou are now even more at home in the depths. You gain resistance to cold damage. In addition, when you are fully submerged, any creature that is also fully submerged can understand your speech, and you can understand theirs.", "Característica de 6º nível das Profundezas\n\nVocê agora se sente ainda mais em casa nas profundezas. Você ganha resistência a dano de frio. Além disso, quando estiver totalmente submerso, qualquer criatura que também estiver totalmente submersa pode entender sua fala, e você pode entender a dela."],
      [6, 'Guardian Coil', 'Espiral Guardiã', "6th-level Fathomless feature\n\nYour Tentacle of the Deeps can defend you and others, interposing itself between them and harm. When you or a creature you can see takes damage while within 10 feet of the tentacle, you can use your reaction to choose one of those creatures and reduce the damage to that creature by 1d8. When you reach 10th level in this class, the damage reduced by the tentacle increases to 2d8.", "Característica de 6º nível das Profundezas\n\nSeu Tentáculo das Profundezas pode defender você e outros, interpondo-se entre eles e o perigo. Quando você ou uma criatura que você possa ver sofrer dano enquanto estiver a até 3 metros do tentáculo, você pode usar sua reação para escolher uma dessas criaturas e reduzir o dano a essa criatura em 1d8. Quando você atingir o 10º nível nesta classe, o dano reduzido pelo tentáculo aumenta para 2d8."],
      [10, 'Grasping Tentacles', 'Tentáculos Agarradores', "10th-level Fathomless feature\n\nYou learn the spell Evard’s black tentacles. It counts as a warlock spell for you, but it doesn’t count against the number of spells you know. You can also cast it once without a spell slot, and you regain the ability to do so when you finish a long rest.\n\nWhenever you cast this spell, your patron’s magic bolsters you, granting you a number of temporary hit points equal to your warlock level. Moreover, damage can’t break your concentration on this spell.", "Característica das Profundezas de 10º nível\n\nVocê aprende a magia tentáculos negros de Evard. Ela conta como uma magia de bruxo para você, mas não conta no número de magias que você conhece. Você também pode conjurá-la uma vez sem gastar um espaço de magia, e recupera a capacidade de fazê-lo ao terminar um descanso longo.\n\nSempre que você conjura esta magia, a magia de seu patrono o fortalece, concedendo-lhe um número de pontos de vida temporários igual ao seu nível de bruxo. Além disso, o dano não pode quebrar sua concentração nesta magia."],
      [14, 'Fathomless Plunge', 'Mergulho Insondável', "14th-level Fathomless feature\n\nYou can magically open temporary conduits to watery destinations. As an action, you can teleport yourself and up to five other willing creatures that you can see within 30 feet of you. Amid a whirl of tentacles, you all vanish and then reappear up to 1 mile away in a body of water you’ve seen (pond size or larger) or within 30 feet of it, each of you appearing in an unoccupied space within 30 feet of the others.\n\nOnce you use this feature, you can’t use it again until you finish a short or long rest.", "Característica de 14º nível das Profundezas\n\nVocê pode abrir magicamente condutos temporários para destinos aquáticos. Como uma ação, você pode se teletransportar e a até cinco outras criaturas voluntárias que você possa ver a até 9 metros de você. Em meio a um turbilhão de tentáculos, todos vocês desaparecem e reaparecem a até 1,5 quilômetro de distância em um corpo de água que você já tenha visto (do tamanho de um lago ou maior) ou a até 9 metros dele, cada um de vocês aparecendo em um espaço desocupado a até 9 metros dos outros.\n\nDepois de usar esta característica, você não pode usá-la novamente até terminar um descanso curto ou longo."],
    ],
    genie: [
      [1, 'Genie\'s Vessel', 'Recipiente do Gênio', "1st-level The Genie feature\n\nYour patron gifts you a magical vessel that grants you a measure of the genie’s power. The vessel is a Tiny object, and you can use it as a spellcasting focus for your warlock spells. You decide what the object is, or you can determine what it is randomly by rolling on the Genie’s Vessel table.\n\nGenie’s Vessel\n\nd6 | Vessel\n\n1 | Oil lamp\n\n2 | Urn\n\n3 | Ring with a compartment\n\n4 | Stoppered bottle\n\n5 | Hollow statuette\n\n6 | Ornate lantern\n\nWhile you are touching the vessel, you can use it in the following ways:\n\nBottled Respite. As an action, you can magically vanish and enter your vessel, which remains in the space you left. The interior of the vessel is an extradimensional space in the shape of a 20-foot radius cylinder, 20 feet high, and resembles your vessel. The interior is comfortably appointed with cushions and low tables and is a comfortable temperature. While inside, you can hear the area around your vessel as if you were in its space. You can remain inside the vessel up to a number of hours equal to twice your proficiency bonus. You exit the vessel early if you use a bonus action to leave, if you die, or if the vessel is destroyed. When you exit the vessel, you appear in the unoccupied space closest to it. Any objects left in the vessel remain there until carried out, and if the vessel is destroyed, every object stored there harmlessly appears in the unoccupied spaces closest to the vessel’s former space. Once you enter the vessel, you can’t enter again until you finish a long rest.\n\nGenie’s Wrath. Once during each of your turns when you hit with an attack roll, you can deal extra damage to the target equal to your proficiency bonus. The type of this damage is determined by your patron: bludgeoning (dao), thunder (djinni), fire (efreeti), or cold (marid).\n\nThe vessel’s AC equals your spell save DC. Its hit points equal your warlock level plus your proficiency bonus, and it is immune to poison and psychic damage.\n\nIf the vessel is destroyed or you lose it, you can perform a 1-hour ceremony to receive a replacement from your patron. This ceremony can be performed during a short or long rest, and the previous vessel is destroyed if it still exists. The vessel vanishes in a flare of elemental power when you die.", "Característica de O Gênio de 1º nível\n\nSeu patrono presenteia você com um receptáculo mágico que lhe concede uma parcela do poder do gênio. O receptáculo é um objeto Miúdo, e você pode usá-lo como um foco de conjuração para suas magias de bruxo. Você decide o que é o objeto, ou pode determinar o que ele é aleatoriamente rolando na tabela Receptáculo do Gênio.\n\nReceptáculo do Gênio\n\nd6 | Receptáculo\n\n1 | Lâmpada de óleo\n\n2 | Urna\n\n3 | Anel com compartimento\n\n4 | Garrafa com rolha\n\n5 | Estatueta oca\n\n6 | Lanterna ornamentada\n\nEnquanto estiver tocando o receptáculo, você pode usá-lo das seguintes maneiras:\n\nRefúgio Engarrafado. Como uma ação, você pode desaparecer magicamente e entrar no seu receptáculo, que permanece no espaço que você deixou. O interior do receptáculo é um espaço extradimensional na forma de um cilindro de 6 metros de raio e 6 metros de altura, e assemelha-se ao seu receptáculo. O interior é confortavelmente decorado com almofadas e mesas baixas, mantendo uma temperatura agradável. Enquanto estiver lá dentro, você pode ouvir a área ao redor do seu receptáculo como se estivesse no espaço dele. Você pode permanecer dentro do receptáculo por até um número de horas igual ao dobro do seu bônus de proficiência. Você sai do receptáculo mais cedo se usar uma ação bônus para sair, se morrer ou se o receptáculo for destruído. Quando sai do receptáculo, você aparece no espaço desocupado mais próximo dele. Quaisquer objetos deixados no receptáculo permanecem lá até serem retirados e, se o receptáculo for destruído, todos os objetos armazenados nele surgem ilesos nos espaços desocupados mais próximos do espaço anterior do receptáculo. Depois de entrar no receptáculo, você não pode entrar novamente até terminar um descanso longo.\n\nIra do Gênio. Uma vez durante cada um dos seus turnos, quando acertar uma jogada de ataque, você pode causar dano extra ao alvo igual ao seu bônus de proficiência. O tipo desse dano é determinado pelo seu patrono: contundente (dao), trovejante (djinni), fogo (efreeti) ou frio (marid).\n\nA CA do receptáculo é igual à CD de suas magias. Seus pontos de vida são iguais ao seu nível de bruxo mais o seu bônus de proficiência, e ele é imune a dano de veneno e psíquico.\n\nSe o receptáculo for destruído ou você o perder, poderá realizar uma cerimônia de 1 hora para receber um substituto do seu patrono. Esta cerimônia pode ser realizada durante um descanso curto ou longo, e o receptáculo anterior é destruído se ainda existir. O receptáculo desaparece em uma labareda de poder elemental quando você morre."],
      [6, 'Elemental Gift', 'Dádiva Elemental', "You begin to take on characteristics of your patron’s kind. You now have resistance to a damage type determined by your patron’s kind: bludgeoning (dao), thunder (djinni), fire (efreeti), or cold (marid).\n\nIn addition, as a bonus action, you can give yourself a flying speed of 30 feet that lasts for 10 minutes, during which you can hover. You can use this bonus action a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.", "Você começa a assumir características do tipo do seu patrono. Agora você tem resistência a um tipo de dano determinado pelo tipo do seu patrono: contundente (dao), trovejante (djinni), fogo (efreeti) ou frio (marid).\n\nAlém disso, com uma ação bônus, você pode conceder a si mesmo um deslocamento de voo de 9 metros que dura por 10 minutos, durante o qual você pode planar. Você pode usar esta ação bônus um número de vezes igual ao seu bônus de proficiência e recupera todos os usos gastos ao terminar um descanso longo."],
      [10, 'Sanctuary Vessel', 'Recipiente Santuário', "10th-level The Genie feature\n\nWhen you enter your Genie’s Vessel via the Bottle Respite feature, you can now choose up to five willing creatures that you can see within 30 feet of you, and the chosen creatures are drawn into the vessel with you.\n\nAs a bonus action, you can eject any number of creatures from the vessel, and everyone is ejected if you leave or the vessel is destroyed.\n\nIn addition, anyone (including you) who remains in the vessel for at least 10 minutes gains the benefit of finishing a short rest, and anyone can add your proficiency bonus to the number of hit points they regain if they spend any Hit Dice as part of a short rest there.", "Característica de O Gênio de 10º nível\n\nQuando você entra no seu Receptáculo do Gênio por meio da característica Refúgio Engarrafado, agora pode escolher até cinco criaturas voluntárias que possa ver a até 9 metros de você, e as criaturas escolhidas são puxadas para dentro do receptáculo com você.\n\nComo uma ação bônus, você pode ejetar qualquer número de criaturas do receptáculo, e todos são ejetados se você sair ou se o receptáculo for destruído.\n\nAlém disso, qualquer pessoa (incluindo você) que permaneça no receptáculo por pelo menos 10 minutos recebe os benefícios de terminar um descanso curto, e qualquer pessoa pode adicionar seu bônus de proficiência ao número de pontos de vida que recupera se gastar quaisquer Dados de Vida como parte de um descanso curto ali."],
      [14, 'Limited Wish', 'Desejo Limitado', "14th-level The Genie feature\n\nYou entreat your patron to grant you a small wish. As an action, you can speak your desire to your Genie’s Vessel, requesting the effect of one spell that is 6th level or lower and has a casting time of 1 action. The spell can be from any class’s spell list, and you don’t need to meet the requirements in that spell, including costly components; the spell simply takes effect as part of this action.\n\nOnce you use this feature, you can’t use it again until you finish 1d4 long rests.", "Característica de 14º nível do Gênio\n\nVocê suplica ao seu patrono para lhe conceder um pequeno desejo. Com uma ação, você pode expressar seu desejo ao seu Receptáculo do Gênio, solicitando o efeito de uma magia de 6º círculo ou inferior que tenha um tempo de conjuração de 1 ação. A magia pode ser da lista de magias de qualquer classe, e você não precisa atender aos requisitos dessa magia, incluindo componentes caros; a magia simplesmente entra em vigor como parte desta ação.\n\nDepois de usar esta característica, você não pode usá-la novamente até terminar 1d4 descansos longos."],
    ],
    undead: [
      [1, 'Form of Dread', 'Forma do Pavor', "1st-level Undead feature\n\nYou manifest an aspect of your patron’s dreadful power. As a bonus action, you transform for 1 minute. You gain the following benefits while transformed:\n\n• You gain temporary hit points equal to 1d10 + your warlock level.\n\n• Once during each of your turns, when you hit a creature with an attack roll, you can force it to make a Wisdom saving throw, and if the saving throw fails, the target is frightened of you until the end of your next turn.\n\n• You are immune to the frightened condition.\n\nYou can transform a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.\n\nThe appearance of your Form of Dread reflects some aspect of your patron. For example, your form could be a shroud of shadows forming the crown and robes of your lich patron, or your body might glow with glyphs from ancient funerary rites and be surrounded by desert winds, suggesting your mummy patron.", "Característica de O Morto-Vivo de 1º nível\n\nVocê manifesta um aspecto do poder terrível do seu patrono. Como uma ação bônus, você se transforma por 1 minuto. Você recebe os seguintes benefícios enquanto transformado:\n\n• Você ganha pontos de vida temporários iguais a 1d10 + seu nível de bruxo.\n\n• Uma vez durante cada um dos seus turnos, quando acertar uma criatura com uma jogada de ataque, você pode forçá-la a fazer um teste de resistência de Sabedoria e, se falhar na salvaguarda, o alvo fica amedrontado por você até o final do seu próximo turno.\n\n• Você é imune à condição amedrontado.\n\nVocê pode se transformar um número de vezes igual ao seu bônus de proficiência, e recupera todos os usos gastos ao terminar um descanso longo.\n\nA aparência de sua Forma Pavorosa reflete algum aspecto do seu patrono. Por exemplo, sua forma pode ser uma mortalha de sombras formando a coroa e os mantos do seu patrono lich, ou seu corpo pode brilhar com glifos de ritos funerários antigos e ser cercado por ventos do deserto, sugerindo seu patrono múmia."],
      [6, 'Grave Touched', 'Tocado pelo Túmulo', "6th-level Undead feature\n\nYour patron’s powers have a profound effect on your body and magic. You don’t need to eat, drink, or breathe.\n\nIn addition, once during each of your turns, when you hit a creature with an attack roll and roll damage against the creature, you can replace the damage type with necrotic damage. While you are using your Form of Dread, you can roll one additional damage die when determining the necrotic damage the target takes.", "Característica de 6º nível do Insepulto\n\nOs poderes do seu patrono têm um efeito profundo em seu corpo e em sua magia. Você não precisa comer, beber ou respirar.\n\nAlém disso, uma vez durante cada um dos seus turnos, quando acertar uma criatura com uma jogada de ataque e rolar dano contra ela, você pode substituir o tipo de dano por dano necrótico. Enquanto estiver usando sua Forma de Pavor, você pode rolar um dado de dano adicional ao determinar o dano necrótico que o alvo sofre."],
      [10, 'Necrotic Husk', 'Casca Necrótica', "10th-level Undead feature\n\nYour connection to undeath and necrotic energy now saturates your body. You have resistance to necrotic damage. If you are transformed using your Form of Dread, you instead become immune to necrotic damage.\n\nIn addition, when you would be reduced to 0 hit points, you can use your reaction to drop to 1 hit point instead and cause your body to erupt with deathly energy. Each creature of your choice that is within 30 feet of you takes necrotic damage equal to 2d10 + your warlock level. You then gain 1 level of exhaustion. Once you use this reaction, you can’t do so again until you finish 1d4 long rests.", "Característica de O Morto-Vivo de 10º nível\n\nSua conexão com a morte-vida e a energia necrótica agora satura seu corpo. Você tem resistência a dano necrótico. Se estiver transformado usando sua Forma Pavorosa, em vez disso você se torna imune a dano necrótico.\n\nAlém disso, quando for reduzido a 0 pontos de vida, você pode usar sua reação para ficar com 1 ponto de vida em vez disso e fazer com que seu corpo irrompa em energia mortal. Cada criatura à sua escolha a até 9 metros de você sofre dano necrótico igual a 2d10 + seu nível de bruxo. Você então ganha 1 nível de exaustão. Uma vez que você use esta reação, não poderá fazê-lo novamente até terminar 1d4 descansos longos."],
      [14, 'Spirit Projection', 'Projeção Espiritual', "14th-level Undead feature\n\nYour spirit can become untethered from your physical form. As an action, you can project your spirit from your body. The body you leave behind is unconscious and in a state of suspended animation.\n\nYour spirit resembles your mortal form in almost every way, replicating your game statistics but not your possessions. Any damage or other effects that apply to your spirit or physical body affects the other. Your spirit can remain outside your body for up to 1 hour or until your concentration is broken (as if concentrating on a spell). When your projection ends, your spirit returns to your body or your body magically teleports to your spirit’s space (your choice).\n\nWhile projecting your spirit, you gain the following benefits:\n\n• Your spirit and body gain resistance to bludgeoning, piercing, and slashing damage.\n\n• When you cast a spell of the conjuration or necromancy school, the spell doesn’t require verbal or somatic components or material components that lack a gold cost.\n\n• You have a flying speed equal to your walking speed and can hover. You can move through creatures and objects as if they were difficult terrain, but you take 1d10 force damage if you end your turn inside a creature or an object.\n\n• While you are using your Form of Dread, once during each of your turns when you deal necrotic damage to a creature, you regain hit points equal to half the amount of necrotic damage dealt.\n\nOnce you use this feature, you can’t do so again until you finish a long rest.", "Característica de O Morto-Vivo de 14º nível\n\nSeu espírito pode se desvincular de sua forma física. Como uma ação, você pode projetar seu espírito a partir do seu corpo. O corpo que você deixa para trás fica inconsciente e em um estado de animação suspensa.\n\nCaracterística de O Morto-Vivo de 14º nível\n\nSeu espírito pode se desvincular de sua forma física. Como uma ação, você pode projetar seu espírito a partir do seu corpo. O corpo que você deixa para trás fica inconsciente e em um estado de animação suspensa.\n\nSeu espírito se assemelha à sua forma mortal em quase todos os aspectos, replicando suas estatísticas de jogo, mas não suas posses. Qualquer dano ou outros efeitos que se apliquem ao seu espírito ou corpo físico afetam o outro. Seu espírito pode permanecer fora do seu corpo por até 1 hora ou até que sua concentração seja quebrada (como se estivesse se concentrando em uma magia). Quando sua projeção termina, seu espírito retorna ao seu corpo ou seu corpo se teletransporta magicamente para o espaço do seu espírito (à sua escolha).\n\nEnquanto projeta seu espírito, você recebe os seguintes benefícios:\n\n• Seu espírito e corpo ganham resistência a dano contundente, perfurante e cortante.\n\n• Quando você conjura uma magia da escola de conjuração ou necromancia, a magia não requer componentes verbais ou somáticos, nem componentes materiais que não possuam um custo em ouro.\n\n• Você tem um deslocamento de voo igual ao seu deslocamento de caminhada e pode pairar. Você pode se mover através de criaturas e objetos como se fossem terreno difícil, mas sofre 1d10 de dano de força se terminar seu turno dentro de uma criatura ou objeto.\n\n• Enquanto estiver usando sua Forma Pavorosa, uma vez durante cada um dos seus turnos, ao causar dano necrótico a uma criatura, você recupera pontos de vida iguais à metade da quantidade de dano necrótico causado."],
    ],
  },
  wizard: {
    conjuration: [
      [2, 'Conjuration Savant', 'Sábio da Conjuração', "Beginning when you select this school at 2nd level, the gold and time you must spend to copy a conjuration spell into your spellbook is halved.", "A partir do momento em que escolhe esta escola no 2º nível, o ouro e o tempo que você deve gastar para copiar uma magia de conjuração para o seu grimório são reduzidos pela metade."],
      [2, 'Minor Conjuration', 'Conjuração Menor', "Starting at 2nd level when you select this school, you can use your action to conjure up an inanimate object in your hand or on the ground in an unoccupied space that you can see within 10 feet of you. This object can be no larger than 3 feet on a side and weigh no more than 10 pounds, and its form must be that of a nonmagical object that you have seen. The object is visibly magical, radiating dim light out to 5 feet.\n\nThe object disappears after 1 hour, when you use this feature again, or if it takes or deals any damage.", "A partir do 2º nível, quando você escolhe esta escola, você pode usar sua ação para conjurar um objeto inanimado em sua mão ou no chão em um espaço desocupado que você possa ver a até 3 metros de você. Este objeto não pode ter mais do que 90 centímetros de lado e não pode pesar mais de 4,5 kg, e sua forma deve ser a de um objeto não mágico que você já tenha visto. O objeto é visivelmente mágico, irradiando luz penumbrosa a até 1,5 metro.\n\nO objeto desaparece após 1 hora, quando você usa esta característica novamente, ou se sofrer ou causar qualquer dano."],
      [6, 'Benign Transposition', 'Transposição Benigna', "Starting at 6th level, you can use your action to teleport up to 30 feet to an unoccupied space that you can see. Alternatively, you can choose a space within range that is occupied by a Small or Medium creature. If that creature is willing, you both teleport, swapping places.\n\nOnce you use this feature, you can’t use it again until you finish a long rest or you cast a conjuration spell of 1st level or higher.", "A partir do 6º nível, você pode usar sua ação para se teletransportar a até 9 metros para um espaço desocupado que você possa ver. Como alternativa, você pode escolher um espaço dentro do alcance que esteja ocupado por uma criatura Pequena ou Média. Se essa criatura for voluntária, ambos se teletransportam, trocando de lugar.\n\nDepois de usar esta característica, você não pode usá-la novamente até terminar um descanso longo ou conjurar uma magia de conjuração de 1º círculo ou superior."],
      [10, 'Focused Conjuration', 'Conjuração Focada', "Beginning at 10th level, while you are concentrating on a conjuration spell, your concentration can’t be broken as a result of taking damage.", "A partir do 10º nível, enquanto estiver se concentrando em uma magia de conjuração, sua concentração não pode ser interrompida em decorrência de sofrer dano."],
      [14, 'Durable Summons', 'Invocações Duráveis', "Starting at 14th level, any creature that you summon or create with a conjuration spell has 30 temporary hit points.", "A partir do 14º nível, qualquer criatura que você invocar ou criar com uma magia de conjuração ganha 30 pontos de vida temporários."],
    ],
    enchantment: [
      [2, 'Enchantment Savant', 'Sábio do Encantamento', "Beginning when you select this school at 2nd level, the gold and time you must spend to copy an enchantment spell into your spellbook is halved.", "A partir do momento em que escolhe esta escola no 2º nível, o ouro e o tempo que você deve gastar para copiar uma magia de encantamento para o seu grimório são reduzidos pela metade."],
      [2, 'Hypnotic Gaze', 'Olhar Hipnótico', "Starting at 2nd level when you choose this school, your soft words and enchanting gaze can magically enthrall another creature. As an action, choose one creature that you can see within 5 feet of you. If the target can see or hear you, it must succeed on a Wisdom saving throw against your wizard spell save DC or be charmed by you until the end of your next turn. The charmed creature’s speed drops to 0, and the creature is incapacitated and visibly dazed.\n\nOn subsequent turns, you can use your action to maintain this effect, extending its duration until the end of your next turn. However, the effect ends if you move more than 5 feet away from the creature, if the creature can neither see nor hear you, or if the creature takes damage.\n\nOnce the effect ends, or if the creature succeeds on its initial saving throw against this effect, you can’t use this feature on that creature again until you finish a long rest.", "A partir do 2º nível, quando você escolhe esta escola, suas palavras suaves e olhar encantador podem fascinar magicamente outra criatura. Com uma ação, escolha uma criatura que você possa ver a até 1,5 metro de você. Se o alvo puder vê-lo ou ouvi-lo, ele deve ser bem-sucedido em uma salvaguarda de Sabedoria contra a CD das suas magias de mago ou ficará enfeitiçado por você até o final do seu próximo turno. O deslocamento da criatura enfeitiçada cai para 0, e a criatura fica incapacitada e visivelmente atordoada.\n\nNos turnos subsequentes, você pode usar sua ação para manter este efeito, estendendo sua duração até o final do seu próximo turno. No entanto, o efeito termina se você se mover para mais de 1,5 metro de distância da criatura, se a criatura não puder ver nem ouvir você, ou se a criatura sofrer dano.\n\nQuando o efeito terminar, ou se a criatura obtiver sucesso em sua salvaguarda inicial contra este efeito, você não poderá usar esta característica nessa criatura novamente até terminar um descanso longo."],
      [6, 'Instinctive Charm', 'Encanto Instintivo', "Beginning at 6th level, when a creature you can see within 30 feet of you makes an attack roll against you, you can use your reaction to divert the attack, provided that another creature is within the attack’s range. The attacker must make a Wisdom saving throw against your wizard spell save DC. On a failed save, the attacker must target the creature that is closest to it, not including you or itself. If multiple creatures are closest, the attacker chooses which one to target. On a successful save, you can’t use this feature on the attacker again until you finish a long rest.\n\nYou must choose to use this feature before knowing whether the attack hits or misses. Creatures that can’t be charmed are immune to this effect.", "A partir do 6º nível, quando uma criatura que você possa ver a até 9 metros de você fizer uma jogada de ataque contra você, você pode usar sua reação para desviar o ataque, desde que outra criatura esteja dentro do alcance do ataque. O atacante deve fazer uma salvaguarda de Sabedoria contra a CD de suas magias de mago. Se falhar na salvaguarda, o atacante deve alvejar a criatura que estiver mais próxima dele, não incluindo você nem a si mesmo. Se várias criaturas estiverem igualmente próximas, o atacante escolhe qual alvejar. Se obtiver sucesso na salvaguarda, você não pode usar esta característica no atacante novamente até terminar um descanso longo.\n\nVocê deve escolher usar esta característica antes de saber se o ataque acerta ou erra. Criaturas que não podem ser enfeitiçadas são imunes a este efeito."],
      [10, 'Split Enchantment', 'Encantamento Dividido', "Starting at 10th level, when you cast an enchantment spell of 1st level or higher that targets only one creature, you can have it target a second creature.", "A partir do 10º nível, quando você conjura uma magia de encantamento de 1º círculo ou superior que tenha apenas uma criatura como alvo, você pode fazer com que ela tenha uma segunda criatura como alvo."],
      [14, 'Alter Memories', 'Alterar Memórias', "At 14th level, you gain the ability to make a creature unaware of your magical influence on it. When you cast an enchantment spell to charm one or more creatures, you can alter one creature’s understanding so that it remains unaware of being charmed.\n\nAdditionally, once before the spell expires, you can use your action to try to make the chosen creature forget some of the time it spent charmed. The creature must succeed on an Intelligence saving throw against your wizard spell save DC or lose a number of hours of its memories equal to 1 + your Charisma modifier (minimum 1). You can make the creature forget less time, and the amount of time can’t exceed the duration of your enchantment spell.", "No 14º nível, você ganha a capacidade de fazer com que uma criatura não perceba sua influência mágica sobre ela. Quando você conjura uma magia de encantamento para enfeitiçar uma ou mais criaturas, pode alterar a percepção de uma criatura para que ela permaneça sem saber que foi enfeitiçada.\n\nAlém disso, uma vez antes de a magia expirar, você pode usar sua ação para tentar fazer a criatura escolhida esquecer parte do tempo que passou enfeitiçada. A criatura deve ser bem-sucedida em um teste de resistência de Inteligência contra a CD de suas magias de mago ou perderá um número de horas de suas memórias igual a 1 + seu modificador de Carisma (mínimo de 1). Você pode fazer a criatura esquecer menos tempo, e a quantidade de tempo não pode exceder a duração da sua magia de encantamento."],
    ],
    bladesinging: [
      [2, 'Training in War and Song', 'Treino de Guerra e Canção', "When you adopt this tradition at 2nd level, you gain proficiency with light armor, and you gain proficiency with one type of one-handed melee weapon of your choice.\n\nYou also gain proficiency in the Performance skill if you don’t already have it.", "Quando você adota esta tradição no 2º nível, ganha proficiência com armaduras leves e ganha proficiência com um tipo de arma corpo a corpo de uma mão à sua escolha.\n\nVocê também ganha proficiência na perícia Atuação se ainda não a tiver."],
      [2, 'Bladesong', 'Canção da Lâmina', "Starting at 2nd level, you can invoke a secret elven magic called the Bladesong, provided that you aren’t wearing medium or heavy armor or using a shield. It graces you with supernatural speed, agility, and focus.\n\nYou can use a bonus action to start the Bladesong, which lasts for 1 minute. It ends early if you are incapacitated, if you don medium or heavy armor or a shield, or if you use two hands to make an attack with a weapon. You can also dismiss the Bladesong at any time you choose (no action required).\n\nWhile your Bladesong is active, you gain the following benefits:\n\n• You gain a bonus to your AC equal to your Intelligence modifier (minimum of +1).\n\n• Your walking speed increases by 10 feet.\n\n• You have advantage on Dexterity (Acrobatics) checks .\n\n• You gain a bonus to any Constitution saving throw you make to maintain your concentration on a spell. The bonus equals your Intelligence modifier (minimum of +l).\n\nYou can use this feature a number of times equal to your proficiency bonus, and you regain all expended uses of it when you finish a long rest.", "A partir do 2º nível, você pode invocar uma magia élfica secreta chamada Canção da Lâmina, desde que não esteja vestindo armadura média ou pesada nem usando um escudo. Ela agracia você com velocidade, agilidade e foco sobrenaturais.\n\nVocê pode usar uma ação bônus para iniciar a Canção da Lâmina, que dura 1 minuto. Ela termina mais cedo se você ficar incapacitado, se vestir armadura média ou pesada ou um escudo, ou se usar as duas mãos para fazer um ataque com uma arma. Você também pode encerrar a Canção da Lâmina a qualquer momento à sua escolha (nenhuma ação necessária).\n\nEnquanto sua Canção da Lâmina estiver ativa, você ganha os seguintes benefícios:\n\n• Você ganha um bônus na sua CA igual ao seu modificador de Inteligência (mínimo de +1).\n\n• Seu deslocamento de caminhada aumenta em 3 metros.\n\n• Você tem vantagem em testes de Destreza (Acrobacia).\n\n• Você ganha um bônus em qualquer salvaguarda de Constituição feita para manter sua concentração em uma magia. O bônus é igual ao seu modificador de Inteligência (mínimo de +1).\n\nVocê pode usar esta característica um número de vezes igual ao seu bônus de proficiência, e recupera todos os usos gastos ao terminar um descanso longo."],
      [6, 'Extra Attack', 'Ataque Extra', "6th-level Bladesinging feature\n\nYou can attack twice, instead of once, whenever you take the Attack action on your turn. Moreover, you can cast one of your cantrips in place of one of those attacks.", "Característica de 6º nível do Dançarino da Lâmina\n\nVocê pode atacar duas vezes, em vez de uma, sempre que realizar a ação Atacar em seu turno. Além disso, você pode conjurar um de seus truques no lugar de um desses ataques."],
      [10, 'Song of Defense', 'Canção da Defesa', "10th-level Bladesinging feature\n\nYou can direct your magic to absorb damage while your Bladesong is active. When you take damage, you can use your reaction to expend one spell slot and reduce that damage to you by an amount equal to five times the spell slot's level.", "Característica de 10º nível do Dançarino da Lâmina\n\nVocê pode direcionar sua magia para absorver dano enquanto sua Canção da Lâmina estiver ativa. Quando você sofrer dano, pode usar sua reação para gastar um espaço de magia e reduzir esse dano a você em uma quantidade igual a cinco vezes o círculo do espaço de magia."],
      [14, 'Song of Victory', 'Canção da Vitória', "14th-level Bladesinging feature\n\nYou can add your Intelligence modifier (minimum of +1) to the damage of your melee weapon attacks while your Bladesong is active.", "Característica de 14º nível do Dançarino da Lâmina\n\nVocê pode adicionar seu modificador de Inteligência (mínimo de +1) ao dano dos seus ataques corpo a corpo com arma enquanto sua Canção da Lâmina estiver ativa."],
    ],
    warmagic: [
      [2, 'Arcane Deflection', 'Deflexão Arcana', "At 2nd level, you have learned to weave your magic to fortify yourself against harm. When you are hit by an attack or you fail a saving throw, you can use your reaction to gain a +2 bonus to your AC against that attack or a +4 bonus to that saving throw.\n\nWhen you use this feature, you can’t cast spells other than cantrips until the end of your next turn.", "No 2º nível, você aprendeu a tecer sua magia para se proteger contra ferimentos. Quando for atingido por um ataque ou falhar em uma salvaguarda, você pode usar sua reação para ganhar um bônus de +2 na sua CA contra aquele ataque ou um bônus de +4 naquela salvaguarda.\n\nAo usar esta característica, você não pode conjurar magias que não sejam truques até o final do seu próximo turno."],
      [2, 'Tactical Wit', 'Astúcia Tática', "Starting at 2nd level, your keen ability to assess tactical situations allows you to act quickly in battle. You can give yourself a bonus to your initiative rolls equal to your Intelligence modifier.", "A partir do 2º nível, sua habilidade aguçada de avaliar situações táticas permite que você aja rapidamente em batalha. Você pode conceder a si mesmo um bônus em suas jogadas de iniciativa igual ao seu modificador de Inteligência."],
      [6, 'Power Surge', 'Surto de Poder', "Starting at 6th level, you can store magical energy within yourself to later empower your damaging spells. In its stored form, this energy is called a power surge.\n\nYou can store a maximum number of power surges equal to your Intelligence modifier (minimum of one). Whenever you finish a long rest, your number of power surges resets to one. Whenever you successfully end a spell with dispel magic or counterspell, you gain one power surge, as you steal magic from the spell you foiled. If you end a short rest with no power surges, you gain one power surge.\n\nOnce per turn when you deal damage to a creature or object with a wizard spell, you can spend one power surge to deal extra force damage to that target. The extra damage equals half your wizard level.", "A partir do 6º nível, você pode armazenar energia mágica dentro de si para posteriormente potencializar suas magias que causam dano. Em sua forma armazenada, essa energia é chamada de surto de poder.\n\nVocê pode armazenar um número máximo de surtos de poder igual ao seu modificador de Inteligência (mínimo de um). Sempre que terminar um descanso longo, seu número de surtos de poder é redefinido para um. Sempre que encerrar uma magia com sucesso usando dissipar magia ou contramagia, você ganha um surto de poder, ao roubar a magia da magia que frustrou. Se terminar um descanso curto sem nenhum surto de poder, você ganha um surto de poder.\n\nUma vez por turno, quando você causa dano a uma criatura ou objeto com uma magia de mago, pode gastar um surto de poder para causar dano de força adicional a esse alvo. O dano adicional é igual à metade do seu nível de mago."],
      [10, 'Durable Magic', 'Magia Durável', "Beginning at 10th level, the magic you channel helps ward off harm. While you maintain concentration on a spell, you have a +2 bonus to AC and all saving throws.", "A partir do 10º nível, a magia que você canaliza ajuda a afastar o perigo. Enquanto mantiver a concentração em uma magia, você tem um bônus de +2 na CA e em todas as salvaguardas."],
      [14, 'Deflecting Shroud', 'Mortalha Defletora', "At 14th level, your Arcane Deflection becomes infused with deadly magic. When you use your Arcane Deflection feature, you can cause magical energy to arc from you. Up to three creatures of your choice that you can see within 60 feet of you each take force damage equal to half your wizard level.", "No 14º nível, sua Deflexão Arcana fica impregnada de magia letal. Quando usa sua característica Deflexão Arcana, você pode fazer com que energia mágica se projete de você. Até três criaturas à sua escolha que você possa ver a até 18 metros de você sofrem, cada uma, dano de força igual à metade do seu nível de mago."],
    ],
    scribes: [
      [2, 'Wizardly Quill', 'Pena Arcana', "2nd-level Order of Scribes feature\n\nAs a bonus action, you can magically create a Tiny quill in your free hand. The magic quill has the following properties:\n\n• The quill doesn’t require ink. When you write with it, it produces ink in a color of your choice on the writing surface.\n\n• The time you must spend to copy a spell into your spellbook equals 2 minutes per spell level if you use the quill for the transcription.\n\n• You can erase anything you write with the quill if you wave the feather over the text as a bonus action, provided the text is within 5 feet of you.\n\ne on the writing surface.\n\nThis quill disappears if you create another one or if you die.", "Característica de 2º nível da Ordem dos Escribas\n\nComo uma ação bônus, você pode criar magicamente uma pena Miúda em sua mão livre. A pena mágica possui as seguintes propriedades:\n\n• A pena não precisa de tinta. Ao escrever com ela, ela produz tinta na cor de sua escolha na superfície de escrita.\n\n• O tempo necessário para copiar uma magia em seu grimório é de 2 minutos por círculo da magia se você usar a pena para a transcrição.\n\n• Você pode apagar qualquer coisa que tenha escrito com a pena se passar a pluma sobre o texto como uma ação bônus, desde que o texto esteja a até 1,5 metro de você.\n\ne na superfície de escrita.\n\nEsta pena desaparece se você criar outra ou se morrer."],
      [2, 'Awakened Spellbook', 'Grimório Desperto', "2nd-level Order of Scribes feature\n\nUsing specially prepared inks and ancient incantations passed down by your wizardly order, you have awakened an arcane sentience within your spellbook.\n\nWhile you are holding the book, it grants you the following benefits:\n\n• You can use the book as a spellcasting focus for your wizard spells.\n\n• When you cast a wizard spell with a spell slot, you can temporarily replace its damage type with a type that appears in another spell in your spellbook, which magically alters the spell’s formula for this casting only. The latter spell must be of the same level as the spell slot you expend.\n\n• When you cast a wizard spell as a ritual, you can use the spell’s normal casting time, rather than adding 10 minutes to it. Once you use this benefit, you can’t do so again until you finish a long rest.\n\nIf necessary, you can replace the book over the course of a short rest by using your Wizardly Quill to write arcane sigils in a blank book or a magic spellbook to which you’re attuned. At the end of the rest, your spellbook’s consciousness is summoned into the new book, which the consciousness transforms into your spellbook, along with all its spells. If the previous book still existed somewhere, all the spells vanish from its pages.", "Característica de 2º nível da Ordem dos Escribas\n\nUsando tintas especialmente preparadas e encantamentos ancestrais transmitidos pela sua ordem de magos, você despertou uma senciência arcana dentro do seu grimório.\n\nEnquanto você estiver segurando o livro, ele concede a você os seguintes benefícios:\n\n• Você pode usar o livro como um foco de conjuração para suas magias de mago.\n\n• Quando você conjurar uma magia de mago com um espaço de magia, você pode substituir temporariamente o tipo de dano dela por um tipo que apareça em outra magia no seu grimório, o que altera magicamente a fórmula da magia apenas para esta conjuração. A outra magia deve ser do mesmo círculo que o espaço de magia que você gastou.\n\n• Quando você conjura uma magia de mago como um ritual, você pode usar o tempo normal de conjuração da magia, em vez de adicionar 10 minutos a ele. Uma vez usado este benefício, você não poderá fazê-lo novamente até terminar um Descanso Longo.\n\nSe necessário, você pode substituir o livro ao longo de um Descanso Curto usando sua Pena do Mago para escrever sigilos arcanos em um livro em branco ou em um grimório mágico com o qual esteja sintonizado. Ao final do descanso, a consciência do seu grimório é invocada para o novo livro, que a consciência transforma no seu grimório, junto com todas as suas magias. Se o livro anterior ainda existia em algum lugar, todas as magias desaparecem de suas páginas."],
      [6, 'Manifest Mind', 'Mente Manifesta', "6th-level Order of Scribes feature\n\nYou can conjure forth the mind of your Awakened Spellbook. As a bonus action while the book is on your person, you can cause the mind to manifest as a Tiny spectral object, hovering in an unoccupied space of your choice within 60 feet of you. The spectral mind is intangible and doesn’t occupy its space, and it sheds dim light in a 10-foot radius. It looks like a ghostly tome, a cascade of text, or a scholar from the past (your choice).\n\nWhile manifested, the spectral mind can hear and see, and it has darkvision with a range of 60 feet. The mind can telepathically share with you what it sees and hears (no action required).\n\nWhenever you cast a wizard spell on your turn, you can cast it as if you were in the spectral mind’s space, instead of your own, using its senses. You can do so a number of times per day equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.\n\nAs a bonus action, you can cause the spectral mind to hover up to 30 feet to an unoccupied space that you or it can see. It can pass through creatures but not objects.\n\nThe spectral mind stops manifesting if it is ever more than 300 feet away from you, if someone casts dispel magic on it, if the Awakened Spellbook is destroyed, if you die, or if you dismiss the spectral mind as a bonus action.\n\nOnce you conjure the mind, you can’t do so again until you finish a long rest, unless you expend a spell slot of any level to conjure it again.", "Característica de 6º nível da Ordem dos Escribas\n\nVocê pode conjurar a mente do seu Grimório Desperto. Como uma ação bônus enquanto o livro estiver consigo, você pode fazer com que a mente se manifeste como um objeto espectral Miúdo, pairando em um espaço desocupado à sua escolha a até 18 metros de você. A mente espectral é intangível e não ocupa seu espaço, emitindo luz fraca em um raio de 3 metros. Ela se parece com um tomo fantasmagórico, uma cascata de texto ou um erudito do passado (à sua escolha).\n\nEnquanto manifestada, a mente espectral pode ouvir e ver, possuindo visão no escuro com alcance de 18 metros. A mente pode compartilhar telepaticamente com você o que vê e ouve (nenhuma ação necessária).\n\nSempre que você conjurar uma magia de mago em seu turno, pode conjurá-la como se estivesse no espaço da mente espectral, em vez do seu, usando os sentidos dela. Você pode fazer isso um número de vezes por dia igual ao seu bônus de proficiência, e recupera todos os usos gastos ao terminar um descanso longo.\n\nComo uma ação bônus, você pode fazer a mente espectral pairar até 9 metros para um espaço desocupado que você ou ela possam ver. Ela pode passar através de criaturas, mas não de objetos.\n\nA mente espectral deixa de se manifestar se estiver a mais de 90 metros de você, se alguém conjurar dissipar magia nela, se o Grimório Desperto for destruído, se você morrer ou se dispensar a mente espectral como uma ação bônus.\n\nDepois de conjurar a mente, você não pode fazê-lo novamente até terminar um descanso longo, a menos que gaste um espaço de magia de qualquer círculo para conjurá-la novamente."],
      [10, 'Master Scrivener', 'Escriba Mestre', "10th-level Order of Scribes feature\n\nWhenever you finish a long rest, you can create one magic scroll by touching your Wizardly Quill to a blank piece of paper or parchment and causing one spell from your Awakened Spellbook to be copied onto the scroll. The spellbook must be within 5 feet of you when you make the scroll.\n\nThe chosen spell must be of 1st or 2nd level and must have a casting time of 1 action. Once in the scroll, the spell’s power is enhanced, counting as one level higher than normal. You can cast the spell from the scroll by reading it as an action. The scroll is unintelligible to anyone else, and the spell vanishes from the scroll when you cast it or when you finish your next long rest.\n\nYou are also adept at crafting spell scrolls, which are described in the treasure chapter of the Dungeon Master’s Guide. The gold and time you must spend to make such a scroll are halved if you use your Wizardly Quill.", "Característica de 10º nível da Ordem dos Escribas\n\nSempre que terminar um Descanso Longo, você pode criar um pergaminho mágico tocando sua Pena do Mago em um pedaço de papel ou pergaminho em branco e fazendo com que uma magia do seu Grimório Desperto seja copiada para o pergaminho. O grimório deve estar a até 1,5 metro de você quando você criar o pergaminho.\n\nA magia escolhida deve ser de 1º ou 2º círculo e deve ter um tempo de conjuração de 1 Ação. Uma vez no pergaminho, o poder da magia é aprimorado, contando como um círculo acima do normal. Você pode conjurar a magia do pergaminho lendo-o como uma Ação. O pergaminho é ininteligível para qualquer outra pessoa, e a magia desaparece do pergaminho quando você a conjura ou quando termina seu próximo Descanso Longo.\n\nVocê também é adepto em criar pergaminhos de magia, descritos no capítulo de tesouros do Livro do Mestre. O ouro e o tempo que você deve gastar para fazer tal pergaminho são reduzidos pela metade se você usar sua Pena do Mago."],
      [14, 'One with the Word', 'Um com a Palavra', "14th-level Order of Scribes feature\n\nYour connection to your Awakened Spellbook has become so profound that your soul has become entwined with it. While the book is on your person, you have advantage on all Intelligence (Arcana) checks, as the spellbook helps you remember magical lore.\n\nMoreover, if you take damage while your spellbook’s mind is manifested, you can prevent all of that damage to you by using your reaction to dismiss the spectral mind, using its magic to save yourself. Then roll 3d6. The spellbook temporarily loses spells of your choice that have a combined spell level equal to that roll or higher. For example, if the roll’s total is 9, spells vanish from the book that have a combined level of at least 9, which could mean one 9th-level spell, three 3rd-level spells, or some other combination. If there aren’t enough spells in the book to cover this cost, you drop to 0 hit points.\n\nUntil you finish 1d6 long rests, you are incapable of casting the lost spells, even if you find them on a scroll or in another spellbook. After you finish the required number of rests, the spells reappear in the spellbook.\n\nOnce you use this reaction, you can’t do so again until you finish a long rest.", "Característica de 14º nível da Ordem dos Escribas\n\nSua conexão com seu Grimório Desperto tornou-se tão profunda que sua alma se entrelaçou a ele. Enquanto o livro estiver com você, você tem Vantagem em todos os testes de Inteligência (Arcanismo), pois o grimório ajuda você a se lembrar do conhecimento mágico.\n\nAlém disso, se sofrer dano enquanto a mente do seu grimório estiver manifestada, você pode evitar todo esse dano contra você usando sua Reação para dispensar a mente espectral, usando a magia dela para se salvar. Em seguida, role 3d6. O grimório perde temporariamente magias à sua escolha cujo círculo combinado de magia seja igual ou superior a essa rolagem. Por exemplo, se o total da rolagem for 9, magias somando pelo menos 9 círculos combinados desaparecem do livro, o que pode significar uma magia de 9º círculo, três magias de 3º círculo ou alguma outra combinação. Se não houver magias suficientes no livro para cobrir esse custo, você cai a 0 Pontos de Vida.\n\nAté que você termine 1d6 Descansos Longos, você é incapaz de conjurar as magias perdidas, mesmo que as encontre em um pergaminho ou em outro grimório. Depois de terminar o número necessário de descansos, as magias reaparecem no grimório.\n\nUma vez que você use esta Reação, você não pode fazê-lo novamente até terminar um Descanso Longo."],
    ],
    chronurgy: [
      [2, 'Chronal Shift', 'Mudança Cronal', "2nd-level Chronurgy Magic feature\n\nYou can magically exert limited control over the flow of time around a creature. As a reaction, after you or a creature you can see withing 30 feet of you makes an attack roll, and ability check, or a saving throw, you can force the creature to reroll. You make this decision after you see whether the roll succeeds or fails. The target must use the result of the second roll.\n\nYou can use this ability twice, and you regain any expended uses when you finish a long rest.", "Característica de 2º nível da Magia de Cronurgia\n\nVocê pode exercer magicamente um controle limitado sobre o fluxo do tempo ao redor de uma criatura. Como uma reação, depois que você ou uma criatura que você possa ver a até 9 metros de você fizer uma jogada de ataque, um teste de atributo ou uma salvaguarda, você pode forçar a criatura a rolar novamente. Você toma essa decisão depois de ver se a jogada foi bem-sucedida ou falhou. O alvo deve usar o resultado da segunda rolagem.\n\nVocê pode usar esta habilidade duas vezes, e recupera quaisquer usos gastos ao terminar um descanso longo."],
      [2, 'Temporal Awareness', 'Consciência Temporal', "2nd-level Chronurgy Magic feature\n\nYou can add your Intelligence modifier to your initiative rolls.", "Característica de 2º nível da Magia de Cronurgia\n\nVocê pode adicionar seu modificador de Inteligência às suas jogadas de iniciativa."],
      [6, 'Momentary Stasis', 'Estase Momentânea', "6th-level Chronurgy Magic feature\n\nAs an action, you can magically force a Large or smaller creature you can see within 60 feet of you to make a Constitution saving throw against your spell save DC. Unless the saving throw is a success, the creature is encased in a field of magical energy until the end of your next turn or until the creature takes any damage. While encased in this way, the creature is incapacitated and has a speed of 0.\n\nYou can use this feature a number of times equal to your Intelligence modifier (a minimum of once). You regain all expended uses when you finish a long rest.", "Característica de 6º nível da Magia de Cronurgia\n\nComo uma ação, você pode forçar magicamente uma criatura Grande ou menor que possa ver a até 18 metros de você a fazer uma salvaguarda de Constituição contra a CD de suas magias. A menos que a salvaguarda seja um sucesso, a criatura fica envolta em um campo de energia mágica até o final do seu próximo turno ou até sofrer qualquer dano. Enquanto estiver envolta dessa forma, a criatura fica incapacitada e tem deslocamento 0.\n\nVocê pode usar esta característica um número de vezes igual ao seu modificador de Inteligência (mínimo de uma vez). Você recupera todos os usos gastos ao terminar um descanso longo."],
      [10, 'Arcane Abeyance', 'Suspensão Arcana', "10th-level Chronurgy Magic feature\n\nWhen you cast a spell using a spell slot of 4th level or lower, you can condense the spell’s magic into a mote. The spell is frozen in time at the moment of casting and held within a gray bead for 1 hour. This bead is a Tiny object with AC 15 and 1 hit point, and it is immune to poison and psychic damage. When the duration ends, or if the bead is destroyed, it vanishes in a flash of light, and the spell is lost.\n\nA creature holding the bead can use its action to release the spell within, whereupon the bead disappears. The spell uses your spell attack bonus and save DC, and the spell treats the creature who released it as the caster for all other purposes.\n\nOnce you create a bead with this feature, you can’t do so again until you finish a short or long rest.", "Característica de 10º nível de Magia da Cronurgia\n\nQuando você conjura uma magia usando um espaço de magia de 4º círculo ou inferior, você pode condensar a magia da magia em uma partícula. A magia é congelada no tempo no momento da conjuração e mantida dentro de uma conta cinzenta por 1 hora. Esta conta é um objeto Miúdo com CA 15 e 1 Ponto de Vida, e é imune a dano de veneno e psíquico. Quando a duração termina, ou se a conta for destruída, ela desaparece em um lampejo de luz, e a magia é perdida.\n\nUma criatura segurando a conta pode usar sua Ação para liberar a magia contida nela, momento em que a conta desaparece. A magia usa seu bônus de ataque mágico e CD de salvaguarda, e a magia trata a criatura que a liberou como o conjurador para todos os outros propósitos.\n\nUma vez que você cria uma conta com esta característica, não pode fazê-lo novamente até terminar um Descanso Curto ou Longo."],
      [14, 'Convergent Future', 'Futuro Convergente', "14th-level Chronurgy Magic feature\n\nYou can peer through possible futures and magically pull one of them into events around you, ensuring a particular outcome. When you are a creature you can see within 60 feet of you makes an attack roll, an ability check, or a saving throw, you can use your reaction to ignore the die roll and decide whether the number rolled is the minimum needed to succeed or one less than that number (your choice).\n\nWhen you use this feature, you gain one level of exhaustion. Only by finishing a long rest can you remove a level of exhaustion gained in this way.", "Característica de 14º nível da Magia de Cronurgia\n\nVocê pode perscrutar futuros possíveis e puxar magicamente um deles para os acontecimentos ao seu redor, garantindo um resultado específico. Quando você ou uma criatura que você possa ver a até 18 metros de você fizer uma jogada de ataque, um teste de atributo ou uma salvaguarda, você pode usar sua reação para ignorar a rolagem do dado e decidir se o número rolado é o mínimo necessário para ter sucesso ou um a menos que esse número (à sua escolha).\n\nQuando você usa esta característica, ganha um nível de exaustão. Apenas ao terminar um descanso longo você pode remover um nível de exaustão ganho dessa maneira."],
    ],
    graviturgy: [
      [2, 'Adjust Density', 'Ajustar Densidade', "2nd-level Graviturgy Magic feature\n\nAs an action, you can magically alter the weight of one object or creature you can see within 30 feet of you. The object or creature must be Large or smaller. The target’s weight is halved or doubled for up to 1 minute or until your concentration ends (as if you were concentrating on a spell).\n\nWhile the weight of a creature is halved by this effect, the creature’s speed increases by 10 feet, it can jump twice as far as normal, and it has disadvantage on Strength checks and Strength saving throws. While the weight of a creature is doubled by this effect, the creature’s speed is reduced by 10 feet, and it has advantage on Strength checks and Strength saving throws.\n\nUpon reaching 10th level in this class, you can target an object or a creature that is Huge or smaller.", "Característica de 2º nível da Magia de Graviturgia\n\nComo uma ação, você pode alterar magicamente o peso de um objeto ou criatura que possa ver a até 9 metros de você. O objeto ou criatura deve ser Grande ou menor. O peso do alvo é reduzido pela metade ou dobrado por até 1 minuto ou até sua concentração terminar (como se estivesse se concentrando em uma magia).\n\nEnquanto o peso de uma criatura estiver reduzido pela metade por este efeito, o deslocamento da criatura aumenta em 3 metros, ela pode saltar duas vezes mais longe que o normal e tem desvantagem em testes de Força e salvaguardas de Força. Enquanto o peso de uma criatura estiver dobrado por este efeito, o deslocamento da criatura é reduzido em 3 metros e ela tem vantagem em testes de Força e salvaguardas de Força.\n\nAo atingir o 10º nível nesta classe, você pode alvejar um objeto ou uma criatura que seja Enorme ou menor."],
      [6, 'Gravity Well', 'Poço Gravitacional', "6th-level Graviturgy Magic feature\n\nYou’ve learned how to manipulate gravity around a living being: whenever you cast a spell on a creature, you can move the target 5 feet to an unoccupied space of your choice if the target is willing to move, the spell hits it with an attack, or it fails a saving throw against the spell.", "Característica de 6º nível da Magia de Graviturgia\n\nVocê aprendeu como manipular a gravidade ao redor de um ser vivo: sempre que conjurar uma magia em uma criatura, você pode mover o alvo 1,5 metro para um espaço desocupado à sua escolha se o alvo estiver disposto a se mover, se a magia atingi-lo com um ataque ou se ele falhar em uma salvaguarda contra a magia."],
      [10, 'Violent Attraction', 'Atração Violenta', "10th-level Graviturgy Magic feature\n\nWhen another creature that you can see within 60 feet of you hits with a weapon attack, you can use your reaction to increase the attack’s velocity, causing the attack’s target to take an extra 1d10 damage of the weapon’s type.\n\nAlternatively, if a creature within 60 feet of you takes damage from a fall, you can use your reaction to increase the fall’s damage by 2d10.\n\nYou can use this feature a number of times equal to your Intelligence modifier (a minimum of once). You regain all expended uses when you finish a long rest.", "Característica de 10º nível da Magia de Graviturgia\n\nQuando outra criatura que você possa ver a até 18 metros de você acertar com um ataque com arma, você pode usar sua reação para aumentar a velocidade do ataque, fazendo com que o alvo do ataque sofra 1d10 de dano extra do tipo da arma.\n\nComo alternativa, se uma criatura a até 18 metros de você sofrer dano de uma queda, você pode usar sua reação para aumentar o dano da queda em 2d10.\n\nVocê pode usar esta característica um número de vezes igual ao seu modificador de Inteligência (mínimo de uma vez). Você recupera todos os usos gastos ao terminar um descanso longo."],
      [14, 'Event Horizon', 'Horizonte de Eventos', "14th-level Graviturgy Magic feature\n\nAs an action, you can magically emit a powerful field of gravitation energy that tugs at other creatures for up to 1 minute or until your concentration ends (as if you were concentrating on a spell). For the duration, whenever a creature hostile to you starts its turn within 30 feet of you, it must make a Strength saving throw against your spell save DC. On a failed save, it takes 2d10 force damage, and its speed is reduced to 0 until the start of its next turn. On a successful save, it takes half as much damage, and every foot it moves this turn costs 2 extra feet of movement.\n\nOnce you use this feature, you can’t do so again until you finish a long rest or until you expend a spell slot of 3rd level or higher on it.", "Característica de 14º nível da Magia de Graviturgia\n\nComo uma ação, você pode emitir magicamente um poderoso campo de energia gravitacional que atrai outras criaturas por até 1 minuto ou até sua concentração terminar (como se estivesse se concentrando em uma magia). Durante a duração, sempre que uma criatura hostil a você iniciar o turno dela a até 9 metros de você, ela deve fazer uma salvaguarda de Força contra a CD de suas magias. Se falhar na salvaguarda, sofre 2d10 de dano de força e seu deslocamento é reduzido a 0 até o início do próximo turno dela. Se obtiver sucesso na salvaguarda, sofre metade desse dano, e cada metro que ela se mover neste turno custa 2 metros extras de movimento.\n\nDepois de usar esta característica, você não pode fazê-lo novamente até terminar um descanso longo ou até gastar um espaço de magia de 3º círculo ou superior nela."],
    ],
  },
};

/** { classe: { subclasse: [{ level, name:{pt,en}, desc:{pt,en} }] } } */
export const EXPANDED_SUBCLASS_FEATURES = Object.fromEntries(Object.entries(F).map(([cls, subs]) => [cls,
  Object.fromEntries(Object.entries(subs).map(([sub, rows]) => [sub, rows.map(([level, en, pt, dEn, dPt]) => ({
    level, name: { pt, en }, desc: { pt: dPt, en: dEn },
  }))])),
]));

// Playtests (UA) e o Cartógrafo só existem no formato 2024 (data/class-options): a ficha 2014
// reaproveita esses mesmos traços, trazendo o nível de entrada da subclasse para o da classe
// em 2014 (druida no 2, clérigo e feiticeiro no 1); os níveis seguintes já coincidem.
const FROM_2024 = [
  ['druid', 'titan', { 3: 2 }],
  ['cleric', 'pestilence', { 3: 1 }],
  ['sorcerer', 'demonic', { 3: 1 }],
  ['fighter', 'hellknight', {}],
  ['artificer', 'cartographer', {}],
];
for (const [cls, sub, remap] of FROM_2024) {
  const levels = CLASS_OPTIONS[cls]?.subclasses?.[sub]?.levels || {};
  const rows = [];
  for (const [lv, node] of Object.entries(levels)) {
    for (const f of node?.features || []) {
      if (!f?.name) continue;
      // Clérigo 2014: a dádiva de Canalizar Divindade chega no 2, não no 1.
      const level = cls === 'cleric' && /Blessing/.test(f.name.en || '') ? 2 : (remap[lv] ?? +lv);
      rows.push({ level, name: { pt: f.name.pt || f.name.en, en: f.name.en || f.name.pt },
        desc: { pt: f.desc?.pt || f.desc?.en || '', en: f.desc?.en || f.desc?.pt || '' } });
    }
  }
  if (rows.length) ((EXPANDED_SUBCLASS_FEATURES[cls] ||= {})[sub] = rows.sort((a, b) => a.level - b.level));
}
export default EXPANDED_SUBCLASS_FEATURES;
